import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Kontrol runtime ACP untuk mengaktifkan pengiriman, memilih backend, membatasi target agen yang diizinkan, dan memilih perilaku proyeksi giliran yang dialirkan.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Agen ACP yang Diizinkan`},help:{"v1-f2mw0d-3a":`Daftar ID agen target ACP yang diizinkan untuk sesi runtime ACP. Jika kosong, tidak ada pembatasan tambahan berdasarkan daftar izin.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Backend ACP`},help:{"v1-1s1l6bz-2v":`ID backend runtime ACP default (misalnya: acpx). Harus cocok dengan backend plugin runtime ACP yang terdaftar.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Agen Default ACP`},help:{"v1-7donnu-2c":`ID agen target ACP cadangan yang digunakan ketika pembuatan sesi ACP tidak menentukan target secara eksplisit.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Pengiriman ACP Diaktifkan`},help:{"v1-1ug9t9m-3w":`Kontrol pengiriman independen untuk giliran sesi ACP (default: true). Atur ke false agar perintah ACP tetap tersedia sambil memblokir eksekusi giliran ACP.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP Diaktifkan`},help:{"v1-1uonl1v-2a":`Kontrol fitur ACP global. Biarkan nonaktif kecuali runtime + kebijakan ACP sudah dikonfigurasi.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Backend Cadangan ACP`},help:{"v1-1wvdifq-5m":`Daftar berurutan ID backend ACP cadangan yang dicoba saat backend utama gagal dengan UNAVAILABLE (misalnya: batas laju / kuota habis). Setiap entri harus cocok dengan backend plugin runtime ACP yang terdaftar.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Perintah Instalasi Runtime ACP`},help:{"v1-1jjuv9m-39":"Perintah instalasi/penyiapan opsional untuk operator yang ditampilkan oleh `/acp install` dan `/acp doctor` saat koneksi backend ACP belum dikonfigurasi."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Streaming ACP`},help:{"v1-1bka5p-2v":`Kontrol proyeksi streaming ACP untuk ukuran potongan, visibilitas metadata, dan perilaku pengiriman tanpa duplikasi.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Mode Pengiriman Streaming ACP`},help:{"v1-19gdmx1-3s":`Gaya pengiriman ACP: live mengalirkan keluaran yang diproyeksikan secara bertahap, final_only menampung semua keluaran ACP yang diproyeksikan hingga peristiwa akhir giliran.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Pencegahan Pengulangan Streaming ACP`},help:{"v1-manh32-3d":`Jika true (default), sembunyikan baris proyeksi status/alat ACP yang berulang dalam satu giliran tanpa mengubah peristiwa ACP mentah.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Visibilitas Tag Streaming ACP`},help:{"v1-1ybhx22-34":`Pengaturan visibilitas pengganti per sessionUpdate untuk proyeksi ACP (misalnya usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agen`},help:{"v1-2rc4v8-55":`Akar konfigurasi runtime agen. Entri sejajar di tingkat akar mengatur infrastruktur dan pengaturan default lintas agen; agents.defaults mengatur perilaku loop agen; entri agen dapat mengganti keduanya jika didukung.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Pengaturan Default Agen`},help:{"v1-1af7k5b-5a":`Pengaturan default bersama yang diwarisi oleh agen kecuali ditimpa pada setiap entri di agents.entries. Gunakan pengaturan default untuk menerapkan perilaku dasar yang konsisten dan mengurangi duplikasi konfigurasi per agen.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Target Pewarisan Autentikasi`},help:{"v1-2d16wl-2x":`Pemilik penyimpanan kredensial yang diwariskan untuk kompatibilitas peningkatan versi hingga kredensial dipindahkan ke masing-masing agen.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Pemilik Pewarisan Autentikasi`},help:{"v1-1a1s7nm-4s":`Agen yang penyimpanan kredensial lamanya tetap menjadi sumber pewarisan setelah penanda default dihentikan. Ditulis secara otomatis selama peningkatan versi jika pemilik sebelumnya bukan main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Karakter Maksimum Bootstrap`},help:{"v1-drlo3i-37":`Jumlah karakter maksimum dari setiap file bootstrap ruang kerja yang disisipkan ke dalam prompt sistem sebelum dipangkas (default: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Total Karakter Maksimum Bootstrap`},help:{"v1-1evwsjb-2c":`Jumlah total karakter maksimum di seluruh file bootstrap ruang kerja yang disisipkan (default: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Pemadatan`},help:{"v1-1qxdwz8-5p":`Perilaku pemadatan saat konteks mendekati batas token, termasuk strategi dan perilaku penyimpanan memori sebelum pemadatan. Gunakan ini saat sesi yang berlangsung lama memerlukan kesinambungan yang stabil dalam jendela konteks yang terbatas.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Pemadatan Otomatis Terintegrasi`},help:{"v1-1et7vwu-5l":`Aktifkan pemadatan otomatis proaktif bawaan (default: true). Atur ke false untuk menghentikan pemadatan bawaan berbasis ambang batas, sambil tetap mempertahankan pemulihan kelebihan kapasitas OpenClaw, pemadatan praproses, dan /compact manual.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Kebijakan Pengenal Pemadatan`},help:{"v1-hby01l-4l":`Kebijakan pelestarian pengenal untuk ringkasan pemadatan: "strict" menambahkan panduan bawaan untuk mempertahankan pengenal opak di awal (default), sedangkan "off" menonaktifkan awalan ini.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Token Terbaru yang Dipertahankan saat Pemadatan`},help:{"v1-tgysub-5h":`Alokasi token minimum yang dipertahankan dari jendela percakapan terbaru selama pemadatan. Gunakan nilai lebih tinggi untuk menjaga kesinambungan konteks terkini dan nilai lebih rendah untuk menyimpan lebih banyak riwayat lama.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Ambang Batas Ukuran Transkrip Aktif untuk Pemadatan`},help:{"v1-u715n1-90":`Ambang batas byte yang memicu pemadatan lokal praproses normal ketika jendela transkrip yang dilihat model (sejak pemadatan atau pengaturan ulang terakhir) mencapai ukuran ini (dalam byte atau string seperti "20mb"). Atur ke 0 atau biarkan tidak diatur untuk menonaktifkannya. Ini juga membatasi transkrip rollout native Codex app-server; utas native yang terlalu besar dimulai ulang dari awal.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Penyimpanan Memori sebelum Pemadatan`},help:{"v1-18q0ve9-55":`Pengaturan penyimpanan memori sebelum pemadatan yang menjalankan penulisan memori oleh agen sebelum pemadatan besar. Biarkan aktif untuk sesi panjang agar konteks penting tersimpan sebelum pemangkasan agresif.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Penyimpanan Memori Saat Pemadatan Diaktifkan`},help:{"v1-9xllgp-5o":`Mengaktifkan penyimpanan memori sebelum runtime melakukan pengurangan riwayat yang lebih besar menjelang batas token. Biarkan aktif kecuali Anda sengaja menonaktifkan efek samping memori di lingkungan dengan sumber daya terbatas.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Ambang Ukuran Transkrip untuk Penyimpanan Memori Saat Pemadatan`},help:{"v1-1rzov1e-93":`Memaksa penyimpanan memori sebelum pemadatan ketika jendela transkrip yang terlihat oleh model mencapai ambang ini (dalam byte atau string seperti "2mb"). Setelah pemadatan, ini mencakup bagian akhir yang dipertahankan dan giliran percakapan berikutnya, bukan riwayat yang dibuang. Gunakan ini untuk mencegah sesi panjang macet meskipun penghitung token belum diperbarui; atur ke 0 untuk menonaktifkannya.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Penggantian Model Penyimpanan Memori Saat Pemadatan`},help:{"v1-1r3ctyu-7w":`Penggantian penyedia/model opsional yang hanya digunakan untuk giliran penyimpanan memori sebelum pemadatan. Atur ke model lokal seperti ollama/qwen3:8b jika ekstraksi memori persisten sebaiknya tidak menggunakan model berbayar dari sesi aktif. Penggantian ini bersifat pasti dan tidak mewarisi rantai model cadangan dari model aktif.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Ambang Lunak Penyimpanan Memori Saat Pemadatan`},help:{"v1-1dqo2l1-5c":`Ambang jarak menuju pemadatan (dalam token) yang memicu penyimpanan memori sebelum pemadatan. Gunakan ambang yang memicu lebih awal untuk penyimpanan persisten yang lebih aman, atau ambang yang lebih dekat ke pemadatan untuk mengurangi frekuensi penyimpanan.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Pemeriksaan Awal Pemadatan di Tengah Giliran`},help:{"v1-am6gbh-6x":`Pemeriksaan awal opsional dalam perulangan alat OpenClaw tertanam yang mendeteksi tekanan konteks setelah hasil alat ditambahkan dan sebelum pemanggilan model berikutnya. Jika diaktifkan, OpenClaw menggunakan kembali mekanisme pemulihan pemeriksaan awal yang ada untuk memangkas hasil alat atau memadatkan konteks sebelum mencoba lagi.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Pemeriksaan Awal Pemadatan di Tengah Giliran Diaktifkan`},help:{"v1-engbwe-5u":`Aktifkan pemeriksaan tekanan konteks terstruktur di tengah giliran untuk perulangan alat OpenClaw tertanam. Nilai bawaan: false. Biarkan nonaktif kecuali sesi panjang yang banyak menggunakan alat melampaui batas konteks sebelum pemadatan normal di akhir giliran dapat berjalan.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Mode Pemadatan`},help:{"v1-1unahwc-76":`Mode strategi pemadatan: "safeguard" (nilai bawaan yang berlaku jika tidak diatur) menerapkan pengaman untuk mempertahankan konteks terbaru, sedangkan "default" menggunakan peringkasan dasar tanpa pengaman tersebut. Atur ke "default" hanya jika peringkasan safeguard menyebabkan masalah pada penyedia Anda.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Penggantian Model Pemadatan`},help:{"v1-cfeys9-6q":`Penyedia/model opsional atau alias tanpa awalan yang telah dikonfigurasi, yang hanya digunakan untuk peringkasan pemadatan. Alias tanpa awalan diresolusikan sebelum permintaan dikirim; ID model literal yang dikonfigurasi diutamakan jika bertabrakan dengan alias. Biarkan tidak diatur agar tetap menggunakan model agen utama.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Beri Tahu Pengguna tentang Pemadatan`},help:{"v1-lvymm8-bv":`Jika diaktifkan, mengirim pemberitahuan singkat tentang pemeliharaan konteks kepada pengguna: saat pemadatan dimulai dan selesai (misalnya, '🧹 Memadatkan konteks...' dan '🧹 Pemadatan selesai'), serta saat upaya penyimpanan memori sebelum pemadatan telah habis sehingga balasan dilanjutkan dalam kondisi terdegradasi (misalnya, '⚠️ Pemeliharaan memori gagal sementara; melanjutkan balasan Anda.'). Dinonaktifkan secara default agar pemeliharaan konteks tetap berjalan tanpa pemberitahuan dan tidak mengganggu.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Bagian Konteks Setelah Pemadatan`},help:{"v1-1n0ln2u-5f":`Nama bagian H2/H3 AGENTS.md yang secara opsional disisipkan kembali setelah pemadatan. Biarkan tidak diatur atau tetapkan [] untuk menonaktifkan penyisipan ulang. Tetapkan secara eksplisit ["Session Startup", "Red Lines"] untuk mengaktifkan pasangan default lama.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Sinkronisasi Indeks Setelah Pemadatan`},help:{"v1-ekpjeq-6l":`Mengontrol mode pengindeksan ulang memori sesi setelah pemadatan: "off", "async", atau "await" (default: "async"). Gunakan "await" untuk memastikan data paling mutakhir, "async" untuk latensi pemadatan yang lebih rendah, dan "off" hanya jika sinkronisasi memori sesi ditangani di tempat lain.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Penyedia Pemadatan`},help:{"v1-kiwk91-86":`ID plugin penyedia pemadatan terdaftar yang digunakan untuk peringkasan. Jika diatur dan penyedia tersebut terdaftar, metode summarize() miliknya dipanggil sebagai pengganti alur pemrosesan summarizeInStages bawaan. Beralih kembali ke peringkasan bawaan jika penyedia gagal. Biarkan tidak diatur untuk menggunakan peringkasan bawaan default.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Penjaga Kualitas Pemadatan`},help:{"v1-u9ognp-4k":`Pengaturan percobaan ulang audit kualitas untuk ringkasan pemadatan safeguard. Mode safeguard mengaktifkan fitur ini secara default; atur enabled: false untuk melewati audit ringkasan dan pembuatan ulang.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Penjaga Kualitas Pemadatan Diaktifkan`},help:{"v1-1xk2vt3-36":`Mengaktifkan audit kualitas ringkasan dan percobaan pembuatan ulang untuk pemadatan safeguard. Default: true dalam mode safeguard.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Percobaan Ulang Maksimum Penjaga Kualitas Pemadatan`},help:{"v1-n7l46y-3y":`Jumlah maksimum percobaan pembuatan ulang setelah audit kualitas ringkasan safeguard gagal. Gunakan nilai kecil untuk membatasi latensi tambahan dan biaya token.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Giliran Terbaru yang Dipertahankan saat Pemadatan`},help:{"v1-y34ihi-5k":`Jumlah giliran pengguna/asisten terbaru yang dipertahankan tanpa perubahan di luar peringkasan safeguard (default: 3). Naikkan nilai ini untuk mempertahankan konteks dialog terbaru secara persis, atau turunkan untuk memaksimalkan penghematan dari pemadatan.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Tingkat Berpikir Pemadatan`},help:{"v1-1vafgaw-g1":`Tingkat penalaran yang hanya digunakan untuk ringkasan pemadatan tertanam OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra", atau "inherit". Nilai default mengikuti preferensi pemadatan penyedia, atau "low" jika tidak tersedia; Ollama lokal native mengutamakan "off". Tetapkan "inherit" untuk menggunakan kembali tingkat sesi. Pengaturan eksplisit mengesampingkan nilai default penyedia, dan tingkat yang dipilih dibatasi sesuai model/runtime pemadatan yang sebenarnya. Pemadatan native Codex app-server mengabaikan pengaturan ini karena permintaan pemadatannya tidak memiliki pengesampingan penalaran per operasi, dan OpenClaw mencatat peringatan.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Batas Waktu Pemadatan (Detik)`},help:{"v1-2bhn29-7m":`Rentang waktu pengaman dalam detik untuk setiap permintaan model pemadatan bawaan (default: 180). Pemadatan bertahap memperbarui rentang waktu setiap kali permintaan berurutan dimulai, sehingga keseluruhan pemadatan dapat memakan waktu lebih lama; pemadatan yang dikelola plugin mendapatkan satu rentang waktu untuk seluruh operasi.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Penyisipan Konteks`},help:{"v1-u18x0-7u":`Mengontrol injeksi berkas bootstrap ruang kerja dalam runtime tersemat: "always" menggunakan injeksi normal (default), "continuation-skip" melewati giliran lanjutan yang memenuhi syarat setelah giliran dengan bootstrap lengkap tercatat, dan "never" menonaktifkan injeksi. Tidak mengontrol persiapan prompt berbasis CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Batas Konteks Default`},help:{"v1-1coeez8-5d":`Alokasi default khusus per konteks agen untuk cuplikan bervolume tinggi tertentu dan blok prompt yang disisipkan. Gunakan ini untuk menyesuaikan ukuran pembacaan/penyisipan yang dibatasi tanpa membuka kembali jalur pemanggilan yang tidak dibatasi.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Jumlah Karakter Maksimum Default memory_get`},help:{"v1-1qb40qv-4v":`Jumlah maksimum karakter default yang dikembalikan oleh memory_get sebelum metadata pemotongan dan pemberitahuan kelanjutan ditambahkan. Tingkatkan nilai ini untuk mendekati ukuran cuplikan lama yang lebih besar, tetapi tetap beri batas.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Jumlah Maksimum Karakter Default Setelah Pemadatan`},help:{"v1-64qo8g-5r":`Jumlah maksimum karakter default yang dipertahankan dari AGENTS.md saat injeksi penyegaran konteks setelah pemadatan. Turunkan nilai ini untuk mengurangi biaya pemulihan setelah pemadatan, atau naikkan untuk agen yang bergantung pada panduan awal yang lebih panjang.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Direktori Kerja`},help:{"v1-1y8wlxn-6a":`Direktori kerja untuk eksekusi balasan agen, terpisah dari inisialisasi ruang kerja dan file memori. cwd khusus agen dan cwd yang ditetapkan saat sesi dibuat diprioritaskan. Mendukung ~ dan jalur relatif; cwd yang berbeda memerlukan eksekusi di luar sandbox.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Model Keputusan`},help:{"v1-7nd7ze-64":`Penyedia/model opsional untuk pilihan bertipe, skor, dan probabilitas boolean. Jika tidak diatur atau kosong, pemanggilan keputusan dinonaktifkan. Plugin yang mendukung fitur ini mengirimkan bukti tugas dalam batas tertentu ke penyedia ini; model obrolan dan utilitas tidak berubah.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`OpenClaw Tertanam`},help:{"v1-1keek32-3k":`Kontrol penguatan keamanan pelaksana OpenClaw tertanam yang mengatur cara pengaturan agen lokal ruang kerja dipercaya dan diterapkan dalam sesi OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Pengalihan Cadangan Kebijakan Siber`},help:{"v1-xvv6wl-2r":`Eskalasi otomatis ke Daybreak untuk penolakan kebijakan siber OpenAI yang aman dicoba ulang di lingkungan eksekusi tertanam.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Jeda Pengalihan Cadangan Kebijakan Siber`},help:{"v1-16smtrl-25":`Durasi target eskalasi yang tidak tersedia dilewati dalam sesi saat ini.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Mode Pengalihan Cadangan Kebijakan Siber`},help:{"v1-rzsd2b-2h":`Aktifkan eskalasi otomatis ("auto", default) atau tetap akhiri proses saat penyedia menolak ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Model Pengalihan Cadangan Kebijakan Siber`},help:{"v1-1aaj8nn-1t":`Target penyedia/model yang digunakan untuk eskalasi kebijakan siber otomatis.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Kontrak Eksekusi OpenClaw Tertanam`},help:{"v1-1fch2ig-66":`Kontrak eksekusi OpenClaw tertanam: "default" mempertahankan perilaku pelaksana standar, sedangkan "strict-agentic" mengaktifkan pelacakan rencana terstruktur dan pemulihan giliran yang tidak terlihat untuk eksekusi keluarga GPT-5 OpenAI/OpenAI Codex yang didukung.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Kebijakan Pengaturan Proyek OpenClaw Tertanam`},help:{"v1-fdyy04-65":'Cara OpenClaw tersemat menangani `.openclaw/settings.json` lokal ruang kerja: "sanitize" (default) menghapus shellPath/shellCommandPrefix, "ignore" menonaktifkan pengaturan proyek sepenuhnya, dan "trusted" menerapkan pengaturan proyek apa adanya.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Flag Agen Eksperimental`},help:{"v1-cvv5cl-2w":`Flag eksperimental untuk pengaturan default agen. Biarkan nonaktif kecuali Anda sengaja menguji fitur pratinjau.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Aktifkan Mode Model Lokal Ringkas (Eksperimental)`},help:{"v1-gj06u6-7b":`Pengaturan pengganti untuk pemecahan masalah tingkat lanjut yang membatasi alat opsional seperti browser, automations, dan message. Nonaktif secara default; runtime lokal yang didukung menggunakan Tool Search otomatis tanpa pembatasan ini. Izin alat eksplisit dan alat pengiriman yang diwajibkan tetap dipertahankan.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Mode Cepat Default Agen`},help:{"v1-zv4y98-2z":`Kebijakan mode cepat default untuk loop agen ("auto", true, atau false). Entri agen individual mengesampingkan kebijakan ini.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Agen Heartbeat`},help:{"v1-1jynxej-3w":`Agen yang bertanggung jawab atas eksekusi heartbeat latar belakang ketika tidak ada konfigurasi heartbeat per agen. Biarkan tidak diatur untuk mempertahankan perutean default yang dikonfigurasi.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Kebijakan Pesan Langsung Heartbeat`},help:{"v1-nhyxa9-41":`Mengontrol apakah pengiriman heartbeat dapat menargetkan percakapan langsung/DM: "allow" (default) mengizinkan pengiriman DM dan "block" mencegah pengiriman ke target langsung.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Batas Waktu Detak Jantung (Detik)`},help:{"v1-1se21py-5f":`Waktu maksimum dalam detik yang diizinkan untuk satu giliran agen detak jantung sebelum dibatalkan. Biarkan tidak diatur untuk menggunakan agents.defaults.timeoutSeconds jika diatur; jika tidak, gunakan interval detak jantung dengan batas maksimum 600 detik.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Jeda Mirip Manusia Maksimum (ms)`},help:{"v1-vnmvli-1m":`Jeda maksimum dalam ms untuk humanDelay khusus (default: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Jeda Mirip Manusia Minimum (ms)`},help:{"v1-5nrtr5-1l":`Jeda minimum dalam ms untuk humanDelay khusus (default: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Mode Jeda Mirip Manusia`},help:{"v1-k7hyg3-1n":`Gaya jeda untuk balasan berbentuk blok ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Dimensi Gambar Maksimum (px)`},help:{"v1-vju8x-2u":`Panjang sisi gambar maksimum dalam piksel saat membersihkan muatan gambar transkrip/hasil alat (default: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Model Gambar Cadangan`},help:{"v1-1kgx5i9-1b":`Model gambar cadangan dalam urutan prioritas (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Model Gambar`},help:{"v1-dstqyh-2c":`Model gambar opsional (provider/model) yang digunakan saat model utama tidak mendukung masukan gambar.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Kualitas Gambar`},help:{"v1-1uyxc5s-6u":`Preferensi kompresi media untuk alat gambar: "auto" menyesuaikan dengan batas penyedia/model dan jumlah gambar, "efficient" menghemat token dan byte, "balanced" mempertahankan keseimbangan saat ini, dan "high" mempertahankan lebih banyak detail untuk tangkapan layar dan gambar dokumen.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Model Cadangan untuk Pembuatan Gambar`},help:{"v1-oljfk4-1m":`Model cadangan untuk pembuatan gambar sesuai urutan (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Model Pembuatan Gambar`},help:{"v1-g4yw0h-2o":`Model pembuatan gambar opsional (provider/model) yang digunakan oleh kapabilitas pembuatan gambar bersama.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Batas Waktu Pembuatan Gambar (ms)`},help:{"v1-9yesfj-31":`Batas waktu permintaan penyedia default dalam milidetik untuk pemanggilan image_generate. timeoutMs per pemanggilan menggantikan nilai ini.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Model Cadangan untuk Pembuatan Musik`},help:{"v1-wyg9xe-1m":`Model cadangan untuk pembuatan musik sesuai urutan (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Model Pembuatan Musik`},help:{"v1-xs1e2h-2o":`Model pembuatan musik opsional (provider/model) yang digunakan oleh kapabilitas pembuatan musik bersama.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Model Cadangan untuk Pembuatan Video`},help:{"v1-wpbf1e-1m":`Model cadangan untuk pembuatan video sesuai urutan (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Model Pembuatan Video`},help:{"v1-hfmlbl-2o":`Model pembuatan video opsional (provider/model) yang digunakan oleh kapabilitas pembuatan video bersama.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Batas Waktu Pembuatan Video (ms)`},help:{"v1-1bqj80s-4i":`Batas waktu permintaan penyedia secara default dalam milidetik untuk panggilan video_generate. timeoutMs per panggilan menggantikan nilai ini, dan nilai ini menggantikan nilai default yang ditetapkan penyedia.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Model Cadangan`},help:{"v1-t4djq2-24":`Model cadangan sesuai urutan (provider/model). Digunakan saat model utama gagal.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Model Utama`},help:{"v1-1i8a1v4-v":`Model utama (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Kebijakan Model`},help:{"v1-z0txb7-2e":`Kebijakan eksplisit untuk penggantian model. Hilangkan kebijakan ini atau biarkan allow kosong untuk mengizinkan model apa pun.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Model yang Diizinkan`},help:{"v1-1fqace-3x":`Referensi penggantian model yang diizinkan. Menerima alias, referensi lengkap "provider/model", dan wildcard penyedia seperti "openai/*". Jika kosong, model apa pun diizinkan.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Model`},help:{"v1-13cvq23-4i":`Katalog model yang dikonfigurasi dan pengaturan per model. Entri menyediakan alias, parameter, metadata runtime, dan penggantian pengaturan Code Mode; entri ini tidak membatasi penggantian model.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Runtime Model Agen Default`},help:{"v1-6km9kx-41":`Kebijakan runtime opsional per model untuk agen default. Gunakan ini untuk pengecualian runtime khusus model, alih-alih menetapkan runtime untuk seluruh agen.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`ID Runtime Model Agen Default`},help:{"v1-1co96w7-4a":`ID runtime model agen default: "openclaw", "auto", ID harness plugin terdaftar seperti "codex", atau alias backend CLI yang didukung seperti "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Mode Kode`},help:{"v1-rsdl5o-6x":`Mode Kode OpenClaw untuk penyedia/model spesifik ini: Aktif memaksanya aktif, Nonaktif menonaktifkannya, dan Default mengikuti tools.codeMode.enabled. Pengaturan aktivasi khusus agen diutamakan. Ini tidak mengubah runtime yang dipilih atau Mode Kode bawaan Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Cakupan Pemilihan Model`},help:{"v1-sj8owq-bl":`Cakupan untuk perintah obrolan dan pembaruan model sesi Gateway tanpa cakupan eksplisit: "session" (default) hanya mengubah sesi saat ini, "agent" juga memperbarui model utama agen tersebut, dan "global" juga memperbarui model cadangan bersama agents.defaults.model. Flag cakupan eksplisit diutamakan; perubahan pada default yang dikonfigurasi memerlukan wewenang pemilik/admin. Pemilih callback Telegram dan TUI lokal tertanam tetap hanya berlaku untuk sesi.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Ukuran Maksimum PDF (MB)`},help:{"v1-1uig1dr-1u":`Ukuran maksimum file PDF dalam megabita untuk alat PDF (default: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Jumlah Halaman Maksimum PDF`},help:{"v1-11na7hp-1y":`Jumlah maksimum halaman PDF yang diproses oleh alat PDF (default: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Model Cadangan PDF`},help:{"v1-89ebd8-19":`Model PDF cadangan sesuai urutan (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Model PDF`},help:{"v1-2ktkxt-2y":`Model PDF opsional (provider/model) untuk alat analisis PDF. Secara default menggunakan imageModel, lalu model sesi.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Direktori Akar Repositori`},help:{"v1-j3sh74-2h":`Direktori akar repositori opsional yang ditampilkan pada baris runtime dalam prompt sistem (menggantikan deteksi otomatis).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Rentang Port Sumber CDP Browser Sandbox`},help:{"v1-1jkowdc-2b":`Daftar izin CIDR opsional untuk lalu lintas CDP masuk di batas kontainer (misalnya 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Jaringan Browser Sandbox`},help:{"v1-8m74ud-5w":`Jaringan Docker untuk kontainer browser sandbox (default: openclaw-sandbox-browser). Gunakan jaringan default khusus atau jaringan bridge kustom; "none" tidak didukung karena kontrol browser memerlukan port CDP yang dipublikasikan.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Izinkan Docker Sandbox Bergabung ke Namespace Kontainer`},help:{"v1-qm39de-4c":`Penggantian pengaturan darurat yang BERBAHAYA untuk mengizinkan mode jaringan Docker sandbox container:<id>. Tindakan ini menggabungkan sandbox ke namespace kontainer lain dan melemahkan isolasi sandbox.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU Docker Sandbox`},help:{"v1-jj0yhw-4k":`Nilai penerusan GPU Docker opsional yang diteruskan ke --gpus, misalnya "all" atau "device=GPU-uuid". Memerlukan runtime host yang kompatibel seperti NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Target Penyimpanan Sesi Lama`},help:{"v1-1xkej6i-2g":`Pemilik untuk kompatibilitas saat peningkatan versi bagi baris main-agent yang telah dihentikan dan penyimpanan sesi lama yang tetap.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Pemilik Penyimpanan Sesi Lama`},help:{"v1-ommm7e-5w":`Agen yang memiliki baris main-agent yang telah dihentikan atau baris tanpa cakupan dalam penyimpanan sesi lama yang tetap setelah penghentian default-marker. Ditulis secara otomatis selama peningkatan versi ketika pemilik sebelumnya bukan main atau bukan satu-satunya agen.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Daftar izin keterampilan default opsional yang diwarisi oleh agen yang tidak menyertakan agents.entries.*.skills. Jangan sertakan untuk mengizinkan keterampilan tanpa batasan, tetapkan [] agar agen yang mewarisinya tidak memiliki keterampilan, dan ingat bahwa agents.entries.*.skills yang ditetapkan secara eksplisit menggantikan default ini, bukan digabungkan dengannya.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Lewati Pembuatan Bootstrap Ruang Kerja`},help:{"v1-kbstgw-5v":`Melewati pembuatan otomatis berkas bootstrap ruang kerja, bukan injeksi berkas yang sudah ada. Untuk runtime tersemat, atur agents.defaults.contextInjection ke "never" untuk menonaktifkan injeksi, kecuali jika pengaturan tersebut ditimpa pada tingkat agen.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`File Bootstrap Opsional yang Dilewati`},help:{"v1-1j2z4yj-4c":`File bootstrap opsional yang tidak boleh dibuat di ruang kerja agen. Nilai yang valid: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md diterima tetapi tidak berpengaruh).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Konteks Awal`},help:{"v1-1ugsihy-5o":`Pengantar giliran pertama yang dikelola runtime untuk "/new" dan "/reset" tanpa argumen. Gunakan ini untuk mengatur apakah file memori harian terbaru dimuat terlebih dahulu ke dalam prompt pertama, alih-alih meminta model memutuskan apa yang perlu dibaca.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Terapkan Konteks Awal Pada`},help:{"v1-wav4a5-36":`Memilih perintah reset tanpa argumen yang mendapatkan konteks awal: sertakan "new", "reset", atau keduanya (default: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Jumlah Hari Memori Harian untuk Konteks Awal`},help:{"v1-4i5xcm-3p":`Jumlah file memori bertanggal yang dimuat, dihitung mundur dari hari ini dalam zona waktu pengguna yang dikonfigurasi (default: 2 untuk hari ini + kemarin).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Aktifkan Konteks Awal`},help:{"v1-1d5vz2u-4i":`Aktifkan pengantar konteks awal untuk reset sesi tanpa argumen (default: true). Nonaktifkan ini untuk kembali ke perilaku yang hanya menggunakan prompt tanpa memori harian yang dimuat oleh runtime.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Byte File Maksimum untuk Konteks Awal`},help:{"v1-11cbian-41":`Jumlah byte maksimum yang diizinkan per file memori harian saat menyusun konteks awal (default: 16384). File yang melebihi batas pembacaan aman ini dilewati.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Karakter File Maksimum untuk Konteks Awal`},help:{"v1-10z53s-2u":`Jumlah karakter maksimum yang dipertahankan dari setiap file memori harian yang dimuat dalam pengantar awal (default: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Total Karakter Maksimum Konteks Awal`},help:{"v1-sf676u-54":`Jumlah karakter maksimum yang dipertahankan dari semua file memori harian yang dimuat dalam pengantar awal (default: 2800). File tambahan dipangkas dari pengantar setelah batas ini tercapai.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Mode Delegasi Subagen`},help:{"v1-pqewbk-5o":`Tingkat penekanan delegasi subagen yang hanya diterapkan melalui prompt. Defaultnya adalah "prefer" dalam sesi utama setiap agen dan "suggest" di sesi lainnya; "prefer" menginstruksikan agen secara tegas untuk mendelegasikan pekerjaan yang tidak sederhana melalui sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Target Agen Sistem`},help:{"v1-1wwimo9-34":`Pengaturan target untuk inferensi agen sistem OpenClaw dan Custodian yang berjalan di latar belakang, serta operasi baca operator tertentu tanpa cakupan khusus.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Pemilik Agen Sistem`},help:{"v1-15rvt92-8c":`Agen yang model dan kredensialnya digunakan untuk konsultasi agen sistem dan Custodian di latar belakang. Juga digunakan ketika models.list, models.authStatus, skills.status, doctor.memory.status, atau perintah CLI infer yang menentukan model atau status autentikasi milik agen tidak menyertakan agentId atau --agent; agentId yang diberikan secara eksplisit dalam permintaan selalu diutamakan.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Interval Mengetik (Detik)`},help:{"v1-1y701ox-42":`Mengontrol interval pembaruan agar indikator mengetik tetap aktif, dalam detik, untuk setiap agen. Tingkatkan nilainya untuk mengurangi frekuensi pembaruan di semua kanal yang mendukung indikator mengetik.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Mode Mengetik`},help:{"v1-m2hvpw-3m":`Mengontrol kapan agen mulai mengetik: "never", "instant", "thinking", atau "message". typingMode per agen menggantikan pengaturan default ini.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Model Utilitas`},help:{"v1-1wg7h1a-7s":`Model opsional berbiaya lebih rendah (provider/model atau alias) untuk tugas internal singkat seperti pembuatan judul dan narasi progres. Jika tidak diatur, model kecil yang dideklarasikan oleh penyedia utama akan digunakan jika tersedia (jika tidak, model utama digunakan); atur ke string kosong untuk menonaktifkan perutean utilitas.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Model Suara Cadangan`},help:{"v1-faazv4-1b":`Model suara cadangan sesuai urutan (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Model Suara`},help:{"v1-1yeh3h4-2t":`Model suara opsional (provider/model) yang digunakan oleh kemampuan ujaran, transkripsi, dan suara waktu nyata.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Batas Waktu Suara (ms)`},help:{"v1-1sbergs-32":`Batas waktu permintaan default ke penyedia dalam milidetik untuk operasi model suara ketika pemanggil mendukung batas waktu.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Ruang kerja`},help:{"v1-1lssx8l-5w":`Ruang kerja default agen untuk file inisialisasi dan memori. Juga digunakan sebagai direktori kerja saat agents.defaults.cwd tidak diatur. Atur ini secara eksplisit saat menjalankan dari wrapper agar resolusi jalur tetap deterministik.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Daftar Agen`},help:{"v1-yurood-5l":`Daftar eksplisit agen yang dikonfigurasi beserta ID dan pengaturan pengganti opsional untuk model, alat, identitas, dan ruang kerja. Pastikan ID tetap stabil dari waktu ke waktu agar pengikatan, persetujuan, dan perutean sesi tetap deterministik.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Runtime Agen Lama`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID Runtime Agen Lama`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Karakter Maksimum Bootstrap Agen`},help:{"v1-rsf1es-4j":`Pengaturan khusus per agen untuk jumlah karakter maksimum setiap file bootstrap ruang kerja yang disisipkan ke dalam prompt sistem agen ini. Jangan isi untuk mewarisi agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Total Karakter Maksimum Bootstrap Agen`},help:{"v1-1bal68p-4y":`Pengaturan khusus per agen untuk jumlah total karakter maksimum di seluruh file bootstrap ruang kerja yang disisipkan ke dalam prompt sistem agen ini. Jangan isi untuk mewarisi agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Penyisipan Konteks Agen`},help:{"v1-1j68ys8-50":`Pengaturan pengganti per agen untuk penyisipan file bootstrap ruang kerja dalam runtime tertanam. Hilangkan untuk mewarisi agents.defaults.contextInjection. Tidak mengontrol penyiapan prompt berbasis CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Batas Konteks Agen`},help:{"v1-f1qxq8-3c":`Pengaturan khusus opsional per agen untuk parameter alokasi konteks terfokus. Kolom yang tidak diisi mewarisi agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Karakter Maksimum memory_get Agen`},help:{"v1-12hlmsv-1v":`Pengaturan khusus per agen untuk alokasi karakter maksimum bawaan memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Karakter Maksimum Agen Setelah Pemadatan`},help:{"v1-15s0npd-1w":`Pengaturan pengganti per agen untuk batas ukuran kutipan AGENTS.md setelah pemadatan.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Direktori Kerja Agen`},help:{"v1-mv43ak-6a":`Direktori kerja untuk eksekusi balasan agen ini. Menggantikan agents.defaults.cwd, tetapi tidak menggantikan cwd yang ditetapkan saat sesi dibuat; file bootstrap dan memori tetap berada di ruang kerja. Mendukung ~ dan jalur relatif; cwd yang berbeda memerlukan eksekusi tanpa sandbox.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Model Keputusan Agen`},help:{"v1-1mih8bf-3j":`Model keputusan per agen. Jika tidak diatur, mewarisi agents.defaults.decisionModel; string kosong menonaktifkan pemanggilan keputusan untuk agen ini.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`OpenClaw Tertanam Agen`},help:{"v1-uoomza-4b":`Pengaturan pengganti opsional per agen untuk OpenClaw tertanam. Gunakan ini untuk mengaktifkan perilaku eksekusi GPT-5 yang lebih ketat bagi agen tertentu tanpa mengubah pengaturan default global.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Kontrak Eksekusi OpenClaw Tertanam Agen`},help:{"v1-1d1jaoi-7k":`Pengaturan pengganti opsional per agen untuk kontrak eksekusi OpenClaw tertanam. Tetapkan "strict-agentic" untuk mengaktifkan pelacakan rencana terstruktur dan pemulihan giliran yang tidak terlihat bagi agen tersebut pada eksekusi keluarga GPT-5 OpenAI/OpenAI Codex yang didukung, atau "default" untuk mewarisi perilaku standar pelaksana.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Flag Eksperimental Agen`},help:{"v1-1r06jov-2a":`Flag eksperimental per agen. Kolom yang tidak disertakan mewarisi agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Mode Model Lokal Ringkas Agen`},help:{"v1-5o3tgx-58":`Pengaturan pengganti untuk pemecahan masalah per agen dalam mode model lokal ringkas. Aktifkan hanya jika pembatasan alat opsional mengatasi kegagalan model yang terbukti, tanpa mengurangi alat untuk semua agen.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Default Mode Cepat Agen`},help:{"v1-1ujydjc-3o":`Default opsional per agen untuk mode cepat ("auto", true, atau false). Berlaku jika tidak ada pengaturan pengganti mode cepat untuk pesan atau sesi.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Kebijakan Pengiriman Langsung Heartbeat`},help:{"v1-11gl9l0-41":`Pengaturan pengganti per agen untuk kebijakan pengiriman heartbeat langsung/DM; gunakan "block" untuk agen yang hanya boleh mengirim peringatan heartbeat ke tujuan non-DM.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Batas Waktu Heartbeat (Detik)`},help:{"v1-kdetv4-6s":`Waktu maksimum per agen dalam detik yang diizinkan untuk satu giliran agen heartbeat sebelum dibatalkan. Biarkan tidak diatur untuk mewarisi batas waktu heartbeat gabungan, lalu agents.defaults.timeoutSeconds jika diatur, atau interval heartbeat yang dibatasi hingga 600 detik jika tidak.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Avatar Identitas`},help:{"v1-pzp9gr-1t":`Avatar agen (jalur relatif terhadap ruang kerja, URL http(s), atau URI data).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Kebijakan Model Agen`},help:{"v1-17d5je8-2r":`Kebijakan penggantian model per agen. Daftar izin yang ditetapkan secara eksplisit menggantikan kebijakan default untuk agen ini.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Model Agen yang Diizinkan`},help:{"v1-v1ueke-5b":`Referensi model pengganti yang diizinkan untuk agen ini. Menerima alias, referensi lengkap "provider/model", dan prefiks dengan wildcard di akhir seperti "provider/*" atau "provider/namespace/*"; jika kosong, model apa pun diizinkan.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Pengaturan Pengganti Model Agen`},help:{"v1-nld1vq-1v":`Pengaturan pengganti katalog model per agen dengan ID provider/model lengkap sebagai kunci.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Runtime Model Agen`},help:{"v1-7b59y-3s":`Kebijakan runtime opsional per model untuk agen ini. Gunakan untuk pengecualian model khusus agen, alih-alih menetapkan runtime untuk seluruh agen.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`ID Runtime Model Agen`},help:{"v1-1ckfc39-46":`ID runtime model per agen: "openclaw", "auto", ID harness plugin terdaftar seperti "codex", atau alias backend CLI yang didukung seperti "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Mode Kode`},help:{"v1-91zu7f-7m":`OpenClaw Code Mode untuk agen ini dan provider/model yang persis sesuai: Aktif memaksanya aktif, Nonaktif menonaktifkannya, dan Default mewarisi pengaturan aktivasi agen, lalu pengaturan pengganti model bersama, lalu tools.codeMode.enabled. Ini tidak mengubah runtime yang dipilih atau Code Mode bawaan Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Default Penalaran Agen`},help:{"v1-13ly0xf-3m":`Visibilitas penalaran default opsional per agen (on|off|stream). Berlaku jika tidak ada pengaturan pengganti penalaran per pesan atau sesi.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Runtime Agen`},help:{"v1-avjgkf-3l":`Deskriptor runtime opsional untuk agen ini. Gunakan embedded untuk eksekusi default OpenClaw atau acp untuk pengaturan default harness ACP eksternal.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Runtime ACP Agen`},help:{"v1-91zvdk-3i":`Pengaturan bawaan runtime ACP untuk agen ini saat runtime.type=acp. Pengaturan pengganti ACP pada tingkat pengikatan tetap diutamakan untuk setiap percakapan.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agen Harness ACP untuk Agen`},help:{"v1-1pm98vp-37":`ID agen harness ACP opsional yang digunakan untuk agen OpenClaw ini (misalnya codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Backend ACP Agen`},help:{"v1-1u3cdsg-2n":`Pengaturan pengganti backend ACP opsional untuk sesi ACP agen ini (menggunakan acp.backend global jika tidak ditentukan).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Direktori Kerja ACP Agen`},help:{"v1-d9p9rf-1t":`Direktori kerja bawaan opsional untuk sesi ACP agen ini.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Mode ACP Agen`},help:{"v1-yatuk4-21":`Mode sesi ACP bawaan opsional untuk agen ini (persistent atau oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Jenis Runtime Agen`},help:{"v1-139fbk6-2r":`Jenis runtime untuk agen ini: "embedded" (runtime bawaan OpenClaw) atau "acp" (pengaturan bawaan harness ACP).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Rentang Sumber CDP Browser Sandbox Agen`},help:{"v1-1q1qyso-1d":`Pengaturan pengganti per agen untuk daftar CIDR sumber CDP yang diizinkan.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Jaringan Browser Sandbox Agen`},help:{"v1-13bdfww-4c":`Pengaturan pengganti per agen untuk jaringan Docker browser sandbox. Gunakan jaringan bridge; "none" tidak didukung karena kontrol browser memerlukan port CDP yang dipublikasikan.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Izinkan Penggabungan Namespace Kontainer Docker Sandbox Agen`},help:{"v1-1xtnseb-2i":`Pengaturan pengganti BERBAHAYA per agen untuk penggabungan namespace kontainer dalam mode jaringan Docker sandbox.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`GPU Docker Sandbox Agen`},help:{"v1-1kek1n2-1t":`Pengaturan pengganti per agen untuk penerusan GPU Docker ke kontainer sandbox.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Filter Keterampilan Agen`},help:{"v1-igchue-6v":`Daftar opsional keterampilan yang diizinkan untuk agen ini. Jika tidak diisi, agen mewarisi agents.defaults.skills jika sudah ditetapkan; jika tidak, keterampilan tetap tidak dibatasi. Tetapkan [] agar tidak ada keterampilan. Daftar eksplisit sepenuhnya menggantikan pengaturan default yang diwarisi, bukan digabungkan dengannya.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Batas Skills Agen`},help:{"v1-1sv10v9-4y":`Pengaturan pengganti opsional per agen untuk alokasi subsistem keterampilan. Gunakan ini saat agen memerlukan alokasi prompt keterampilan yang berbeda tanpa menambahkan jalur batas konteks umum kedua.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Karakter Maksimum Prompt Skills Agen`},help:{"v1-dys63y-52":`Pengaturan khusus per agen untuk batas jumlah karakter prompt Skills. Pengaturan ini memperluas jalur skills.limits.maxSkillsPromptChars yang sudah ada, alih-alih menyalurkan batas yang sama melalui contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Mode Delegasi Subagen`},help:{"v1-1rkgh6p-4s":`Pengaturan khusus per agen untuk tingkat dorongan delegasi subagen. Jika tidak diisi, "prefer" digunakan dalam sesi utama agen ini dan "suggest" di tempat lain; nilai "prefer" atau "suggest" yang ditetapkan secara eksplisit selalu diutamakan.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Tingkat Berpikir Default Agen`},help:{"v1-173q7vy-43":`Tingkat berpikir default opsional per agen. Menggantikan agents.defaults.thinkingDefault untuk agen ini jika tidak ada pengaturan khusus per pesan atau sesi.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Tambahan Daftar Izin Alat Agen`},help:{"v1-1550ui9-46":`Daftar izin alat tambahan per agen yang melengkapi kebijakan global dan profil. Batasi cakupannya agar hak akses agen khusus tidak meluas secara tidak sengaja.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Kebijakan Alat Agen menurut Penyedia`},help:{"v1-mthxv9-4t":`Pengaturan khusus kebijakan alat per agen untuk penyedia tertentu, guna mengontrol kemampuan dalam cakupan kanal. Gunakan ini saat satu agen memerlukan pembatasan yang lebih ketat pada satu penyedia dibandingkan penyedia lainnya.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Mode Kode Agen`},help:{"v1-118t8u5-65":`Opsi Code Mode per agen. Nilai enabled yang ditetapkan secara eksplisit mengesampingkan default aktivasi model bersama dan global; pengaturan codeMode model khusus agen diutamakan. Opsi lainnya digabungkan dengan tools.codeMode tanpa mengubah aktivasi.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Batas Waktu Eksekusi Agen (Detik)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Penggantian Identitas GitHub CLI Agen`},help:{"v1-mjwdh4-38":`Penggantian lengkap identitas GitHub CLI terkelola dan penulis Git untuk agen ini. Jangan sertakan untuk mewarisi identitas sistem.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Email Penulis Git Agen`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Nama Penulis Git Agen`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Jenis Kredensial GitHub Agen`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Versi Profil GitHub Agen`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Daftar Tindakan Pesan yang Diizinkan untuk Agen`},help:{"v1-1g5gov3-67":`Daftar tindakan pesan yang diizinkan per agen untuk alat message. Tetapkan daftar minimal seperti ["send"] untuk agen sandbox publik agar tindakan membaca, mengedit, menghapus, memberi reaksi, dan tindakan pesan khusus penyedia lainnya tetap tersembunyi dan diblokir.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Perpesanan Lintas Konteks Agen (Lintas Penyedia)`},help:{"v1-pehesn-49":`Pengaturan khusus per agen untuk pengiriman lintas penyedia. Mewarisi pengaturan global (default: true). Atur ke false untuk memblokir pengiriman pesan lintas penyedia bagi agen ini.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Perpesanan Lintas Konteks Agen (Penyedia yang Sama)`},help:{"v1-s9u09h-4t":`Pembatas pengiriman pesan per agen ke percakapan lain pada penyedia yang sama. Atur pengaturan ini dan allowAcrossProviders ke false untuk agen publik yang hanya boleh mengirim pesan dalam percakapan saat ini.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Profil Alat Agen`},help:{"v1-1du76ix-57":`Pengaturan pengganti per agen untuk pemilihan profil alat saat satu agen memerlukan kemampuan dasar yang berbeda. Gunakan seperlunya agar perbedaan kebijakan antaragen tetap disengaja dan dapat ditinjau.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Kawanan Agen`},help:{"v1-420ljs-2c":`Pengaturan pengganti kawanan per agen. Nilainya digabungkan dengan konfigurasi tools.swarm tingkat teratas dan diutamakan.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Mode Mengetik Agen`},help:{"v1-oxir52-2e":`Menggantikan kebijakan default untuk mulai mengetik bagi satu agen tanpa mengubah agen lain.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Model Utilitas Agen`},help:{"v1-1v9oskz-2z":`Pengaturan pengganti model utilitas opsional per agen untuk tugas internal singkat. Menggantikan agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Generasi Kepemilikan Agen`},help:{"v1-m2hp61-8g":`Penanda generasi kepemilikan multiagen yang persisten. "explicit" berarti saluran latar belakang, heartbeat, konsultasi agen sistem, Talk, cron, dan operasi CLI langsung harus menentukan pemilik khusus antarmuka atau memblokir operasi jika gagal. OpenClaw menetapkan penanda ini secara otomatis saat membuat atau memigrasikan armada; abaikan untuk agen tunggal.`}},approvals:{label:{"v1-1m405m7-9":`Persetujuan`},help:{"v1-4y3in-5w":`Kontrol perutean persetujuan untuk meneruskan permintaan persetujuan exec dan plugin ke tujuan chat di luar sesi asal. Biarkan kontrol ini dinonaktifkan kecuali operator perlu melihat persetujuan secara eksplisit di luar sesi.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Penerusan Persetujuan Exec`},help:{"v1-1r2mozk-5v":`Mengelompokkan perilaku penerusan persetujuan exec, termasuk pengaktifan, mode perutean, filter, dan target eksplisit. Konfigurasikan di sini jika permintaan persetujuan harus menjangkau kanal operasional, bukan hanya utas asal.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Filter Agen untuk Persetujuan`},help:{"v1-xbuhd3-5i":'Daftar opsional berisi ID agen yang diizinkan untuk penerusan persetujuan, misalnya `["primary", "ops-agent"]`. Gunakan ini untuk membatasi cakupan penerusan dan menghindari pengiriman notifikasi ke kanal untuk agen yang tidak terkait.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Teruskan Persetujuan Exec`},help:{"v1-1t0whe8-5s":`Mengaktifkan penerusan permintaan persetujuan exec ke tujuan pengiriman yang dikonfigurasi (default: false). Biarkan dinonaktifkan dalam konfigurasi berisiko rendah dan aktifkan hanya jika pemberi persetujuan manusia memerlukan permintaan yang terlihat di kanal.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Mode Penerusan Persetujuan`},help:{"v1-1dedfo4-69":`Mengontrol tujuan pengiriman permintaan persetujuan: "session" menggunakan chat asal, "targets" menggunakan target yang dikonfigurasi, dan "both" mengirim ke kedua jalur. Gunakan "session" sebagai pengaturan dasar dan perluas hanya jika alur kerja operasional memerlukan redundansi.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Filter Sesi untuk Persetujuan`},help:{"v1-smeg8e-5u":'Filter kunci sesi opsional yang dicocokkan sebagai substring atau pola bergaya regex, misalnya `["discord:", "^agent:ops:"]`. Gunakan pola yang spesifik agar hanya konteks persetujuan yang dimaksud yang diteruskan ke tujuan bersama.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Target Penerusan Persetujuan`},help:{"v1-17ah848-5u":`Target pengiriman eksplisit yang digunakan saat mode penerusan menyertakan target, masing-masing dengan detail kanal dan tujuan. Batasi daftar target sesuai prinsip hak akses minimum dan validasi setiap tujuan sebelum mengaktifkan penerusan secara luas.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`ID Akun Target Persetujuan`},help:{"v1-16zopng-5e":`Pemilih akun opsional untuk pengaturan kanal multiakun saat persetujuan harus dirutekan melalui konteks akun tertentu. Gunakan ini hanya jika kanal target memiliki beberapa identitas yang dikonfigurasi.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Kanal Target Persetujuan`},help:{"v1-ji1igl-59":`ID kanal/penyedia yang digunakan untuk mengirim persetujuan yang diteruskan, seperti discord, slack, atau ID kanal plugin. Gunakan hanya ID kanal yang valid agar persetujuan tidak gagal tanpa pemberitahuan akibat rute yang tidak dikenal.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`ID Utas Target Persetujuan`},help:{"v1-1axynw7-59":`Target utas/topik opsional untuk kanal yang mendukung pengiriman persetujuan yang diteruskan melalui utas. Gunakan ini agar lalu lintas persetujuan tetap berada di utas operasional, bukan di kanal utama.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Tujuan Target Persetujuan`},help:{"v1-1ijng7e-5n":`Pengidentifikasi tujuan di dalam kanal target (ID kanal, ID pengguna, atau akar utas, bergantung pada penyedia). Verifikasi maknanya untuk setiap penyedia karena format tujuan berbeda antar integrasi kanal.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Penerusan Persetujuan Plugin`},help:{"v1-1m6pzxv-6b":`Mengelompokkan perilaku penerusan persetujuan plugin, termasuk pengaktifan, mode perutean, filter, dan target eksplisit. Terpisah dari penerusan persetujuan exec. Konfigurasikan di sini jika permintaan persetujuan plugin harus sampai ke kanal operasional.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Filter Agen untuk Persetujuan Plugin`},help:{"v1-jb1bra-4b":'Daftar izin opsional berisi ID agen yang memenuhi syarat untuk penerusan persetujuan plugin, misalnya `["primary", "ops-agent"]`. Gunakan ini untuk membatasi cakupan dampak penerusan.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Teruskan Persetujuan Plugin`},help:{"v1-1ntctaf-3v":`Mengaktifkan penerusan permintaan persetujuan plugin ke tujuan pengiriman yang dikonfigurasi (default: false). Terpisah dari approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Mode Penerusan Persetujuan Plugin`},help:{"v1-1h62vy4-3z":`Mengontrol tujuan pengiriman permintaan persetujuan plugin: "session" menggunakan percakapan asal, "targets" menggunakan target yang dikonfigurasi, dan "both" mengirim ke kedua jalur.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Filter Sesi untuk Persetujuan Plugin`},help:{"v1-1eppxmt-57":'Filter kunci sesi opsional yang dicocokkan sebagai substring atau pola bergaya regex, misalnya `["discord:", "^agent:ops:"]`. Gunakan pola yang spesifik agar hanya konteks persetujuan yang dimaksud yang diteruskan.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Target Penerusan Persetujuan Plugin`},help:{"v1-o92qze-3k":`Target pengiriman eksplisit yang digunakan saat mode penerusan persetujuan plugin mencakup target, masing-masing dengan detail kanal dan tujuan.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`ID Akun Target Persetujuan Plugin`},help:{"v1-1wf3lqn-3j":`Pemilih akun opsional untuk pengaturan kanal multiakun saat persetujuan plugin harus dirutekan melalui konteks akun tertentu.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Kanal Target Persetujuan Plugin`},help:{"v1-1mzhzi9-34":`ID kanal/penyedia yang digunakan untuk mengirim persetujuan plugin yang diteruskan, seperti discord, slack, atau ID kanal plugin.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`ID Utas Target Persetujuan Plugin`},help:{"v1-1scaw9c-2v":`Target utas/topik opsional untuk kanal yang mendukung pengiriman persetujuan plugin yang diteruskan melalui utas.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Tujuan Target Persetujuan Plugin`},help:{"v1-sh5te1-31":`Pengidentifikasi tujuan di dalam kanal target (ID kanal, ID pengguna, atau akar utas, bergantung pada penyedia).`}},attachments:{label:{"v1-8925gh-b":`Lampiran`},help:{"v1-1xvgkss-40":`Perilaku retensi tingkat atas yang berlaku bersama untuk penyedia dan alat yang menyimpan media secara persisten. Gunakan ttlHours saat media sementara secara umum perlu dibersihkan dalam batas waktu tertentu.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`TTL Retensi Lampiran (jam)`},help:{"v1-1g90day-9e":`Jangka waktu retensi opsional dalam jam untuk media tersimpan yang ditangani oleh pembersihan mtime umum. Biarkan tidak diatur untuk menonaktifkan pembersihan tersebut, atau tetapkan nilai seperti 24 (1 hari) atau 168 (7 hari) untuk menghapus media sementara yang lebih lama secara berkala. Media keluar yang dikelola (lampiran yang dihasilkan dari obrolan) dikecualikan dan mengikuti kebijakan retensinya sendiri yang mempertimbangkan SQLite dan transkrip.`}},audio:{label:{"v1-11wczsp-5":`Audio`}},auth:{label:{"v1-5xz433-4":`Autentikasi`},help:{"v1-1eu3aud-5c":`Akar profil autentikasi yang digunakan untuk kredensial penyedia multiprofil dan urutan peralihan cadangan berdasarkan masa tunggu. Jaga agar profil tetap minimal dan eksplisit sehingga perilaku peralihan cadangan otomatis tetap dapat diaudit.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Urutan Profil Autentikasi`},help:{"v1-1x6kknp-1w":`ID profil autentikasi yang diurutkan per penyedia (digunakan untuk peralihan cadangan otomatis).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Profil Autentikasi`},help:{"v1-kzoqcn-1j":`Profil autentikasi bernama (penyedia + mode + email opsional).`}},bindings:{label:{"v1-1hcih9f-8":`Pengikatan`},help:{"v1-y7hrzb-4i":`Aturan pengikatan tingkat teratas untuk perutean dan kepemilikan percakapan ACP persisten. Gunakan type=route untuk perutean normal dan type=acp untuk pengikatan harness ACP persisten.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Pengaturan Pengganti Pengikatan ACP`},help:{"v1-1t4lisi-44":`Pengaturan pengganti ACP opsional per pengikatan untuk bindings[].type=acp. Lapisan ini menggantikan nilai default agents.entries.*.runtime.acp untuk percakapan yang cocok.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend Pengikatan ACP`},help:{"v1-rsrbkp-2x":`Pengaturan pengganti backend ACP untuk pengikatan ini (menggunakan backend ACP runtime agen sebagai cadangan, lalu acp.backend global).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Direktori Kerja Pengikatan ACP`},help:{"v1-ngpkj0-1y":`Penggantian direktori kerja untuk sesi ACP yang dibuat dari pengikatan ini.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Label Pengikatan ACP`},help:{"v1-azce82-23":`Label yang mudah dipahami untuk status/diagnostik ACP dalam percakapan yang terikat ini.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Mode Pengikatan ACP`},help:{"v1-cgq8xv-1v":`Penggantian mode sesi ACP untuk pengikatan ini (persistent atau oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`ID Agen Pengikatan`},help:{"v1-17ra0cl-4m":`ID agen tujuan yang menerima lalu lintas saat aturan pencocokan pengikatan terkait terpenuhi. Gunakan hanya ID agen valid yang telah dikonfigurasi agar perutean tidak gagal saat dijalankan.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Aturan Pencocokan Pengikatan`},help:{"v1-sc1w2e-51":`Objek aturan pencocokan untuk menentukan kapan pengikatan berlaku, termasuk kanal dan batasan akun/peer opsional. Batasi cakupan aturan untuk menghindari pengambilalihan oleh agen secara tidak sengaja di berbagai konteks.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`ID Akun Pengikatan`},help:{"v1-1d209g7-56":`Pemilih akun opsional untuk konfigurasi kanal multiakun agar pengikatan hanya berlaku pada satu identitas. Gunakan ini saat rute memerlukan pembatasan cakupan akun, dan biarkan tidak diatur jika tidak diperlukan.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Kanal Pengikatan`},help:{"v1-d22m5-54":"Pengenal kanal/penyedia tempat pengikatan ini berlaku, seperti `telegram`, `discord`, atau ID kanal plugin. Gunakan kunci kanal yang dikonfigurasi secara persis agar evaluasi pengikatan berfungsi dengan andal."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`ID Guild Pengikatan`},help:{"v1-jzzfj1-4x":`Batasan ID guild/server bergaya Discord yang bersifat opsional untuk evaluasi pengikatan dalam penerapan multiserver. Gunakan ini jika pengenal rekan yang sama dapat muncul di guild yang berbeda.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Pencocokan Rekan Pengikatan`},help:{"v1-gcjxff-4i":`Pencocok rekan opsional untuk percakapan tertentu, termasuk jenis dan ID rekan. Gunakan ini jika hanya satu target percakapan langsung/grup/kanal yang harus ditetapkan ke agen.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`ID Rekan Pengikatan`},help:{"v1-86fbh7-4b":`Pengenal percakapan yang digunakan untuk pencocokan rekan, seperti ID obrolan, ID kanal, atau ID grup dari penyedia. Pastikan nilainya persis sama agar pencocokan tidak gagal tanpa pemberitahuan.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Jenis Rekan Pengikatan`},help:{"v1-uufscp-4x":`Jenis percakapan rekan: "direct", "group", "channel", atau nilai lama "dm" (alias untuk direct yang tidak lagi disarankan). Utamakan "direct" untuk konfigurasi baru dan pastikan jenisnya sesuai dengan semantik kanal.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Peran Pengikatan`},help:{"v1-6s891m-4k":`Daftar filter berbasis peran opsional yang digunakan oleh penyedia yang menyertakan peran dalam konteks obrolan. Gunakan ini untuk mengarahkan lalu lintas dari peran berhak istimewa atau peran operasional ke agen khusus.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`ID Tim Pengikatan`},help:{"v1-hh9ps2-48":`Batasan ID tim/ruang kerja opsional yang digunakan oleh penyedia yang mengelompokkan obrolan dalam cakupan tim. Tambahkan ini jika Anda perlu membatasi pengikatan pada satu konteks ruang kerja.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Sesi Pengikatan`},help:{"v1-x325l2-4v":`Penggantian pengaturan sesi rute opsional untuk percakapan yang cocok dengan pengikatan ini. Gunakan ini jika rute tertentu harus tetap menggunakan agen yang sama, tetapi mengisolasi kesinambungan sesi secara berbeda.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Cakupan DM Sesi Pengikatan`},help:{"v1-10sg3xw-4s":`Penggantian cakupan sesi DM opsional untuk pengikatan rute ini. Misalnya, tetap gunakan session.dmScope="main" secara global sambil menggunakan "per-account-channel-peer" untuk rekan percakapan langsung tertentu.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Cakupan Grup Sesi Pengikatan`},help:{"v1-1ys2u7k-6n":`Penggantian cakupan sesi grup/kanal opsional untuk pengikatan rute ini. "per-group" menjaga ruang yang cocok tetap terpisah dan dipantau di latar belakang oleh sesi utama agen tanpa bergantung pada dmScope; "main" menggabungkan konteksnya ke sesi utama dan tidak memerlukan pemantauan.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Jenis Pengikatan`},help:{"v1-172mhtk-3o":`Jenis pengikatan. Gunakan "route" (atau hilangkan untuk entri rute lama) untuk perutean normal, dan "acp" untuk pengikatan percakapan ACP persisten.`}},broadcast:{label:{"v1-awqjh0-j":`Utas Grup Agen`},help:{"v1-1tz72sr-6b":`Gunakan utas grup agen untuk menjalankan beberapa agen yang telah dikonfigurasi dalam satu percakapan masuk, masing-masing dalam sesinya sendiri. Entri dengan penanda kanal mendukung putaran tindak lanjut yang dibatasi; array peer WhatsApp lama tetap menggunakan perilaku satu kali proses.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Peserta dan Opsi Grup Agen`},help:{"v1-1b63zmt-7d":`Gunakan ID peer dengan penanda kanal (misalnya "telegram:-100123") untuk mengonfigurasi array ID agen atau objek berskema ketat dengan agents, mentionGating, maxRounds, dan maxTurns. Entri dengan penanda kanal diprioritaskan daripada kunci peer WhatsApp lama dan mengizinkan maksimal 16 agen.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Peserta Grup Agen`},help:{"v1-g5o0ky-43":`ID agen peserta dari agents.entries (maksimal: 16). Setiap peserta menggunakan sesinya sendiri untuk kanal, akun, percakapan, dan utas ini.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Jumlah Putaran Maksimum Grup Agen`},help:{"v1-i6v4jc-5a":`Jumlah putaran maksimum per pesan masuk, termasuk putaran awal (bilangan bulat: 1–4, default: 1). Putaran lanjutan membagikan balasan peserta lain dalam batas tertentu dengan atribusi, dan berhenti ketika semua peserta memilih untuk melewati giliran.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Jumlah Giliran Maksimum Grup Agen`},help:{"v1-1kiv8dy-72":`Jumlah giliran peserta maksimum per pesan masuk di seluruh putaran (bilangan bulat: 1–32, default: agents.length). Slot dicadangkan sebelum pengiriman paralel; batas ini berlaku untuk giliran agen, bukan potongan pesan fisik atau pengiriman alat. Kuota tidak dilanjutkan setelah mulai ulang.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Pemilihan Grup Agen Berdasarkan Sebutan`},help:{"v1-uay9zu-5u":`Pilih hanya peserta yang secara eksplisit disebut dengan @ jika ada yang cocok; jika tidak, jalankan semua peserta (default: true). Nama tanpa @ atau emoji tidak digunakan untuk memilih peserta. Daftar izin kanal dan aturan penerimaan tetap berlaku.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Strategi Grup Agen`},help:{"v1-p4k9hu-4q":`Urutan eksekusi peserta: "parallel" (default) menjalankan agen secara bersamaan, sedangkan "sequential" menjalankannya sesuai urutan yang dikonfigurasi. Setiap putaran diselesaikan sebelum putaran berikutnya dimulai.`}},browser:{label:{"v1-13dzmen-7":`Browser`},help:{"v1-5b74wi-5l":`Kontrol runtime browser untuk koneksi CDP lokal atau jarak jauh, perutean profil, dan perilaku tangkapan layar/snapshot. Pertahankan pengaturan default kecuali alur kerja otomatisasi Anda memerlukan pengaturan transport browser khusus.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Izinkan Impor Profil Sistem`},help:{"v1-1lsvlxw-5w":`Mengizinkan host macOS mengimpor cookie dari profil sistem lokal browser keluarga Chrome ke profil browser OpenClaw terkelola. Nonaktifkan untuk mencegah impor cookie profil browser dan permintaan persetujuan macOS Keychain yang menyertainya.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Mode Browser Hanya Hubungkan`},help:{"v1-xaw7xm-4s":`Membatasi mode browser agar hanya terhubung ke browser yang sudah berjalan tanpa memulai proses browser lokal. Gunakan jika semua sesi browser dikelola secara eksternal oleh penyedia CDP jarak jauh.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`URL CDP Browser`},help:{"v1-2n72jb-65":`URL endpoint CDP/DevTools yang digunakan untuk terhubung ke instans browser yang dikelola secara eksternal. Gunakan untuk host browser terpusat, tunnel, atau koneksi ke sesi yang sudah ada, dan batasi akses URL hanya melalui jalur jaringan tepercaya.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Profil Default Browser`},help:{"v1-a6xo96-52":`Nama profil browser default yang dipilih saat pemanggil tidak memilih profil secara eksplisit. Gunakan profil stabil dengan hak akses terbatas sebagai default untuk mengurangi penggunaan status lintas konteks yang tidak disengaja.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Browser Diaktifkan`},help:{"v1-19qr4oj-56":`Mengaktifkan integrasi kemampuan browser di Gateway agar alat browser dan alur kerja berbasis CDP dapat berjalan. Nonaktifkan saat otomatisasi browser tidak diperlukan untuk mengurangi permukaan serangan dan beban saat memulai.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Evaluasi Browser Diaktifkan`},help:{"v1-1oa79mq-59":`Mengaktifkan fungsi bantu evaluasi di sisi browser untuk kemampuan evaluasi skrip saat runtime jika didukung. Biarkan nonaktif kecuali alur kerja Anda memerlukan fungsi evaluasi di luar snapshot/navigasi.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Path File Eksekusi Browser`},help:{"v1-1plb4ki-6i":`Path file eksekusi browser yang ditentukan secara eksplisit jika penemuan otomatis tidak memadai untuk lingkungan host Anda. Gunakan path absolut yang stabil, atau path yang dimulai dengan ~ untuk direktori beranda OS Anda, agar perilaku peluncuran tetap konsisten setiap kali dimulai ulang.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Relai Ekstensi Browser`},help:{"v1-6ywlwr-4e":`Pengaturan kompatibilitas autentikasi relai ekstensi Chrome. Pertahankan masa dukungan versi lama hanya selama ekstensi lama yang dipasangkan atau klien CDP eksternal masih memerlukannya.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Izinkan Autentikasi Relai Browser Versi Lama`},help:{"v1-pj2e90-63":`Menerima sementara autentikasi relai versi lama berupa Bearer, Basic, dan token-subprotocol. Default: true selama satu periode migrasi. Tetapkan ke false setelah semua ekstensi dan klien CDP eksternal menggunakan Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Mode Headless Browser`},help:{"v1-1rswq8j-5a":`Memaksa browser diluncurkan dalam mode headless saat peluncur lokal memulai instans browser. Biarkan mode headless aktif untuk lingkungan server dan nonaktifkan hanya jika debugging memerlukan antarmuka yang terlihat.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Mode Browser Tanpa Sandbox`},help:{"v1-slntux-4w":`Menonaktifkan flag isolasi sandbox Chromium untuk lingkungan tempat sandbox gagal saat dijalankan. Sebisa mungkin, biarkan opsi ini nonaktif karena perlindungan isolasi proses akan berkurang.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Profil Browser`},help:{"v1-1x8lf05-51":`Peta koneksi profil browser bernama yang digunakan untuk perutean eksplisit ke port atau URL CDP dengan metadata opsional. Gunakan nama profil yang konsisten dan hindari definisi endpoint yang tumpang tindih.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Mode Hanya Hubungkan untuk Profil Browser`},help:{"v1-2b5zs0-5a":`Pengaturan pengganti per profil untuk mode hanya hubungkan, yang melewati peluncuran browser lokal dan hanya menghubungkan ke endpoint CDP yang sudah ada. Berguna ketika satu profil dikelola secara eksternal sementara profil lainnya diluncurkan secara lokal.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Port CDP Profil Browser`},help:{"v1-gx1yiq-49":`Port CDP lokal per profil yang digunakan saat menghubungkan ke instans browser melalui port, bukan URL. Gunakan port unik untuk setiap profil agar tidak terjadi konflik koneksi.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`URL CDP Profil Browser`},help:{"v1-x491r0-64":`URL endpoint CDP/DevTools per profil yang digunakan untuk perutean browser secara eksplisit berdasarkan nama profil. Gunakan ini untuk host CDP jarak jauh, terowongan, atau profil sesi yang sudah ada yang harus terhubung melalui endpoint Chrome DevTools yang sedang berjalan.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Driver Profil Browser`},help:{"v1-17byyx6-5r":`Mode driver browser per profil. Gunakan "openclaw" (atau "clawd" versi lama) untuk profil berbasis CDP, "existing-session" untuk koneksi Chrome DevTools MCP, atau "extension" untuk relai ekstensi Chrome yang terautentikasi.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Jalur Eksekutabel Profil Browser`},help:{"v1-29azyv-4w":`Jalur eksekutabel browser per profil untuk profil browser terkelola yang dijalankan secara lokal. Menggantikan browser.executablePath dan menerima jalur yang diawali dengan ~ untuk direktori beranda OS.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Mode Tanpa Antarmuka Profil Browser`},help:{"v1-p4jtgv-4u":`Pengaturan pengganti mode tanpa antarmuka per profil untuk instans browser yang dijalankan secara lokal. Gunakan ini jika satu profil harus tetap berjalan tanpa antarmuka tanpa memaksakan browser.headless untuk semua profil lainnya.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Argumen Chrome MCP Profil Browser`},help:{"v1-rc45ke-5g":`Argumen tambahan Chrome DevTools MCP per profil untuk koneksi existing-session, seperti --no-usage-statistics. Argumen endpoint di sini menggantikan koneksi otomatis bawaan atau pemilihan URL browser.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Perintah Chrome MCP Profil Browser`},help:{"v1-1xpty8o-2h":`Perintah Chrome DevTools MCP per profil untuk koneksi existing-session. Nilai defaultnya adalah npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Direktori Data Pengguna Profil Browser`},help:{"v1-5xvgex-9h":`Direktori data pengguna Chromium per profil untuk menghubungkan sesi yang sudah ada melalui Chrome DevTools MCP. Gunakan ini untuk Brave, Edge, Chromium, atau profil Chrome non-default ketika jalur koneksi otomatis bawaan akan memilih direktori data browser yang salah pada host atau node browser yang dipilih. Path yang diawali dengan ~ diperluas menjadi direktori beranda OS.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Pengaturan Default Snapshot Browser`},help:{"v1-v19wdy-4y":`Konfigurasi pengambilan snapshot default yang digunakan ketika pemanggil tidak memberikan opsi snapshot secara eksplisit. Sesuaikan ini agar perilaku pengambilan konsisten di seluruh kanal dan jalur otomatisasi.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Mode Snapshot Browser`},help:{"v1-joeyxp-5c":`Mode ekstraksi snapshot default yang mengontrol cara konten halaman diubah untuk diproses oleh agen. Pilih mode yang menyeimbangkan keterbacaan, ketepatan, dan penggunaan token untuk alur kerja Anda.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Kebijakan SSRF Browser`},help:{"v1-1qbp9im-5e":`Pengaturan perlindungan terhadap pemalsuan permintaan sisi server untuk jalur pengambilan browser/jaringan yang dapat menjangkau host internal. Pertahankan pengaturan default yang ketat di lingkungan produksi dan hanya izinkan target yang disetujui secara eksplisit.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Nama Host yang Diizinkan untuk Browser`},help:{"v1-1rng39-2k":`Nama host persis atau literal IP yang diizinkan oleh pemeriksaan kebijakan SSRF browser. Batasi daftar ini seminimal mungkin.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Izinkan Rentang Lokal Unik IPv6 untuk Browser`},help:{"v1-1glx5cy-2c":`Izinkan Alamat Lokal Unik IPv6 (fc00::/7) untuk lingkungan proksi IP palsu yang tepercaya.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Izinkan Rentang Tolok Ukur RFC 2544 di Browser`},help:{"v1-10ateu3-2i":`Izinkan IP dalam rentang tolok ukur RFC 2544 (198.18.0.0/15) untuk lingkungan proksi IP palsu yang tepercaya.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Nama Host yang Diblokir di Browser`},help:{"v1-nug0we-6k":`Pola nama host yang ditolak sebelum pemeriksaan DNS dan aturan izin, bahkan saat akses jaringan privat diaktifkan. Mendukung nama host persis dan "*.example.com" hanya untuk subdomain; tambahkan "example.com" secara terpisah untuk memblokir domain induk. Jika kosong atau tidak ditetapkan, tidak ada penolakan tambahan.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Izinkan Jaringan Privat di Browser (Berbahaya)`},help:{"v1-17103pi-4m":`Mengizinkan akses ke rentang alamat jaringan privat dari alat browser. Secara default dinonaktifkan jika tidak ditetapkan; aktifkan hanya untuk tujuan jaringan privat yang secara eksplisit tepercaya.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Pembersihan Tab Browser`},help:{"v1-1ctwaad-4y":`Kebijakan pembersihan semaksimal mungkin untuk tab browser yang dibuka oleh sesi agen utama. Tetap aktifkan agar tab sandbox atau browser terkelola yang tidak lagi digunakan tidak menumpuk pada gateway yang berjalan lama.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Pembersihan Tab Browser Diaktifkan`},help:{"v1-4sv97p-3u":`Mengaktifkan pembersihan tab browser terlacak yang tidak aktif untuk sesi agen utama. Nonaktifkan hanya jika alat eksternal sepenuhnya mengelola siklus hidup tab.`}},channels:{label:{"v1-1ju93md-8":`Saluran`},help:{"v1-12yv6ma-5n":`Konfigurasi penyedia saluran beserta pengaturan default bersama yang mengontrol kebijakan akses, visibilitas heartbeat, dan perilaku di setiap antarmuka. Pertahankan pengaturan default secara terpusat dan timpa per penyedia hanya jika diperlukan.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Pengaturan Default Kanal`},help:{"v1-uz6veb-4p":`Perilaku default kanal yang diterapkan di seluruh penyedia saat pengaturan khusus penyedia belum ditetapkan. Gunakan ini untuk menerapkan kebijakan dasar yang konsisten sebelum melakukan penyesuaian per penyedia.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Perlindungan Default terhadap Perulangan Bot`},help:{"v1-1lpznyk-4w":`Pengaturan default perlindungan terhadap perulangan pasangan untuk penyedia kanal yang mendukung pencegahan perulangan antarbot. Gunakan pengaturan pengganti khusus penyedia hanya jika suatu kanal memerlukan batas yang berbeda.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Jeda Default Perulangan Bot dalam Detik`},help:{"v1-1yl5ird-2z":`Jeda dalam detik yang diterapkan pada pasangan setelah melampaui batas perulangan. Nilai default untuk kanal yang mendukungnya adalah 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Perlindungan Default terhadap Perulangan Bot Diaktifkan`},help:{"v1-3ruik-4r":`Mengaktifkan perlindungan terhadap perulangan pasangan secara default untuk kanal yang mendukungnya saat pesan buatan bot dapat mencapai tahap pengiriman. Penyedia tetap dapat menonaktifkan perlindungan saat bot diabaikan.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Jumlah Default Peristiwa Perulangan Bot per Rentang Waktu`},help:{"v1-1u0mdjc-41":`Jumlah maksimum peristiwa yang dapat dipertukarkan oleh pasangan pengirim/penerima dalam rentang waktu yang dikonfigurasi sebelum pembatasan dimulai. Nilai default untuk kanal yang mendukungnya adalah 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Rentang Waktu Default Perulangan Bot dalam Detik`},help:{"v1-12xpmen-2m":`Durasi jendela bergeser dalam detik untuk batas loop pasangan. Nilai default untuk kanal yang mendukungnya adalah 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Visibilitas Konteks Default`},help:{"v1-1hze3g1-5o":`Visibilitas konteks tambahan default untuk konten kutipan/utas/riwayat yang diambil: "all" (pertahankan semua konteks), "allowlist" (hanya pengirim dalam daftar izin), atau "allowlist_quote" (daftar izin + pertahankan kutipan eksplisit).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Kebijakan Grup Default`},help:{"v1-ntl9m4-4n":`Kebijakan grup default di seluruh kanal: "open", "disabled", atau "allowlist". Pertahankan "allowlist" untuk konfigurasi produksi yang lebih aman, kecuali partisipasi grup secara luas memang diinginkan.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Visibilitas Heartbeat Default`},help:{"v1-49bw75-4v":`Pengaturan visibilitas heartbeat default untuk pesan status yang dikirim oleh penyedia/kanal. Sesuaikan secara global untuk mengurangi pembaruan status sehat yang berlebihan sambil tetap menampilkan peringatan.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Tampilkan Peringatan Heartbeat`},help:{"v1-8dk8zx-4g":`Menampilkan peringatan heartbeat tentang penurunan kondisi/kesalahan jika bernilai true agar kanal operator segera memperlihatkan masalah. Biarkan aktif di lingkungan produksi agar kondisi kanal yang bermasalah terlihat.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Tampilkan Status OK Heartbeat`},help:{"v1-17tg3mk-4z":`Menampilkan entri status heartbeat sehat/OK dalam keluaran status kanal jika bernilai true. Biarkan bernilai false di lingkungan dengan banyak aktivitas dan aktifkan hanya saat operator memerlukan konfirmasi eksplisit bahwa kondisi sehat.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Gunakan Indikator Heartbeat`},help:{"v1-1w12cs2-4m":`Mengaktifkan tampilan heartbeat berupa indikator ringkas sebagai pengganti teks status terperinci jika didukung. Gunakan mode indikator untuk dasbor padat dengan banyak kanal aktif.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Sebutan Implisit Default`},help:{"v1-4gtdyv-48":`Kebijakan default yang menentukan apakah balasan kepada bot, kutipan pesan bot, dan partisipasi bot dalam utas mengaktifkan kanal pesan yang mendukungnya tanpa sebutan eksplisit.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Sebutan Implisit Default untuk Kutipan Bot`},help:{"v1-va1u5v-2v":`Perlakukan kutipan pesan bot sebagai sebutan implisit secara default. Nilai default adalah true untuk kompatibilitas dengan versi sebelumnya.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Sebutan Implisit Default untuk Balasan kepada Bot`},help:{"v1-lm44c3-39":`Perlakukan balasan terhadap pesan bot itu sendiri sebagai sebutan implisit secara default. Nilai default adalah true untuk kompatibilitas dengan versi sebelumnya.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Sebutan Implisit Default untuk Partisipasi dalam Utas`},help:{"v1-160205h-3o":`Perlakukan pesan lanjutan dalam utas yang diikuti bot sebagai sebutan implisit secara default. Nilai default adalah true untuk kompatibilitas dengan versi sebelumnya.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Penggantian Model per Kanal`},help:{"v1-1b01spx-2p":`Petakan penyedia -> ID kanal / ID rekan DM -> penggantian model (nilainya berupa provider/model atau alias).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Worker Cloud`},help:{"v1-10carc4-5v":`Profil worker cloud yang diaktifkan secara opsional untuk lingkungan jarak jauh sekali pakai. Jika bagian ini dihilangkan atau tidak memiliki profil, pembuatan worker cloud tetap tidak tersedia dan perilaku status gateway/node yang ada tidak berubah.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Desktop Worker Cloud (Eksperimental)`},help:{"v1-vllayc-3n":`Mengaktifkan antarmuka eksperimental worker.desktop.observe dan panel Desktop di Control UI untuk lingkungan worker cloud yang mendukung desktop.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Kumpulan Worker Cloud Siap Pakai`},help:{"v1-rw51o5-6b":`Batas untuk worker cloud yang disiapkan agar siap digunakan pada sesi berikutnya. Cadangan dikenai biaya mesin yang berjalan hingga proses pembersihan oleh penyedia selesai; masa kedaluwarsanya yang tetap mengikuti permintaan aktual proyek dan kebijakan waktu tidak aktif yang berlaku dari penyedia.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Batas Cadangan Worker Cloud Siap Pakai`},help:{"v1-1mpd1dt-7u":`Batas di seluruh Gateway untuk worker cloud siap pakai yang belum ditugaskan, di semua proyek dan profil (default: 4). Worker yang sedang disiapkan dan pembersihan cadangan yang belum dikonfirmasi turut diperhitungkan dalam batas ini. Atur ke 0 untuk mengosongkan cadangan yang belum ditugaskan dan menonaktifkan pengisian ulang, sambil tetap mempertahankan penggunaan ulang snapshot dan sesi aktif.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Profil Worker Cloud`},help:{"v1-eii67l-3j":`Profil worker cloud bernama. Setiap profil memilih penyedia worker yang didaftarkan oleh plugin dan memuat pengaturan milik penyedia.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Profil Worker Cloud`},help:{"v1-1v2w7jl-4u":`Satu profil worker cloud yang dipilih berdasarkan nama saat membuat lingkungan. Simpan kredensial penyedia dalam referensi yang didukung, alih-alih menyematkan data rahasia dalam blok ini.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Metode Instalasi Worker Cloud`},help:{"v1-blrtbf-74":`Metode instalasi worker: "bundle" (default) mentransfer build gateway terinstal yang ditandai dengan hash konten dan mendukung versi rilis, pengembangan, serta versi yang belum dirilis; "npm" menginstal versi gateway yang persis sama dan hanya tersedia jika versi tersebut sudah dirilis.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Penyedia Worker Cloud`},help:{"v1-1p4s4c1-44":`ID penyedia worker yang didaftarkan oleh plugin. Plugin yang dikonfigurasi harus menyediakan ID ini sebelum gateway dapat menyiapkan lingkungan dari profil tersebut.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Target Cadangan Worker Cloud Siap Pakai`},help:{"v1-1nwve9s-7w":`Target jumlah worker siap pakai yang belum ditugaskan per proyek yang memenuhi syarat dan menggunakan profil ini (default: 1), dengan tunduk pada batas kumpulan worker siap pakai di seluruh Gateway. Atur ke 0 untuk menonaktifkan cadangan profil ini sambil tetap mempertahankan penggunaan ulang snapshot. Worker yang sedang disiapkan dan pembersihan cadangan yang belum dikonfirmasi turut diperhitungkan dalam target ini.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Pengaturan Penyedia Worker Cloud`},help:{"v1-mq7u32-4j":`Pengaturan milik penyedia yang divalidasi oleh plugin yang dipilih. Gunakan objek SecretRef untuk nilai yang memuat rahasia; pengaturan opak tidak mendapatkan resolusi rahasia otomatis.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Durasi Penangguhan Worker Cloud yang Menganggur`},help:{"v1-1keuwgh-4w":`Secara otomatis melepaskan sumber daya worker cloud yang menganggur setelah durasi ini, seperti 45m atau 2h; pesan berikutnya akan menyiapkan penggantinya. Minimum: 1m. Biarkan tidak diatur agar worker tetap berjalan.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Profil Proyek Worker Cloud`},help:{"v1-1kkfrif-46":`Nama profil worker cloud default dengan kunci berupa identitas repositori yang dinormalisasi ke huruf kecil (host/owner/repo). ID profil pengiriman yang ditentukan secara eksplisit diutamakan.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Profil Proyek Worker Cloud`},help:{"v1-1mux5u0-30":`Nama profil worker cloud yang digunakan secara default ketika origin worktree sesi cocok dengan identitas repositori ini.`}},commands:{label:{"v1-15x4mpf-8":`Perintah`},help:{"v1-1gi0dr2-5a":`Mengontrol antarmuka perintah chat, pembatasan berdasarkan pemilik, dan perilaku akses perintah dengan hak istimewa di seluruh penyedia. Pertahankan pengaturan default kecuali Anda memerlukan kontrol operator yang lebih ketat atau ketersediaan perintah yang lebih luas.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Aturan Akses Perintah dengan Hak Istimewa`},help:{"v1-7azkw-5g":`Menentukan aturan izin perintah dengan hak istimewa berdasarkan kanal dan pengirim untuk antarmuka perintah tingkat pemilik. Gunakan identitas spesifik penyedia dengan cakupan terbatas agar perintah berhak istimewa tidak tersedia bagi khalayak obrolan yang luas.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Izinkan Perintah Obrolan Bash`},help:{"v1-83ah7w-36":"Izinkan perintah obrolan bash (`!`; alias `/bash`) untuk menjalankan perintah shell host (default: false; memerlukan tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Durasi Bash di Latar Depan (ms)`},help:{"v1-1o0o4dw-2c":`Lama waktu bash menunggu sebelum beralih ke latar belakang (default: 2000; 0 langsung beralih ke latar belakang).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Izinkan /config`},help:{"v1-151bb7c-21":`Izinkan perintah obrolan /config untuk membaca/menulis konfigurasi di disk (default: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Izinkan /debug`},help:{"v1-y1lc3j-1y":`Izinkan perintah obrolan /debug untuk menimpa pengaturan hanya saat runtime (default: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Izinkan /mcp`},help:{"v1-1rtwcgd-2o":`Izinkan perintah obrolan /mcp untuk mengelola konfigurasi server MCP OpenClaw di bawah mcp.servers (default: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Perintah Bawaan`},help:{"v1-dighr2-5n":`Mendaftarkan perintah garis miring/menu bawaan pada kanal yang mendukung pendaftaran perintah (Discord, Slack, Telegram). Biarkan aktif agar perintah mudah ditemukan, kecuali Anda sengaja menggunakan alur kerja perintah berbasis teks saja.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Perintah Keterampilan Bawaan`},help:{"v1-19gtqci-5h":`Mendaftarkan perintah keterampilan bawaan agar pengguna dapat memanggil keterampilan langsung dari menu perintah penyedia yang mendukungnya. Selaraskan dengan kebijakan keterampilan Anda agar perintah yang tersedia sesuai dengan harapan operator.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Pemilik Perintah`},help:{"v1-1di38gv-3y":`Daftar izin pemilik eksplisit untuk perintah khusus pemilik. Gunakan ID asli kanal (opsional dengan awalan seperti "whatsapp:+15551234567"). '*' diabaikan.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Izinkan /plugins`},help:{"v1-akwy9y-33":`Izinkan perintah chat /plugins untuk menampilkan daftar plugin yang ditemukan dan mengaktifkan atau menonaktifkan plugin dalam konfigurasi (default: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Izinkan Mulai Ulang`},help:{"v1-m32fv2-27":`Izinkan /restart, /update, dan permintaan mulai ulang SIGUSR2 eksternal (default: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Perintah Teks`},help:{"v1-1utu76s-5j":`Mengaktifkan penguraian perintah teks dalam input chat, selain antarmuka perintah bawaan jika tersedia. Biarkan aktif untuk menjaga kompatibilitas di berbagai kanal yang tidak mendukung pendaftaran perintah bawaan.`}},cron:{label:{"v1-1qlte4b-b":`Otomatisasi`},help:{"v1-4md8ic-5u":`Pengaturan penjadwal global untuk otomatisasi tersimpan, eksekusi bersamaan, pengiriman cadangan, dan retensi sesi eksekusi. Pertahankan pengaturan default kecuali Anda meningkatkan volume otomatisasi atau mengintegrasikan penerima webhook eksternal.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Otomatisasi Diaktifkan`},help:{"v1-y8otx6-5i":`Mengaktifkan eksekusi otomatisasi untuk jadwal tersimpan yang dikelola oleh gateway. Biarkan aktif untuk alur pengingat/otomatisasi normal, dan nonaktifkan hanya untuk menjeda seluruh eksekusi otomatisasi tanpa menghapus tugas.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Retensi Sesi Otomatisasi`},help:{"v1-4wagu6-7e":"Mengatur berapa lama sesi eksekusi otomatisasi yang telah selesai disimpan sebelum dihapus (`24h`, `7d`, `1h30m`, atau `false` untuk menonaktifkan penghapusan; durasi nol seperti `0h` juga menonaktifkannya; default: `24h`). Gunakan masa penyimpanan yang lebih singkat untuk mengurangi pertumbuhan penggunaan penyimpanan pada jadwal berfrekuensi tinggi."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Lewati Otomatisasi Berulang yang Terlewat`},help:{"v1-w9wfmo-66":`Melewati slot cron/every berulang yang terlewat saat Gateway dimulai dan menjadwalkan waktu eksekusi berikutnya, alih-alih menjalankan yang terlewat. Default: false. Aktifkan untuk menghindari pengingat yang sudah tidak relevan setelah waktu henti; tugas at sekali jalan yang terlewat tetap dijalankan.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Kebijakan SSRF Webhook Otomatisasi`},help:{"v1-1xlfqnu-5h":`Kebijakan SSRF yang diterapkan pada setiap webhook otomatisasi keluar. Target privat, loopback, link-local, dan internal tetap diblokir kecuali kebijakan ini secara eksplisit mengizinkannya. Biarkan tidak diatur agar pengiriman tetap dibatasi secara ketat.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Nama Host yang Diizinkan untuk Webhook Otomatisasi`},help:{"v1-1i94hyz-3n":`Nama host persis atau literal IP yang diizinkan untuk pengiriman webhook otomatisasi, termasuk target yang seharusnya diblokir. Batasi daftar ini seminimal mungkin.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Izinkan Rentang Lokal Unik IPv6 untuk Webhook Otomatisasi`},help:{"v1-rke0oj-3b":`Mengizinkan webhook otomatisasi ke Alamat Lokal Unik IPv6 (fc00::/7). Gunakan hanya di lingkungan proksi fake-IP yang tepercaya.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Izinkan Rentang Tolok Ukur RFC 2544 untuk Webhook Otomatisasi`},help:{"v1-x1usg4-3h":`Mengizinkan webhook otomatisasi ke IP dalam rentang tolok ukur RFC 2544 (198.18.0.0/15). Gunakan hanya dengan lingkungan proksi IP palsu yang tepercaya.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Nama Host yang Diblokir untuk Webhook Otomatisasi`},help:{"v1-16cv1ic-6a":`Pola nama host yang ditolak sebelum pemeriksaan DNS dan aturan izin untuk pengiriman webhook otomatisasi. Mendukung host persis dan "*.example.com" hanya untuk subdomain; tambahkan "example.com" secara terpisah untuk memblokir domain induk. Jika kosong atau tidak diatur, tidak ada penolakan tambahan.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Izinkan Jaringan Privat untuk Webhook Otomatisasi (Berbahaya)`},help:{"v1-1n9710c-3t":`Mengizinkan webhook otomatisasi ke tujuan jaringan privat dan internal. Biarkan dinonaktifkan kecuali setiap tujuan webhook yang dikonfigurasi tepercaya.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Token Bearer Webhook Otomatisasi`},help:{"v1-1l90hxg-5l":`Token bearer yang disertakan dalam pengiriman POST webhook otomatisasi saat mode webhook digunakan. Utamakan substitusi rahasia/variabel lingkungan dan rotasi token ini secara berkala jika endpoint webhook bersama dapat diakses dari internet.`}},desktop:{label:{"v1-rs698z-7":`Desktop`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Desktop Lokal`},help:{"v1-99weio-30":`Pemantauan desktop untuk node yang dipasangkan, atau sumber host Gateway eksperimental, yang didukung oleh server VNC lokal.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Berbagi Desktop`},help:{"v1-m9lbcj-83":`Mengaktifkan sumber desktop mesin ini. Node macOS, Windows, dan Linux yang telah dipasangkan diaktifkan secara default; preferensi berbagi aplikasi desktop yang ditetapkan secara eksplisit diutamakan. Sumber Labs pada host Gateway dinonaktifkan secara default dan menerapkan perubahan secara langsung. Mulai ulang node yang telah dipasangkan setelah mengubah konfigurasi desktopnya.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Desktop Host Linux Terkelola`},help:{"v1-1r7n22m-49":`Menjalankan dan mengawasi desktop TigerVNC/XFCE tanpa monitor yang hanya dapat diakses melalui loopback di Linux. Port yang ditentukan secara eksplisit atau server VNC yang sudah ada pada port default tetap diutamakan.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`File Kata Sandi VNC Lokal`},help:{"v1-1m5lsox-37":`Jalur absolut ke file kata sandi VNC. Kosongkan di macOS untuk memasukkan kredensial akun saat membuka penampil desktop.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Port VNC Lokal`},help:{"v1-1ku4w9b-2b":`Port RFB loopback dari server VNC yang sudah berjalan di mesin ini (default: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnostik`},help:{"v1-1d5rnym-5p":`Kontrol diagnostik untuk penelusuran terarah, ekspor telemetri, dan pemeriksaan cache selama debugging. Pertahankan diagnostik dasar seminimal mungkin di lingkungan produksi dan aktifkan sinyal yang lebih mendalam hanya saat menyelidiki masalah.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Penelusuran Cache`},help:{"v1-10523zm-5b":`Pengaturan pencatatan penelusuran cache untuk mengamati keputusan cache dan konteks payload dalam eksekusi tersemat. Aktifkan sementara untuk debugging, lalu nonaktifkan setelahnya untuk mengurangi jejak log sensitif.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Penelusuran Cache Diaktifkan`},help:{"v1-2c1umi-1v":`Catat snapshot penelusuran cache untuk eksekusi agen tersemat (default: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnostik Diaktifkan`},help:{"v1-a46pxt-4h":`Sakelar utama untuk keluaran instrumentasi diagnostik dalam log dan jalur integrasi telemetri. Diaktifkan secara default; tetapkan ke false hanya di lingkungan dengan batasan sangat ketat.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Flag Diagnostik`},help:{"v1-x4w5ok-33":`Aktifkan log diagnostik terarah berdasarkan flag (misalnya ["telegram.http"]). Mendukung wildcard seperti "telegram.*" atau "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Pengaturan ekspor OpenTelemetry untuk trace, metrik, dan log yang dihasilkan oleh komponen gateway. Gunakan ini saat mengintegrasikan dengan backend observabilitas terpusat dan pipeline pelacakan terdistribusi.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Perekaman Konten OpenTelemetry`},help:{"v1-19tid4t-2t":`Perekaman konten span OTEL yang harus diaktifkan secara eksplisit. Secara default nonaktif; true merekam konten pesan non-sistem dan konten alat.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry Diaktifkan`},help:{"v1-193bm0-5b":`Mengaktifkan pipeline ekspor OpenTelemetry untuk trace, metrik, dan log berdasarkan pengaturan endpoint/protokol yang dikonfigurasi. Biarkan nonaktif kecuali endpoint kolektor dan autentikasi Anda sudah dikonfigurasi sepenuhnya.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Endpoint OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL endpoint kolektor yang digunakan untuk transport ekspor OpenTelemetry, termasuk skema dan port. Gunakan endpoint kolektor yang dapat dijangkau dan tepercaya, lalu pantau kesalahan penerimaan data setelah penerapan.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Interval Pengiriman OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Interval dalam milidetik untuk pengiriman telemetri berkala dari buffer ke kolektor. Naikkan untuk mengurangi frekuensi ekspor, atau turunkan agar data lebih cepat terlihat selama penanganan insiden aktif.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`Header OpenTelemetry`},help:{"v1-s26t2a-52":`Header permintaan HTTP tambahan yang dikirim bersama permintaan ekspor OpenTelemetry, sering digunakan untuk autentikasi tenant atau perutean. Simpan rahasia dalam nilai yang bersumber dari variabel lingkungan dan hindari penambahan header yang tidak perlu.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Log OpenTelemetry Diaktifkan`},help:{"v1-12wo6rv-4k":`Aktifkan ekspor sinyal log melalui OpenTelemetry selain ke tujuan pencatatan lokal. Gunakan ini ketika korelasi log terpusat diperlukan di seluruh layanan dan agen.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Endpoint Log OpenTelemetry`},help:{"v1-1vgzldu-40":`Endpoint log OTLP/HTTP khusus sinyal. Jika ditetapkan, nilai ini menggantikan diagnostics.otel.endpoint dan OTEL_EXPORTER_OTLP_ENDPOINT hanya untuk ekspor log.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Pengekspor Log OpenTelemetry`},help:{"v1-9bzywd-5q":`Tujuan ekspor log untuk diagnostics.otel.logs. Gunakan "otlp" untuk endpoint log OTLP yang dikonfigurasi, "stdout" untuk satu rekaman JSON per baris stdout dalam pipeline log kontainer, dan "both" ketika kedua tujuan diperlukan.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Awalan Nama Metrik OpenTelemetry`},help:{"v1-1epdpi9-b2":`Mengganti awalan default "openclaw." pada nama metrik milik OpenClaw. Gunakan string kosong untuk menghapus awalan, atau hingga 128 karakter berupa huruf ASCII, angka, garis bawah, titik, tanda hubung, dan garis miring yang diawali dengan huruf. Sertakan pemisah apa pun yang diperlukan, misalnya "acme."; nama metrik standar gen_ai.* tidak berubah. Mengubah nilai ini mengharuskan pembaruan dasbor dan peringatan yang melakukan kueri terhadap nama lama.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Metrik OpenTelemetry Diaktifkan`},help:{"v1-13r4cf4-4x":`Aktifkan ekspor sinyal metrik ke endpoint kolektor OpenTelemetry yang dikonfigurasi. Biarkan aktif untuk dasbor kesehatan runtime, dan nonaktifkan hanya jika volume metrik harus diminimalkan.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Endpoint Metrik OpenTelemetry`},help:{"v1-qlfh7x-47":`Endpoint metrik OTLP/HTTP khusus sinyal. Jika ditetapkan, pengaturan ini menggantikan diagnostics.otel.endpoint dan OTEL_EXPORTER_OTLP_ENDPOINT hanya untuk ekspor metrik.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Protokol OpenTelemetry`},help:{"v1-17ine8s-5e":`Protokol transport OTel untuk ekspor telemetri. Hanya "http/protobuf" yang diterima; jalankan "openclaw doctor --fix" untuk memperbaiki nilai lama "grpc" yang tersimpan atau mendapatkan panduan pengeditan manual sesuai sumber.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Tingkat Pengambilan Sampel Jejak OpenTelemetry`},help:{"v1-brcwep-50":`Tingkat pengambilan sampel jejak (0-1) yang mengontrol seberapa banyak lalu lintas jejak diekspor ke backend observabilitas. Tingkat yang lebih rendah mengurangi beban tambahan/biaya, sedangkan tingkat yang lebih tinggi meningkatkan ketelitian penelusuran kesalahan.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Nama Layanan OpenTelemetry`},help:{"v1-1hpiqon-5d":`Nama layanan yang dilaporkan dalam atribut sumber daya telemetri untuk mengidentifikasi instans gateway ini di backend observabilitas. Gunakan nama yang tetap agar dasbor dan peringatan tetap konsisten di setiap deployment.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Jejak OpenTelemetry Diaktifkan`},help:{"v1-j7zrrp-4s":`Aktifkan ekspor sinyal jejak ke endpoint kolektor OpenTelemetry yang dikonfigurasi. Biarkan aktif jika pelacakan latensi/penelusuran kesalahan diperlukan, dan nonaktifkan jika Anda hanya menginginkan metrik/log.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Endpoint Trace OpenTelemetry`},help:{"v1-8yw5p1-43":`Endpoint trace OTLP/HTTP khusus sinyal. Jika diatur, pengaturan ini menggantikan diagnostics.otel.endpoint dan OTEL_EXPORTER_OTLP_ENDPOINT hanya untuk ekspor trace.`}},discovery:{label:{"v1-l2sr05-9":`Penemuan`},help:{"v1-1sqleij-4w":`Pengaturan penemuan layanan untuk pengumuman mDNS lokal dan pensinyalan kehadiran area luas opsional. Batasi penemuan pada jaringan yang dituju untuk menghindari kebocoran metadata layanan.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Penemuan mDNS`},help:{"v1-vtbyyq-4w":`Grup konfigurasi penemuan mDNS untuk pengumuman di jaringan lokal dan penyesuaian perilaku penemuan. Gunakan mode minimal untuk penemuan LAN rutin kecuali metadata tambahan diperlukan.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Mode Penemuan mDNS`},help:{"v1-1p28pd5-2m":`Mode siaran mDNS ("minimal" adalah default, "full" menyertakan cliPath/sshPort, "off" menonaktifkan mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Penemuan Area Luas`},help:{"v1-1akkqjm-53":`Grup konfigurasi penemuan area luas untuk menyediakan sinyal penemuan di luar cakupan tautan lokal. Aktifkan hanya pada penerapan yang memang dimaksudkan untuk menggabungkan informasi kehadiran Gateway lintas lokasi.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Domain Penemuan Area Luas`},help:{"v1-rxrygo-4m":`Domain DNS-SD unicast opsional untuk penemuan area luas, seperti openclaw.internal. Gunakan ini saat Anda memang bermaksud memublikasikan penemuan Gateway di luar cakupan mDNS lokal.`}},env:{label:{"v1-1zc80q-b":`Lingkungan`},help:{"v1-1ao5po6-55":`Pengaturan impor dan penggantian lingkungan yang digunakan untuk menyediakan variabel runtime bagi proses Gateway. Gunakan bagian ini untuk mengontrol pemuatan lingkungan shell dan perilaku penyisipan variabel secara eksplisit.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Impor Lingkungan Shell`},help:{"v1-1gw487t-4y":`Kontrol impor lingkungan shell untuk memuat variabel dari shell login Anda saat memulai. Biarkan aktif jika Anda bergantung pada rahasia yang ditentukan dalam profil atau penyesuaian PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Impor Lingkungan Shell Diaktifkan`},help:{"v1-5tiuup-5u":`Mengaktifkan pemuatan variabel lingkungan dari profil shell pengguna selama inisialisasi awal. Biarkan aktif untuk mesin pengembang, atau nonaktifkan di lingkungan layanan yang dibatasi ketat dengan pengelolaan variabel lingkungan secara eksplisit.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Batas Waktu Impor Lingkungan Shell (ms)`},help:{"v1-nsk2yf-5c":`Waktu maksimum dalam milidetik yang diizinkan untuk menentukan lingkungan shell sebelum mekanisme cadangan diterapkan. Gunakan batas waktu yang lebih singkat agar proses mulai lebih cepat, atau tingkatkan jika inisialisasi shell memerlukan banyak waktu.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Penggantian Variabel Lingkungan`},help:{"v1-yxc3z7-5n":`Penggantian variabel lingkungan berupa pasangan kunci/nilai eksplisit yang digabungkan ke lingkungan proses runtime OpenClaw. Gunakan ini untuk konfigurasi lingkungan yang deterministik alih-alih hanya mengandalkan efek samping profil shell.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Pengaturan runtime Gateway untuk mode pengikatan, autentikasi, Control UI, transport jarak jauh, dan kontrol keselamatan operasional. Pertahankan pengaturan default yang konservatif kecuali Anda sengaja membuka akses Gateway di luar antarmuka lokal tepercaya.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Izinkan Mekanisme Cadangan x-real-ip pada Gateway`},help:{"v1-1wr3qmw-4c":`Mengaktifkan penggunaan x-real-ip sebagai cadangan saat x-forwarded-for tidak tersedia dalam skenario proksi. Biarkan nonaktif kecuali tumpukan ingress Anda memerlukan perilaku kompatibilitas ini.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Autentikasi Gateway`},help:{"v1-70b6ni-50":`Kebijakan autentikasi untuk akses HTTP/WebSocket Gateway, termasuk mode, kredensial, perilaku proksi tepercaya, dan pembatasan laju. Tetap aktifkan autentikasi untuk setiap penerapan non-loopback.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Izinkan Identitas Tailscale untuk Autentikasi Gateway`},help:{"v1-vqtmgw-53":`Mengizinkan jalur identitas Tailscale tepercaya memenuhi pemeriksaan autentikasi Gateway jika dikonfigurasi. Gunakan ini hanya jika keamanan identitas tailnet Anda kuat dan alur kerja operator bergantung padanya.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Pemberian Cakupan Identitas Gateway`},help:{"v1-1h0zxy7-5n":`Memetakan identitas proksi tepercaya atau Tailscale yang telah diverifikasi ke pemberian cakupan operator yang hanya berlaku untuk koneksi. Kunci email dicocokkan tanpa membedakan huruf besar dan kecil; pemberian ini menambah cakupan perangkat sebelum batas cakupan koneksi diterapkan.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Mode Autentikasi Gateway`},help:{"v1-j8rodq-9t":`Mode autentikasi Gateway: "none", "token", "password", atau "trusted-proxy", bergantung pada arsitektur edge Anda. Mode token/password memilih rahasia yang dikonfigurasi (gateway.auth.token atau gateway.auth.password); klien dapat mengirimkannya melalui salah satu kolom autentikasi koneksi. Gunakan token/password untuk akses langsung dari luar, dan trusted-proxy hanya di belakang proksi berbasis identitas yang keamanannya telah diperkuat.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Kata Sandi Gateway`},help:{"v1-1ndt0u2-4g":`Rahasia bersama yang dipilih oleh gateway.auth.mode=password. Klien dapat mengirimkannya melalui auth.token atau auth.password. Mode kata sandi diperlukan untuk Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Batas Laju Autentikasi Gateway`},help:{"v1-1kstr42-54":`Kontrol pembatasan percobaan login/autentikasi untuk mengurangi risiko serangan brute-force terhadap kredensial di batas Gateway. Tetap aktifkan di lingkungan yang terekspos dan sesuaikan ambang batas dengan pola lalu lintas normal Anda.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Token Gateway`},help:{"v1-16i7cxs-5q":`Rahasia bersama yang dipilih oleh gateway.auth.mode=token, pengaturan default untuk penyiapan lokal baru. Klien dapat mengirimkannya melalui auth.token atau auth.password. Pengikatan ke alamat non-loopback memerlukan mode autentikasi yang aktif.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Autentikasi Proksi Tepercaya Gateway`},help:{"v1-12fsi5d-58":`Pemetaan header autentikasi proksi tepercaya untuk penyedia identitas upstream yang menyisipkan klaim pengguna. Gunakan hanya dengan CIDR proksi yang dikenal dan daftar izin header yang ketat untuk mencegah pemalsuan header identitas.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Identitas GitHub Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Identitas GitHub terverifikasi opsional dari penyedia Cloudflare Access OIDC yang dipilih. Memerlukan header email dan asersi Access standar. Jika klaim tidak tersedia, profil tetap hanya menggunakan email; peran profil dan preferensi rekan penulis yang ada dipertahankan.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Klaim ID Akun GitHub`},help:{"v1-pcaaw7-57":`Klaim OIDC yang diteruskan secara persis, dengan nilai berupa ID akun GitHub terverifikasi dalam bentuk string bilangan desimal positif. Konfigurasikan Access untuk meneruskannya dalam oidc_fields; jangan pernah menggunakan klaim yang belum diverifikasi dan dapat diedit pengguna.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Penerbit Cloudflare Access`},help:{"v1-gykv03-56":`Origin HTTPS persis dari tim Cloudflare Access tepercaya, seperti https://example.cloudflareaccess.com, tanpa garis miring di akhir. Klaim dari penerbit lain tidak menyediakan identitas GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`ID Penyedia OIDC Cloudflare Access`},help:{"v1-kbyo5w-44":`ID penyedia identitas Access yang persis untuk integrasi OIDC tepercaya. Nama tampilan penyedia atau nama klaim yang cocok saja tidak cukup untuk menetapkan kepercayaan.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Persetujuan Otomatis Perangkat melalui Proksi Tepercaya`},help:{"v1-uh32ha-6z":`Kebijakan opsional untuk menyetujui secara otomatis perangkat operator baru berbasis browser dan UI native, serta perluasan cakupan dengan kunci yang sama setelah autentikasi proksi tepercaya. Izin yang diberikan dibatasi oleh deviceAutoApprove.scopes dan header x-openclaw-scopes milik proksi jika tersedia.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Persetujuan Otomatis Perangkat melalui Proksi Tepercaya Diaktifkan`},help:{"v1-1nntwls-78":`Secara otomatis menyetujui perangkat operator baru berbasis browser dan UI native, serta perluasan cakupan dengan kunci yang sama setelah proksi balik mengautentikasi pengguna yang diizinkan. Default: false. Aktifkan hanya jika batas identitas proksi cukup kuat untuk menggantikan pemasangan perangkat secara manual.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Cakupan Persetujuan Otomatis Perangkat Proksi Tepercaya`},help:{"v1-raeila-g3":`Cakupan maksimum yang diberikan kepada perangkat operator yang disetujui secara otomatis. Nilai defaultnya adalah operator.read, operator.write, operator.approvals, dan operator.questions. Cakupan yang diminta dibatasi pada daftar ini; permintaan tanpa cakupan akan menerima daftar ini. Jika tidak ditetapkan, persetujuan otomatis juga menambahkan operator.questions untuk klien UI lama; daftar eksplisit tidak pernah diperluas. Mencantumkan operator.admin secara eksplisit memungkinkan setiap pengguna yang diautentikasi melalui proksi mendapatkan persetujuan otomatis untuk akses admin penuh dan membuat permintaan tanpa cakupan menerima akses admin penuh secara otomatis; hal ini juga memicu temuan audit keamanan kritis dan peringatan saat Gateway dimulai.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Mode Pengikatan Gateway`},help:{"v1-1unqude-4y":`Profil pengikatan jaringan: "auto", "lan", "loopback", "custom", atau "tailnet" untuk mengontrol keterpaparan antarmuka. Tetap gunakan "loopback" untuk pengoperasian khusus lokal; "auto" dapat mengekspos semua antarmuka.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`Agen CLI`},help:{"v1-1qqo8m2-5a":`Penemuan mesin sesi CLI eksternal di Control UI yang disediakan melalui katalog sesi Gateway. Aktif secara default; nonaktifkan untuk mencegah mesin tersebut dimulai dari pemilih model sesi baru.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`Agen CLI Diaktifkan`},help:{"v1-ufu7fx-8p":`Menampilkan agen CLI berbasis katalog di pemilih model sesi baru Control UI jika bernilai true (default: true). Tetapkan false untuk menonaktifkan agen CLI dan pembuatan sesi CLI native. Hanya katalog yang menyatakan dukungan pembuatan sesi yang ditampilkan, dan pemilih tetap tersembunyi jika Gateway tidak menyatakan dukungan katalog sesi.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Pengaturan hosting Control UI, termasuk pengaktifan, pengaturan jalur, dan perilaku penguatan keamanan origin browser/autentikasi. Minimalkan eksposur UI dan gunakan kontrol autentikasi yang kuat sebelum melakukan deployment yang dapat diakses dari internet.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Origin yang Diizinkan untuk Control UI`},help:{"v1-1stgitk-9i":`Origin browser yang diizinkan untuk koneksi websocket Control UI/WebChat (hanya origin lengkap, misalnya https://control.example.com). Wajib untuk deployment Control UI non-loopback kecuali fallback header Host yang berbahaya diaktifkan secara eksplisit. Pengaturan ["*"] berarti mengizinkan semua origin browser dan sebaiknya dihindari di luar pengujian lokal yang dikontrol secara ketat.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Izinkan URL Sematan Eksternal Control UI`},help:{"v1-obwpfg-6s":`Opsi BERBAHAYA yang memungkinkan sematan yang dihosting memuat URL http(s) eksternal absolut. Biarkan opsi ini nonaktif kecuali Control UI Anda memang menyematkan halaman pihak ketiga tepercaya; dokumen /__openclaw__/canvas dan /__openclaw__/a2ui yang dihosting tidak memerlukannya.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Ambil Favicon Tautan Secara Otomatis`},help:{"v1-bn9u34-ag":`Ambil favicon tautan dan pratinjau sosial tab browser melalui Gateway (aktif secara default). Kartu tab browser memuat metadata halaman publik dan gambar yang ditentukan tanpa cookie browser atau kredensial situs. Semua permintaan menggunakan pemeriksaan SSRF yang ketat dan pemrosesan HTML/gambar dengan batasan. Atur ke false untuk menonaktifkan pengambilan otomatis favicon dan pratinjau halaman; tangkapan layar browser secara langsung tidak terpengaruh.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Jalur Dasar Control UI`},help:{"v1-1dx68ar-1w":`Awalan URL opsional tempat Control UI disajikan (misalnya /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Undangan Komunitas Control UI`},help:{"v1-1rz3zsx-73":`Tampilkan undangan komunitas Discord di Control UI yang disajikan oleh Gateway ini (aktif secara default). Atur ke false untuk menyembunyikannya di setiap browser yang menggunakan deployment UI ini. Perubahan berlaku setelah browser dimuat ulang atau terhubung kembali; mengaktifkannya kembali tetap mempertahankan status penutupan undangan yang tersimpan secara lokal di browser.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Izinkan Fallback Origin Berbasis Header Host yang Berbahaya`},help:{"v1-1t1qi4c-7v":`Opsi BERBAHAYA yang mengaktifkan fallback origin berbasis header Host untuk pemeriksaan websocket Control UI/WebChat. Mode ini didukung jika deployment Anda sengaja mengandalkan kebijakan origin berbasis header Host; pengaturan gateway.controlUi.allowedOrigins secara eksplisit tetap menjadi pilihan default yang direkomendasikan untuk keamanan yang lebih ketat.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Mode Sandbox Sematan Control UI`},help:{"v1-d54l3a-7c":'Kebijakan sandbox iframe untuk sematan Control UI yang dihosting. "strict" menonaktifkan skrip, "scripts" mengizinkan sematan interaktif sambil mempertahankan isolasi origin (default), dan "trusted" menambahkan `allow-same-origin` untuk dokumen dari situs yang sama yang sengaja memerlukan hak akses lebih tinggi.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI Diaktifkan`},help:{"v1-1hhyymc-4w":`Mengaktifkan penyajian Control UI Gateway dari proses HTTP Gateway jika bernilai true. Biarkan aktif untuk administrasi lokal, dan nonaktifkan jika antarmuka kontrol eksternal menggantikannya.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Lingkungan Control UI`},help:{"v1-paarso-4n":`Identitas lingkungan publik opsional yang ditampilkan pada pita Control UI, avatar agen, lencana label, judul browser, dan favicon. Jangan isi untuk mempertahankan tampilan default.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Warna Lingkungan Control UI`},help:{"v1-mp6cta-2i":`Palet warna lingkungan berdasarkan nama: teal, amber, purple, coral, pink, blue, green, red, atau gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Label Lingkungan Control UI`},help:{"v1-1njve3z-3z":`Label lingkungan yang ditampilkan di Control UI dan tab browser; spasi di awal dan akhir dihapus, dan label harus berisi 1 hingga 24 karakter.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Fitur Eksperimental Control UI`},help:{"v1-1qobi2m-3g":`Eksperimen Control UI yang dapat diaktifkan secara opsional. Kemampuan ini dapat berubah antarversi rilis dan tetap dinonaktifkan kecuali diaktifkan secara eksplisit.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`UI Plugin Kustom`},help:{"v1-108u6ts-9e":`Izinkan plugin yang diinstal pengguna menjalankan JavaScript native di Control UI (default: false). Tampilan plugin bawaan tetap tersedia. UI kustom menggunakan izin Gateway milik operator yang sedang masuk; aktifkan hanya untuk plugin tepercaya. Perubahan diterapkan tanpa memulai ulang Gateway. Muat ulang halaman Control UI yang terbuka untuk menghapus kode plugin yang sebelumnya dimuat.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Kredensial Layanan GitHub Control UI`},help:{"v1-1p31phh-d6":`Kredensial layanan berbasis SecretRef untuk penemuan proyek Control UI dan pratinjau GitHub saat kursor diarahkan, tanpa identitas terkelola. Pratinjau ini mengutamakan identitas GitHub yang dikonfigurasi untuk agen terpilih, dan mewarisi identitas sistem jika tidak ada pengaturan pengganti. Utamakan konfigurasi eksplisit agar kepemilikan layanan jelas. Abaikan pengaturan ini untuk tetap menggunakan GH_TOKEN/GITHUB_TOKEN sebagai cadangan dari lingkungan proses Gateway bersama. Kredensial yang dikonfigurasi secara eksplisit tetapi tidak tersedia akan menyebabkan akses ditolak.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Direktori Root Aset Control UI`},help:{"v1-elck04-25":`Direktori root sistem berkas opsional untuk aset Control UI (default: dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Pengamat Sesi Control UI`},help:{"v1-1ahs80-8a":`Menghasilkan ringkasan status sesi secara langsung untuk klien Control UI yang berlangganan menggunakan model utilitas setiap agen (aktif secara default). Atur ke false untuk menonaktifkan panggilan model pengamat di seluruh Gateway; mengatur agents.defaults.utilityModel ke string kosong akan menonaktifkan pengamatan berbasis model utilitas untuk agen yang tidak mengganti pengaturan tersebut.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Host Bind Kustom Gateway`},help:{"v1-lwjcyo-4d":`Alamat IPv4 yang digunakan untuk bind kustom. Alamat IPv4 tertentu juga memerlukan port Gateway yang sama pada 127.0.0.1; hindari 0.0.0.0 kecuali akses melalui semua antarmuka diperlukan.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`API HTTP Gateway`},help:{"v1-ebtex7-4j":`Konfigurasi API HTTP Gateway yang mengelompokkan pengaturan pengaktifan endpoint dan kontrol eksposur API pada lapisan transport. Aktifkan hanya endpoint yang diperlukan untuk mengurangi permukaan serangan.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Endpoint HTTP Gateway`},help:{"v1-1a0r104-55":`Pengaturan aktivasi fitur endpoint HTTP pada API Gateway untuk rute kompatibilitas dan integrasi opsional. Aktifkan endpoint secara terencana dan pantau pola akses setelah peluncuran.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Endpoint OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Aktifkan endpoint `POST /v1/chat/completions` yang kompatibel dengan OpenAI (default: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Batas Gambar OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Kontrol pengambilan/validasi gambar untuk bagian `image_url` yang kompatibel dengan OpenAI."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Daftar MIME Gambar yang Diizinkan untuk OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Jenis MIME yang diizinkan untuk bagian `image_url` (daftar tidak membedakan huruf besar dan kecil)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Izinkan URL Gambar untuk OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Izinkan pengambilan URL di sisi server untuk bagian `image_url` (default: false; URI data tetap didukung). Atur ke `false` untuk menonaktifkan pengambilan URL sepenuhnya."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Byte Maksimum Gambar OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Byte maksimum per gambar `image_url` yang diambil/didekodekan (default: 10MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Jumlah Maksimum Pengalihan Gambar OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Jumlah maksimum pengalihan HTTP yang diizinkan saat mengambil URL `image_url` (default: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Batas Waktu Gambar OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Batas waktu dalam milidetik untuk pengambilan URL `image_url` (default: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Daftar URL Gambar yang Diizinkan untuk OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Daftar opsional nama host yang diizinkan untuk pengambilan URL `image_url`; mendukung host yang cocok persis dan karakter pengganti `*.example.com`. Daftar yang kosong atau tidak disertakan berarti tidak ada pembatasan berdasarkan daftar nama host yang diizinkan."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Header Keamanan HTTP Gateway`},help:{"v1-n8z1hb-44":`Header keamanan respons HTTP opsional yang diterapkan oleh proses Gateway itu sendiri. Sebaiknya atur header ini di proksi balik Anda jika TLS diterminasi di sana.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Header Keamanan Transport Ketat`},help:{"v1-1buwhc3-3v":`Nilai untuk header respons Strict-Transport-Security. Atur hanya pada origin HTTPS yang sepenuhnya Anda kendalikan; gunakan false untuk menonaktifkannya secara eksplisit.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Mode Gateway`},help:{"v1-nfjirv-5m":`Mode operasi Gateway: "local" menjalankan saluran dan runtime agen di host ini, sedangkan "remote" terhubung melalui transport jarak jauh. Tetap gunakan "local" kecuali Anda sengaja menjalankan topologi Gateway jarak jauh yang terpisah.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills Node Gateway Diaktifkan`},help:{"v1-1xwu6at-3g":`Terima Skills yang dipublikasikan oleh node yang telah dipasangkan selama node tersebut terhubung (default: true). Atur ke false untuk mengabaikan Skills yang dipublikasikan oleh node.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Mode Browser Node Gateway`},help:{"v1-oeu1nc-69":`Perutean browser node ("auto" = utamakan browser host, gunakan satu node browser yang terhubung saat kapabilitas lokal tidak tersedia; "manual" = wajibkan pemilihan node secara eksplisit atau penyematan yang dikonfigurasi; "off" = nonaktifkan perutean node).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Penyematan Browser Node Gateway`},help:{"v1-1cykty2-1p":`Sematkan perutean browser ke ID atau nama node tertentu (opsional).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Daftar Izin Node Gateway (Perintah Tambahan)`},help:{"v1-6l4otb-5m":"Perintah node.invoke tambahan yang diizinkan selain perintah default Gateway (array string perintah). Mengaktifkan perintah berbahaya di sini merupakan pengesampingan yang sensitif terhadap keamanan dan ditandai oleh `openclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Daftar Blokir Node Gateway`},help:{"v1-u7c8wx-53":"Nama perintah node yang akan diblokir meskipun tercantum dalam klaim node atau daftar izin default (hanya pencocokan nama perintah secara persis, misalnya `system.run`; tidak memeriksa teks shell di dalam perintah tersebut)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Pemasangan Node Gateway`},help:{"v1-gldsi2-4s":`Pengaturan kebijakan pemasangan node. Persetujuan otomatis yang diverifikasi melalui SSH diaktifkan secara default; persetujuan otomatis CIDR tetap dinonaktifkan kecuali daftar izin CIDR/IP tepercaya dikonfigurasi secara eksplisit.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR Persetujuan Otomatis Pemasangan Node Gateway`},help:{"v1-1m6jsxj-6x":`Daftar izin CIDR/IP opsional untuk menyetujui secara otomatis pemasangan pertama perangkat dengan peran node tanpa cakupan yang diminta. Dinonaktifkan jika tidak diatur. Pemasangan operator, browser, Control UI, serta pemasangan untuk peningkatan peran, cakupan, metadata, atau kunci publik tetap memerlukan persetujuan manual.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Persetujuan Otomatis Pemasangan Node Lokal Gateway`},help:{"v1-glzm36-41":`Setujui pemasangan lokal tepercaya dan peningkatan akses tanpa pemberitahuan (default: true); atur ke false untuk mengutamakan persetujuan eksplisit bagi setiap perangkat daripada kemudahan.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Verifikasi SSH Pemasangan Node Gateway`},help:{"v1-1e4da92-ct":"Persetujuan otomatis yang diverifikasi melalui SSH untuk pemasangan pertama perangkat dengan peran node (default: diaktifkan). Gateway membuat koneksi SSH balik ke host pemasangan (BatchMode, verifikasi kunci host yang ketat) dan hanya menyetujui jika keluaran `openclaw node identity` dari host jarak jauh cocok dengan kunci perangkat yang menunggu persetujuan. Atur ke false untuk menonaktifkan verifikasi SSH (terpisah dari autoApproveCidrs, yang tetap aktif); untuk pemasangan yang hanya dapat disetujui secara manual, hapus juga pengaturan autoApproveCidrs. Berikan objek untuk mengganti user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Alat Plugin Node Gateway`},help:{"v1-1c24iq3-28":`Mengontrol apakah node yang telah dipasangkan boleh memublikasikan deskriptor alat plugin yang dapat dilihat agen.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Alat Plugin Node Gateway Diaktifkan`},help:{"v1-14lgfu6-47":`Terima deskriptor alat plugin yang terlihat oleh agen dan dipublikasikan oleh node yang dipasangkan (default: true). Atur ke false untuk mengabaikan dan menghapus semua alat plugin yang dipublikasikan oleh node.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Port Gateway`},help:{"v1-for8t5-54":`Port TCP yang digunakan oleh listener Gateway untuk API, Control UI, dan jalur masuk yang menghadap kanal. Gunakan port khusus dan hindari konflik dengan proxy balik atau layanan pengembangan lokal.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Portal Gateway`},help:{"v1-1v2lkw9-1c":`Pengaturan publikasi portal dan ingress privat.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Ingress Portal Privat`},help:{"v1-20w4gq-69":`Proksi balik wildcard HTTPS privat opsional yang dikelola operator. Teruskan Host asli, jalur, dan peningkatan koneksi WebSocket ke listener loopback khusus. Autentikasi bearer portal tetap diperlukan. Memerlukan mulai ulang Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Domain Wildcard Portal`},help:{"v1-1ipbfad-53":`Domain DNS tanpa awalan untuk subdomain portal acak (misalnya previews.example.net). Konfigurasikan DNS wildcard dan HTTPS secara privat; jangan gunakan ruang nama host yang sama dengan Gateway atau Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Port Loopback Ingress Portal`},help:{"v1-1mb98cv-4g":`Port HTTP loopback khusus yang menerima lalu lintas dari proksi HTTPS wildcard privat. Harus berbeda dari port Gateway. Ini adalah port backend, bukan port HTTPS publik.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Origin Publik Gateway`},help:{"v1-17vekvx-87":`Origin HTTPS Gateway yang dapat diakses dari luar. HTTP hanya diizinkan untuk localhost, 127.0.0.1, atau [::1]. MCP OAuth per pemohon menggunakannya untuk membuat URL callback di /oauth/mcp/callback; tautan sesi kanal dan tautan penampil yang dibuat plugin menggunakannya untuk mengakses Control UI dan rute Gateway.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Pengiriman Push Gateway`},help:{"v1-h23oz7-5s":`Pengaturan pengiriman push yang digunakan oleh Gateway saat perlu membangunkan atau memberi tahu perangkat yang dipasangkan. Konfigurasikan APNs berbasis relay di sini untuk build iOS resmi; autentikasi APNs langsung tetap berbasis variabel lingkungan untuk build lokal/manual.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Pengiriman APNs Gateway`},help:{"v1-4bbafr-4e":`Pengaturan pengiriman APNs untuk perangkat iOS yang dipasangkan dengan Gateway ini. Gunakan pengaturan relay untuk build App Store resmi yang mendaftar melalui relay push eksternal.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Relay APNs Gateway`},help:{"v1-7glbel-6x":`Pengaturan relai eksternal untuk pengiriman APNs melalui relai. Gateway menggunakan relai OpenClaw yang dihosting secara default, atau relai kustom ini untuk push.test, sinyal pengaktifan, dan pengaktifan untuk menyambung kembali setelah build iOS resmi yang dipasangkan menerbitkan registrasi berbasis relai.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`URL Dasar Relai APNs Gateway`},help:{"v1-1o8mgnq-69":`URL HTTPS dasar kustom opsional untuk layanan relai APNs eksternal yang digunakan oleh build iOS resmi dari App Store. Pastikan URL ini sesuai dengan URL relai yang ditanamkan dalam build iOS agar lalu lintas registrasi dan pengiriman mengarah ke deployment yang sama.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Batas Waktu Relai APNs Gateway (ms)`},help:{"v1-a0jkb1-4z":`Batas waktu dalam milidetik untuk permintaan pengiriman relai dari Gateway ke relai APNs (default: 10000). Naikkan untuk relai atau jaringan yang lebih lambat, atau turunkan agar percobaan pengaktifan lebih cepat dinyatakan gagal.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Pemuatan Ulang Konfigurasi`},help:{"v1-d02mvq-4w":`Kebijakan pemuatan ulang konfigurasi secara langsung yang menentukan cara perubahan diterapkan dan kapan mulai ulang penuh dipicu. Pertahankan perilaku hibrida untuk pembaruan operasional yang paling aman, kecuali saat men-debug mekanisme internal pemuatan ulang.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Mode Pemuatan Ulang Konfigurasi`},help:{"v1-1q1etcf-3m":`Mengontrol cara perubahan konfigurasi diterapkan: "off" mengabaikan perubahan langsung dan "hybrid" menerapkan perubahan yang aman tanpa mulai ulang, lalu memulai ulang bila diperlukan.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Gateway Jarak Jauh`},help:{"v1-6xv7gd-5a":`Pengaturan koneksi Gateway jarak jauh untuk transport langsung atau SSH saat instans ini menjadi proksi ke host runtime lain. Gunakan mode jarak jauh hanya jika pengoperasian dengan host terpisah memang sengaja dikonfigurasi.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Header Autentikasi Edge Gateway Jarak Jauh`},help:{"v1-jg9p7d-5o":`Header HTTP berbasis rahasia yang dikirimkan ke proksi berbasis identitas di depan Gateway jarak jauh yang dikonfigurasi. Header hanya dikirim ke origin yang persis sama dengan gateway.remote.url melalui WSS dan tidak pernah mengikuti pengalihan.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Kata Sandi Gateway Jarak Jauh`},help:{"v1-16jc0yx-7y":`Rahasia bersama yang dikirim dalam kolom kata sandi untuk mengautentikasi klien ini ke gateway jarak jauh. gateway.auth.mode pada server memilih rahasia yang dikonfigurasikan; kolom token maupun kata sandi klien dapat diterima. Kelola rahasia ini secara eksternal dan hindari nilai teks biasa dalam konfigurasi yang di-commit.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Kebijakan Kunci Host SSH Gateway Jarak Jauh`},help:{"v1-7qoxtb-49":`Kebijakan verifikasi kunci host SSH macOS. "strict" memerlukan kunci host yang sudah dipercaya; "openssh" secara eksplisit mendelegasikan verifikasi ke konfigurasi OpenSSH yang berlaku.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Identitas SSH Gateway Jarak Jauh`},help:{"v1-hz2hsm-1f":`Jalur file identitas SSH opsional (diteruskan ke ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Target SSH Gateway Jarak Jauh`},help:{"v1-85w39w-2t":`Gateway jarak jauh melalui SSH (membuat terowongan dari port gateway ke localhost). Format: user@host atau user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Sidik Jari TLS Gateway Jarak Jauh`},help:{"v1-1ri16lk-23":`Sidik jari TLS sha256 yang diharapkan untuk gateway jarak jauh (sematkan untuk menghindari MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token Gateway Jarak Jauh`},help:{"v1-1pb9q8w-7v":`Rahasia bersama yang dikirim dalam kolom token untuk mengautentikasi klien ini ke Gateway jarak jauh. gateway.auth.mode pada server memilih rahasia yang dikonfigurasi; kolom token atau kata sandi klien dapat digunakan. Simpan melalui substitusi rahasia/variabel lingkungan dan rotasikan seiring perubahan autentikasi Gateway jarak jauh.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transportasi Gateway Jarak Jauh`},help:{"v1-1acfs7m-54":`Transportasi koneksi jarak jauh: "direct" menggunakan konektivitas URL yang dikonfigurasi, sedangkan "ssh" menggunakan terowongan melalui SSH. Gunakan SSH saat Anda memerlukan koneksi terowongan terenkripsi tanpa mengekspos port jarak jauh.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL Gateway Jarak Jauh`},help:{"v1-va7exe-1b":`URL WebSocket Gateway jarak jauh (ws:// atau wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Peran Operator Gateway`},help:{"v1-b59sc5-6w":`Peran operator opsional yang terikat pada profil untuk Gateway tim. Setiap peran bernama mengontrol akses ke sesi orang lain, isolasi sandbox, agen sesi dan eksekusi, serta cakupan operator yang diberikan; menghilangkan bagian ini akan mempertahankan perilaku operator yang ada.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Peran Operator Default`},help:{"v1-1v8add8-4u":`Peran wajib yang diberikan kepada profil terautentikasi tanpa penetapan eksplisit yang valid setiap kali peran operator dikonfigurasi. Namanya harus cocok dengan definisi peran yang dikonfigurasi.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definisi Peran Operator`},help:{"v1-uv91an-53":`Definisi peran yang tidak kosong dan diberi nama oleh administrator, yang menggabungkan kebijakan berbagi sesi, isolasi sandbox, akses agen, dan cakupan operator dengan pilihan yang telah ditetapkan, yang diterapkan pada profil pengguna terautentikasi.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definisi Peran Operator`},help:{"v1-p8tfws-6q":`Satu peran operator bernama. Setiap definisi harus secara eksplisit menyediakan kebijakan berbagi sesi, agen yang diizinkan untuk sesi dan eksekusi, serta batas maksimum cakupan operator. Definisi juga dapat mewajibkan isolasi sandbox untuk sesi yang baru dibuat dan kebijakan akses plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plugin Kebijakan Akses Peran Operator`},help:{"v1-1gq4q08-9n":`ID plugin opsional yang harus sama persis dan kebijakan akses Gateway-nya harus mengizinkan peran ini. Akses ditolak jika plugin tidak tersedia, dinonaktifkan, gagal dimuat, atau tidak menyediakan otoritas yang berlaku saat ini. ID plugin yang tidak tersedia tetap dianggap sebagai konfigurasi yang valid agar peran staf independen dan pemilik Gateway dapat memulihkan akses. Mengosongkan kolom ini tidak menambahkan ketergantungan pada plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Agen yang Diizinkan untuk Peran Operator`},help:{"v1-fvun18-4v":`Agen yang tersedia saat peran ini membuat sesi atau memulai eksekusi: tetapkan "*" untuk mengizinkan semua agen, cantumkan ID agen untuk hanya mengizinkan agen tersebut, atau gunakan daftar kosong untuk menonaktifkan keduanya.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Isolasi Sandbox Peran Operator`},help:{"v1-sknx21-66":`Isolasi eksekusi untuk sesi yang baru dibuat: "inherit" (default) menggunakan kebijakan agen; "required" secara permanen mewajibkan sandbox, bahkan saat mode sandbox agen dinonaktifkan, dan memblokir eksekusi jika backend tidak tersedia.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Batas Maksimum Cakupan Peran Operator`},help:{"v1-1selr2i-4s":`Daftar tertutup cakupan operator yang diberikan sebagai kewenangan koneksi maksimum peran ini. Cakupan yang diminta, diperoleh melalui pemasangan, diberikan berdasarkan identitas, dan ditingkatkan dibatasi pada cakupan yang juga tercantum dalam daftar ini.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Akses Sesi Peran Operator`},help:{"v1-hsoiop-45":`Izin berbagi sesi yang diberikan kepada peran ini untuk sesi yang dibuat oleh orang lain yang telah diautentikasi; sesi milik seseorang tetap dapat diakses oleh pemiliknya.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Akses Peran Operator ke Sesi Lain`},help:{"v1-vf8umx-5r":`Akses ke sesi orang lain: "none" menyembunyikannya, "view" mengizinkan pembacaan, "suggest" mengizinkan alur pemberian saran, dan "write" mengizinkan partisipasi. Keanggotaan sesi yang ditetapkan secara eksplisit dapat memberikan akses tambahan.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale Gateway`},help:{"v1-6ar9o-4x":`Pengaturan integrasi Tailscale untuk eksposur Serve/Funnel dan penanganan siklus hidup saat Gateway dimulai/ditutup. Biarkan nonaktif kecuali deployment Anda memang mengandalkan akses masuk melalui Tailscale.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Mode Tailscale Gateway`},help:{"v1-6l2099-5a":`Mode publikasi Tailscale: "off", "serve", atau "funnel" untuk jalur eksposur privat atau publik. Gunakan "serve" untuk akses khusus tailnet dan "funnel" hanya jika akses dari internet publik diperlukan.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Pengaman Migrasi Funnel Eksternal Tailscale Gateway`},help:{"v1-1mntkor-7q":`Pengaman migrasi yang sudah usang untuk mode='serve'. Jika Funnel eksternal masih menargetkan listener Gateway biasa, OpenClaw membiarkan eksposur tetap seperti semula dan memperingatkan bahwa hanya webhook yang diautentikasi oleh plugin yang tetap dapat digunakan hingga autentikasi kata sandi dikonfigurasi dan mode dimigrasikan ke 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Terminal Operator`},help:{"v1-18f5rgm-8b":`Terminal operator yang disediakan untuk Control UI dan klien seluler: shell berbasis PTY pada host Gateway, yang dibatasi untuk sesi operator dengan cakupan admin. Terminal dimulai di ruang kerja agen target dan aksesnya ditolak untuk agen yang sepenuhnya berada dalam sandbox (sandbox.mode 'all'), alih-alih memberikan shell host tanpa pembatasan.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Batas Waktu Sesi Terminal Operator yang Terlepas`},help:{"v1-k6qbgr-9e":`Jumlah detik sesi terminal tetap aktif setelah koneksinya terputus (laptop dalam mode tidur, halaman dimuat ulang), sehingga dapat disambungkan kembali melalui terminal.attach dengan keluaran terbarunya diputar ulang. Atur ke 0 untuk menghentikan sesi segera setelah koneksi terputus. Default: 300 (5 menit). Sesi yang terputus tetap menjalankan perintahnya, jadi persingkat durasi ini pada host bersama atau yang dapat diakses publik.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Terminal Operator Diaktifkan`},help:{"v1-1nez06v-7p":`Mengaktifkan terminal operator untuk klien dengan cakupan admin (default: true). Fitur ini menyediakan shell browser/seluler dengan lingkungan proses gateway; tetapkan false untuk menonaktifkannya pada penerapan yang tidak mengizinkan operator admin mengakses shell host. Perubahan diterapkan tanpa memulai ulang Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Shell Terminal Operator`},help:{"v1-19mfe6t-5i":`Berkas eksekusi shell yang diluncurkan terminal operator. Biarkan tidak diatur untuk menggunakan shell login host ($SHELL di Unix, %ComSpec% di Windows), atau tetapkan interpreter tertentu untuk lingkungan operator yang konsisten.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS Gateway`},help:{"v1-1dx77dq-4z":`Pengaturan sertifikat dan kunci TLS untuk terminasi HTTPS langsung di proses gateway. Gunakan sertifikat yang ditentukan secara eksplisit di lingkungan produksi dan hindari paparan teks biasa di jaringan yang tidak tepercaya.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Pembuatan Otomatis Sertifikat TLS Gateway`},help:{"v1-1ld6uiu-4w":`Membuat pasangan sertifikat/kunci TLS lokal secara otomatis jika berkas tertentu belum dikonfigurasi. Gunakan hanya untuk lingkungan lokal/pengembangan dan ganti dengan sertifikat yang valid untuk lalu lintas produksi.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Jalur CA TLS Gateway`},help:{"v1-andqlu-52":`Jalur bundel CA opsional untuk verifikasi klien atau persyaratan rantai kepercayaan khusus di batas jaringan Gateway. Gunakan ini jika PKI privat atau rantai sertifikat khusus menjadi bagian dari penerapan.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Jalur Sertifikat TLS Gateway`},help:{"v1-1wznaof-4q":`Jalur sistem berkas ke berkas sertifikat TLS yang digunakan oleh Gateway saat TLS diaktifkan. Gunakan jalur sertifikat terkelola dan pastikan otomatisasi perpanjangan tetap selaras dengan lokasi ini.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS Gateway Diaktifkan`},help:{"v1-ykhwp0-4o":`Mengaktifkan terminasi TLS pada listener Gateway agar klien terhubung langsung melalui HTTPS/WSS. Biarkan tetap aktif jika Gateway dapat diakses langsung dari internet atau berada di batas jaringan yang tidak tepercaya.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Jalur Kunci TLS Gateway`},help:{"v1-15knri0-4i":`Jalur sistem berkas ke berkas kunci privat TLS yang digunakan oleh Gateway saat TLS diaktifkan. Batasi izin akses berkas kunci ini dan lakukan rotasi sesuai kebijakan keamanan Anda.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Kebijakan Akses Alat Gateway`},help:{"v1-1ffol26-5a":`Kebijakan izinkan/tolak akses alat pada tingkat Gateway yang dapat membatasi ketersediaan alat saat runtime secara independen dari profil agen/alat. Gunakan ini untuk kontrol darurat secara menyeluruh dan penguatan keamanan lingkungan produksi.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Daftar Alat yang Diizinkan Gateway`},help:{"v1-163khb1-4y":`Daftar eksplisit alat yang diizinkan pada tingkat Gateway saat Anda ingin hanya sejumlah kecil alat tersedia saat runtime. Gunakan ini untuk lingkungan dengan pembatasan ketat yang mengharuskan cakupan alat dikontrol secara ketat.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Daftar Alat yang Ditolak Gateway`},help:{"v1-1lhssnf-4o":`Daftar penolakan alat yang eksplisit di tingkat Gateway untuk memblokir alat berisiko meskipun kebijakan tingkat bawah mengizinkannya. Gunakan aturan penolakan untuk respons darurat dan penguatan pertahanan berlapis.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR Proksi Tepercaya Gateway`},help:{"v1-n5zcvf-4f":`Daftar CIDR/IP proksi hulu yang diizinkan memberikan header identitas klien yang diteruskan. Batasi daftar ini agar simpul perantara yang tidak tepercaya tidak dapat menyamar sebagai pengguna.`}},hooks:{label:{"v1-j9ywl7-5":`Kait`},help:{"v1-1mzh0ry-5v":`Antarmuka otomatisasi webhook masuk untuk memetakan peristiwa eksternal ke tindakan pengaktifan atau tindakan agen di OpenClaw. Amankan dengan kontrol token/sesi/agen yang eksplisit sebelum membukanya untuk akses dari luar jaringan tepercaya.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`ID Agen yang Diizinkan untuk Hook`},help:{"v1-hree88-7c":`Daftar ID agen efektif yang boleh ditargetkan oleh permintaan dan pemetaan hook, termasuk perutean ke agen default saat agentId tidak disertakan. Gunakan ini untuk membatasi peristiwa otomatisasi ke agen layanan khusus dan mengurangi cakupan dampak jika token hook terekspos.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Awalan Kunci Sesi yang Diizinkan untuk Hook`},help:{"v1-b346oh-4r":`Daftar awalan kunci sesi yang diterima untuk permintaan hook masuk saat kunci yang diberikan pemanggil diaktifkan. Gunakan awalan yang spesifik untuk mencegah injeksi kunci sesi sembarang.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Izinkan Kunci Sesi dalam Permintaan Hook`},help:{"v1-11n9ps-52":`Mengizinkan pemanggil memberikan kunci sesi dalam permintaan hook jika bernilai true, sehingga perutean dapat dikendalikan oleh pemanggil. Pertahankan nilai false kecuali integrator tepercaya secara eksplisit memerlukan pengelompokan sesi khusus.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Kunci Sesi Default Hook`},help:{"v1-bzdgkn-57":`Kunci sesi cadangan yang digunakan untuk pengiriman hook saat permintaan tidak menyediakannya melalui saluran yang diizinkan. Gunakan kunci yang stabil tetapi terbatas cakupannya agar percakapan otomatisasi yang tidak terkait tidak tercampur.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hook Diaktifkan`},help:{"v1-1mixmjf-4n":`Mengaktifkan endpoint hook dan alur eksekusi pemetaan untuk permintaan webhook masuk. Biarkan nonaktif kecuali Anda sedang secara aktif mengarahkan peristiwa eksternal ke gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Hook Gmail`},help:{"v1-4cibmt-4r":`Pengaturan integrasi push Gmail yang digunakan untuk notifikasi Pub/Sub dan penyediaan layanan callback lokal opsional. Jika memungkinkan, batasi cakupannya pada akun otomatisasi Gmail khusus.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Akun Hook Gmail`},help:{"v1-12l1h96-4v":`Pengenal akun Google yang digunakan untuk operasi pemantauan/langganan Gmail dalam integrasi hook ini. Gunakan akun kotak surat khusus otomatisasi untuk mengisolasi izin operasional.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Izinkan Konten Eksternal Tidak Aman pada Hook Gmail`},help:{"v1-1w3gdvs-55":`Jika diaktifkan, mengizinkan konten Gmail eksternal yang kurang disanitasi untuk diproses. Biarkan nonaktif agar pengaturan default lebih aman, dan aktifkan hanya untuk aliran email tepercaya dengan transformasi terkontrol.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`URL Callback Hook Gmail`},help:{"v1-19fhn6q-4z":`URL callback publik yang dipanggil Gmail atau perantara untuk mengirimkan notifikasi ke alur hook ini. Lindungi URL ini dengan validasi token dan akses jaringan yang dibatasi.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Sertakan Isi Pesan pada Hook Gmail`},help:{"v1-14cf1c3-52":`Jika true, ambil dan sertakan isi email untuk pemetaan/pemrosesan agen selanjutnya. Tetap gunakan false kecuali teks isi diperlukan, karena opsi ini meningkatkan ukuran dan sensitivitas muatan data.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Label Hook Gmail`},help:{"v1-9zpdg8-4g":`Filter label Gmail opsional yang membatasi pesan berlabel mana yang memicu peristiwa hook. Gunakan filter yang spesifik agar otomatisasi tidak dibanjiri pesan kotak masuk yang tidak terkait.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Byte Isi Maksimum Hook Gmail`},help:{"v1-2aaxx1-4b":`Jumlah maksimum byte muatan data Gmail yang diproses per peristiwa saat includeBody diaktifkan. Gunakan batas yang konservatif untuk mengurangi biaya dan risiko pemrosesan pesan berukuran terlalu besar.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Penggantian Model Hook Gmail`},help:{"v1-1var65t-59":`Penggantian model opsional untuk eksekusi yang dipicu Gmail saat otomatisasi kotak surat perlu menggunakan perilaku model khusus. Biarkan tidak diatur untuk mewarisi pengaturan default agen, kecuali tugas kotak surat memerlukan penanganan khusus.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Token Push Hook Gmail`},help:{"v1-h1vx01-4o":`Token rahasia bersama yang wajib disertakan pada callback hook push Gmail sebelum notifikasi diproses. Gunakan substitusi variabel lingkungan dan ganti token secara berkala jika endpoint callback dapat diakses dari luar.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Interval Perpanjangan Hook Gmail (menit)`},help:{"v1-pr1z9-49":`Frekuensi perpanjangan dalam menit untuk langganan pemantauan Gmail agar tidak kedaluwarsa. Atur interval lebih pendek daripada masa berlaku yang ditetapkan penyedia dan pantau kegagalan perpanjangan di log.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Server Lokal Hook Gmail`},help:{"v1-hom4wq-54":`Blok pengaturan server callback lokal untuk menerima notifikasi Gmail secara langsung tanpa lapisan ingress terpisah. Aktifkan hanya jika proses ini harus menangani lalu lintas webhook sendiri.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Alamat Bind Server Hook Gmail`},help:{"v1-55bieu-4d":`Alamat bind untuk server HTTP callback Gmail lokal yang digunakan saat melayani hook secara langsung. Batasi ke loopback saja kecuali ingress eksternal memang diperlukan.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Jalur Server Hook Gmail`},help:{"v1-1jqhcw4-4h":`Jalur HTTP pada server callback Gmail lokal tempat notifikasi push diterima. Pastikan jalur ini sesuai dengan konfigurasi langganan agar peristiwa tidak terlewat.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Port Server Hook Gmail`},help:{"v1-1yku7dz-43":`Port untuk server HTTP callback Gmail lokal saat mode serve diaktifkan. Gunakan port khusus untuk menghindari konflik dengan antarmuka gateway/kontrol.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Langganan Hook Gmail`},help:{"v1-127h8vg-5b":`Langganan Pub/Sub yang digunakan oleh gateway untuk menerima notifikasi perubahan Gmail dari topik yang dikonfigurasi. Pastikan kepemilikan langganan jelas agar beberapa konsumen tidak berebut secara tak terduga.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale Hook Gmail`},help:{"v1-7jzidp-4l":`Blok konfigurasi eksposur Tailscale untuk memublikasikan callback Gmail melalui rute Serve/Funnel. Gunakan mode tailnet privat sebelum mengaktifkan jalur ingress publik apa pun.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Mode Tailscale Hook Gmail`},help:{"v1-vhm395-4u":`Mode eksposur Tailscale untuk callback Gmail: "off", "serve", atau "funnel". Gunakan "serve" untuk pengiriman melalui tailnet privat dan "funnel" hanya jika akses masuk dari internet publik diperlukan.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Jalur Tailscale untuk Hook Gmail`},help:{"v1-fr8qi-4m":`Jalur yang dipublikasikan oleh Tailscale Serve/Funnel untuk meneruskan callback Gmail saat diaktifkan. Pastikan jalur ini selaras dengan konfigurasi webhook Gmail agar permintaan mencapai handler yang diharapkan.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Target Tailscale untuk Hook Gmail`},help:{"v1-1twwxge-47":`Target layanan lokal yang menjadi tujuan penerusan oleh Tailscale Serve/Funnel (misalnya http://127.0.0.1:8787). Gunakan target loopback yang eksplisit untuk menghindari perutean yang ambigu.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Penggantian Tingkat Penalaran Hook Gmail`},help:{"v1-17owk9q-4z":`Penggantian tingkat upaya penalaran untuk eksekusi agen yang dipicu Gmail: "off", "minimal", "low", "medium", atau "high". Gunakan nilai default yang rendah untuk otomatisasi kotak masuk rutin guna mengendalikan biaya dan latensi.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Topik Pub/Sub Hook Gmail`},help:{"v1-iled0e-4p":`Nama topik Google Pub/Sub yang digunakan oleh pemantauan Gmail untuk memublikasikan notifikasi perubahan akun ini. Pastikan IAM topik memberikan akses publikasi kepada Gmail sebelum mengaktifkan pemantauan.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Hook Internal`},help:{"v1-piq9k-4v":`Pengaturan runtime hook internal untuk handler peristiwa bawaan/kustom yang dimuat dari jalur modul. Gunakan ini untuk otomatisasi tepercaya dalam proses dan batasi cakupan pemuatan handler secara ketat.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Hook Internal Diaktifkan`},help:{"v1-1wv0289-4c":`Mengaktifkan pemrosesan untuk hook internal dan entri yang dikonfigurasi dalam runtime hook internal. Biarkan nonaktif kecuali hook internal memang sengaja dikonfigurasi.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Entri Hook Internal`},help:{"v1-1ovi38l-4o":`Catatan entri hook internal yang dikonfigurasi untuk mendaftarkan handler runtime konkret dan metadata. Pastikan entri ditetapkan secara eksplisit dan diberi versi agar perilaku di lingkungan produksi dapat diaudit.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Pemuat Hook Internal`},help:{"v1-11re5ph-4p":`Pengaturan pemuat hook internal yang mengontrol lokasi pencarian modul handler saat startup. Batasi direktori akar pemuatan untuk mengurangi konflik modul atau penimpaan modul yang tidak disengaja.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Direktori Tambahan Hook Internal`},help:{"v1-1xfdqxg-4c":`Direktori tambahan untuk mencari modul hook internal di luar jalur pemuatan default. Batasi jumlahnya dan kelola secara terkendali untuk mengurangi penimpaan modul yang tidak disengaja.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Pemetaan Hook`},help:{"v1-frhp3v-5i":`Aturan pemetaan berurutan yang mencocokkan permintaan hook masuk dan memilih tindakan pengaktifan atau agen dengan perutean pengiriman opsional. Tempatkan pemetaan yang spesifik terlebih dahulu agar aturan berpola luas tidak menangkap semuanya.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Tindakan Pemetaan Hook`},help:{"v1-1r5zt5f-5f":`Jenis tindakan pemetaan: "wake" memicu alur pengaktifan agen, sedangkan "agent" mengirim langsung ke penanganan agen. Gunakan "agent" untuk eksekusi langsung dan "wake" jika pemrosesan berbasis heartbeat lebih diutamakan.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`ID Agen Pemetaan Hook`},help:{"v1-l0uioz-4y":`ID agen tujuan untuk eksekusi pemetaan saat perutean tindakan tidak boleh menggunakan nilai default. Gunakan agen otomatisasi khusus untuk mengisolasi perilaku webhook dari sesi operator interaktif.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Izinkan Konten Eksternal Tidak Aman dalam Pemetaan Hook`},help:{"v1-1np9426-57":`Jika true, konten pemetaan dapat menyertakan data payload eksternal yang kurang disanitasi dalam pesan yang dihasilkan. Pertahankan false sebagai default dan aktifkan hanya untuk sumber tepercaya dengan logika transformasi yang telah ditinjau.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Saluran Pengiriman Pemetaan Hook`},help:{"v1-oz7pu5-5s":`Penggantian saluran pengiriman untuk keluaran pemetaan (misalnya "last", "telegram", "discord", "slack", "signal", "imessage", atau "msteams"). Tetapkan penggantian saluran secara eksplisit untuk menghindari pengiriman lintas saluran yang tidak disengaja.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Kirim Balasan Pemetaan Hook`},help:{"v1-12tbbam-5o":`Mengontrol apakah hasil eksekusi pemetaan dikirim kembali ke saluran tujuan atau diproses tanpa pengiriman. Nonaktifkan pengiriman untuk otomatisasi latar belakang yang tidak boleh memposting keluaran yang terlihat oleh pengguna.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Kunci Penyebaran Pemetaan Hook`},help:{"v1-1d593op-7e":`Kunci array tingkat teratas dalam payload yang menjadi dasar penyebaran pemetaan: setiap elemen memicu tindakannya sendiri, dan templat atau transformasi menerima payload dengan array yang hanya berisi elemen saat ini. Preset Gmail menggunakan forEach: messages sehingga pengiriman push secara batch memicu satu eksekusi per email.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID Pemetaan Hook`},help:{"v1-q1t4zw-57":`Pengidentifikasi stabil opsional untuk entri pemetaan hook yang digunakan untuk audit, pemecahan masalah, dan pembaruan tertarget. Gunakan ID unik agar log dan perbedaan konfigurasi dapat merujuk ke pemetaan tanpa ambiguitas.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Pencocokan Pemetaan Hook`},help:{"v1-6u73k2-5a":`Objek pengelompokan untuk kondisi pencocokan pemetaan, seperti jalur dan sumber, sebelum perutean tindakan diterapkan. Pastikan kriteria pencocokan spesifik agar lalu lintas webhook yang tidak terkait tidak memicu otomatisasi.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Jalur Pencocokan Pemetaan Hook`},help:{"v1-1d7dc5j-4k":`Kondisi pencocokan jalur untuk pemetaan hook, biasanya dibandingkan dengan jalur permintaan masuk. Gunakan ini untuk membedakan perilaku otomatisasi berdasarkan kelompok jalur endpoint webhook.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Sumber Pencocokan Pemetaan Hook`},help:{"v1-177zgy7-52":`Kondisi pencocokan sumber untuk pemetaan hook, biasanya ditetapkan oleh metadata hulu tepercaya atau logika adaptor. Gunakan pengidentifikasi sumber yang stabil agar perutean tetap deterministik pada setiap percobaan ulang.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Templat Pesan Pemetaan Hook`},help:{"v1-ggqszl-5c":`Templat untuk mengolah masukan pemetaan terstruktur menjadi konten pesan akhir yang dikirim ke jalur tindakan tujuan. Pastikan templat deterministik agar penguraian dan perilaku di tahap hilir tetap stabil.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Penggantian Model Pemetaan Hook`},help:{"v1-10qyo4j-5e":`Penggantian model opsional untuk eksekusi yang dipicu pemetaan ketika otomatisasi perlu menggunakan model yang berbeda dari model bawaan agen. Gunakan seperlunya agar perilaku tetap dapat diprediksi di seluruh eksekusi pemetaan.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Nama Pemetaan Hook`},help:{"v1-zrd9tn-4v":`Nama tampilan pemetaan yang mudah dibaca, digunakan dalam diagnostik dan UI konfigurasi untuk operator. Gunakan nama yang ringkas dan deskriptif agar tujuan perutean jelas saat peninjauan insiden.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Kunci Sesi Pemetaan Hook`},help:{"v1-lfnt1n-58":`Penggantian kunci sesi secara eksplisit untuk pesan yang dikirim melalui pemetaan guna mengontrol kesinambungan utas. Gunakan kunci stabil dengan cakupan tertentu agar peristiwa berulang saling terhubung tanpa masuk ke percakapan yang tidak terkait.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Mode Sesi Pemetaan Hook`},help:{"v1-1ggtdze-5k":`Mengontrol kesinambungan sesi pemetaan: "isolated" memulai sesi eksekusi baru, sedangkan "persistent" menggunakan kembali sessionKey yang telah ditentukan. Tetap gunakan isolated kecuali integrasi memang memerlukan konteks yang bertahan lama.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Templat Teks Pemetaan Hook`},help:{"v1-1rg732b-4y":`Templat cadangan khusus teks yang digunakan ketika perenderan payload berformat kaya tidak diinginkan atau tidak didukung. Gunakan ini untuk menyediakan teks ringkasan yang ringkas dan konsisten bagi antarmuka pengiriman chat.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Penggantian Pengaturan Penalaran Pemetaan Hook`},help:{"v1-17hq8me-57":`Pengaturan opsional untuk mengganti tingkat upaya berpikir pada eksekusi yang dipicu pemetaan guna menyeimbangkan latensi dan kedalaman penalaran. Gunakan tingkat rendah atau minimal untuk hook bervolume tinggi, kecuali penalaran yang lebih mendalam memang diperlukan.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Batas Waktu Pemetaan Hook (detik)`},help:{"v1-1r44ox2-4i":`Durasi maksimum yang diizinkan untuk menjalankan tindakan pemetaan sebelum penanganan batas waktu diterapkan. Gunakan batas yang lebih ketat untuk sumber webhook bervolume tinggi guna mencegah penumpukan antrean.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Tujuan Pengiriman Pemetaan Hook`},help:{"v1-1p7928e-55":`Pengidentifikasi tujuan dalam kanal yang dipilih saat balasan pemetaan harus diarahkan ke target tetap. Verifikasi format tujuan khusus penyedia sebelum mengaktifkan pemetaan di lingkungan produksi.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformasi Pemetaan Hook`},help:{"v1-14igxpm-5m":`Blok konfigurasi transformasi yang menentukan prapemrosesan modul/ekspor sebelum penanganan tindakan pemetaan. Gunakan transformasi hanya dari jalur kode yang telah ditinjau dan jaga perilakunya tetap deterministik agar otomatisasi dapat diulang secara konsisten.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Ekspor Transformasi Hook`},help:{"v1-atn8v-4b":`Ekspor bernama yang akan dipanggil dari modul transformasi; jika tidak ditentukan, ekspor default modul akan digunakan. Atur ini jika satu file memuat beberapa penangan transformasi.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Modul Transformasi Hook`},help:{"v1-56futq-4v":`Jalur relatif modul transformasi yang dimuat dari hooks.transformsDir untuk menulis ulang payload masuk sebelum dikirim. Pastikan modul tetap lokal, telah ditinjau, dan bebas dari pola penelusuran jalur.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Mode Pengaktifan Pemetaan Hook`},help:{"v1-1dzqfnw-59":`Mode penjadwalan pengaktifan: "now" langsung mengaktifkan, sedangkan "next-heartbeat" menunda hingga siklus heartbeat berikutnya. Gunakan mode tertunda untuk otomatisasi berprioritas lebih rendah yang dapat menoleransi sedikit penundaan.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Jalur Endpoint Hook`},help:{"v1-1l9ijzv-4u":"Jalur HTTP yang digunakan oleh endpoint hook (misalnya `/hooks`) pada server kontrol gateway. Gunakan jalur yang sulit ditebak dan kombinasikan dengan validasi token untuk pertahanan berlapis."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Preset Hook`},help:{"v1-dp8m0l-4v":`Paket preset hook bernama yang diterapkan saat pemuatan untuk menginisialisasi pemetaan standar dan perilaku bawaan. Tetapkan penggunaan preset secara eksplisit agar operator dapat mengaudit otomatisasi yang aktif.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Token Autentikasi Hook`},help:{"v1-1ihf6mv-82":`Token bearer bersama yang diperiksa oleh titik masuk hook untuk autentikasi permintaan sebelum pemetaan dijalankan. Perlakukan pemegang token sebagai pemanggil tepercaya sepenuhnya untuk antarmuka masuk hook, bukan sebagai peran nonpemilik yang terpisah. Gunakan substitusi variabel lingkungan dan rotasi token secara berkala saat endpoint webhook dapat diakses dari internet.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Direktori Transformasi Hook`},help:{"v1-1ayj9p0-4t":`Direktori dasar untuk modul transformasi hook yang dirujuk oleh jalur transform.module dalam pemetaan. Gunakan direktori repositori yang terkontrol agar impor dinamis tetap dapat ditinjau dan diprediksi.`}},logging:{label:{"v1-rq08xq-7":`Pencatatan Log`},help:{"v1-11an9pb-5e":`Kontrol perilaku pencatatan log untuk tingkat keparahan, tujuan keluaran, pemformatan, dan penyamaran data sensitif. Pastikan tingkat log dan penyamaran cukup ketat untuk lingkungan produksi, sambil tetap mempertahankan informasi diagnostik yang berguna.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Buku Besar Audit`},help:{"v1-1lauvy2-6w":`Riwayat audit terbatas yang hanya berisi metadata untuk ditinjau operator. Catatan eksekusi dan alat diaktifkan secara default; metadata siklus hidup pesan memerlukan persetujuan terpisah karena sensitif terhadap privasi. Penulisan di latar belakang dilakukan sebisa mungkin, bukan sebagai arsip kepatuhan yang menjamin tidak ada data hilang.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Buku Besar Audit Diaktifkan`},help:{"v1-snknxb-4v":`Mencatat peristiwa audit baru untuk eksekusi, alat, dan pesan yang diaktifkan. Default: true. Perubahan langsung berlaku; penulisan yang telah diterima akan diselesaikan dan baris yang disimpan tetap dapat dikueri hingga kedaluwarsa.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Audit Identitas Eksekusi`},help:{"v1-1ucirwv-5b":`Menyimpan atribusi identitas eksekusi dalam batas tertentu untuk pemeriksaan eksekusi spesifik. Default: false. Memerlukan logging.audit.enabled dan berlaku untuk eksekusi yang baru diterima; konteks yang sudah ada tetap tidak berubah.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Cakupan Audit Pesan`},help:{"v1-1yg4lc3-76":`Mengontrol catatan siklus hidup pesan tanpa konten: "off" (default), "direct" hanya untuk percakapan langsung yang diketahui, atau "all" untuk jenis percakapan langsung, grup, kanal, dan yang tidak diketahui. Memerlukan logging.audit.enabled. Perubahan berlaku untuk peristiwa siklus hidup berikutnya.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Tingkat Log Konsol`},help:{"v1-16badbd-5u":`Ambang tingkat log khusus konsol: "silent", "fatal", "error", "warn", "info", "debug", atau "trace" untuk mengontrol keluaran terminal. Gunakan ini untuk mengurangi keluaran konsol lokal sambil tetap menyimpan log file yang lebih terperinci jika diperlukan.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Gaya Log Konsol`},help:{"v1-d7u0iq-3q":`Gaya format keluaran konsol: "pretty" atau "json". Gunakan json untuk alur pemrosesan oleh mesin dan pretty untuk alur kerja terminal yang mengutamakan keterbacaan bagi manusia.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Jalur File Log`},help:{"v1-16gaitv-4w":`Jalur file opsional untuk menyimpan keluaran log sebagai tambahan atau pengganti pencatatan log konsol. Gunakan jalur terkelola yang dapat ditulisi dan sesuaikan retensi/rotasi dengan kebijakan operasional Anda.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Tingkat Log`},help:{"v1-1r5yku0-5o":`Ambang tingkat log utama untuk keluaran pencatat log runtime: "silent", "fatal", "error", "warn", "info", "debug", atau "trace". Gunakan "info" atau "warn" untuk produksi, dan gunakan debug/trace hanya selama investigasi.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Pola Penyamaran Kustom`},help:{"v1-1esa6eg-7k":`String regex kustom menggantikan daftar string default untuk keluaran log/transkrip dan melengkapi aturan batas keamanan untuk UI/alat/diagnostik. Perlindungan bawaan untuk isi formulir, autentikasi terstruktur, dan kunci AWS tanpa penanda selalu berlaku. Gunakan ini untuk menyamarkan token dan pengenal khusus deployment.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Definisi server MCP global yang dikelola oleh OpenClaw. OpenClaw yang disematkan dan adaptor runtime lainnya dapat menggunakan server ini tanpa menyimpannya di dalam pengaturan proyek milik runtime.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`Aplikasi MCP`},help:{"v1-amyd91-38":`Dukungan UI MCP Apps. Jika diaktifkan, server MCP yang dikonfigurasi dapat menyediakan tampilan HTML interaktif untuk hasil alatnya.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps Diaktifkan`},help:{"v1-ghqy98-3w":`Rendering MCP Apps dan jembatan aplikasi ke server yang diaktifkan secara opsional. Biarkan nonaktif kecuali Anda memercayai server MCP yang dikonfigurasi yang menyediakan sumber daya UI aplikasi.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Origin Sandbox MCP Apps`},help:{"v1-1sxv3mf-6v":`Origin HTTP(S) publik khusus yang opsional untuk MCP Apps. Gunakan ini di belakang reverse proxy atau terminator TLS dan teruskan melalui proxy hanya ke port sandbox MCP Apps yang dikonfigurasi. Origin ini harus berbeda dari origin Control UI dan tidak boleh menyajikan konten yang memerlukan autentikasi.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Port Sandbox MCP Apps`},help:{"v1-1b8n71l-4p":`Port listener khusus untuk sandbox MCP Apps. Nilai defaultnya adalah port Gateway ditambah satu. Tetapkan port yang belum digunakan jika layanan lokal lain atau profil Gateway sudah menggunakan port tersebut.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`Server MCP`},help:{"v1-157ozoz-42":`Definisi server MCP bernama. OpenClaw menyimpannya dalam konfigurasinya sendiri dan adaptor runtime menentukan transport mana yang didukung saat eksekusi.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Autentikasi Server MCP`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Sertifikat Klien MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Kunci Klien MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Sertifikat Klien MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Kunci Klien MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Proyeksi MCP Codex`},help:{"v1-slcmq1-6x":`Metadata proyeksi OpenClaw khusus untuk thread app-server Codex. Metadata ini tidak memengaruhi sesi ACP atau konfigurasi harness Codex umum. Hilangkan blok ini agar server tetap tersedia untuk setiap agen app-server Codex dengan perilaku persetujuan MCP bawaan Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Agen MCP Codex`},help:{"v1-8q98n8-67":`ID agen OpenClaw opsional yang tidak kosong, yang harus menerima server MCP ini dalam konfigurasi thread app-server Codex. Daftar yang kosong, hanya berisi spasi, atau tidak valid akan menolak akses secara default; jika tidak disertakan, server diproyeksikan untuk semua agen app-server Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Persetujuan Alat MCP Codex`},help:{"v1-1xql0qr-3d":`Penamaan asli Codex untuk mode persetujuan alat MCP per server yang sama. Utamakan penggunaan defaultToolsApprovalMode dalam konfigurasi OpenClaw.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Persetujuan Alat MCP Codex`},help:{"v1-y5vsqq-3s":`Mode persetujuan alat MCP Codex opsional untuk server ini: "auto", "prompt", atau "approve". Gunakan hanya untuk server MCP yang memang Anda percayai.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Batas Waktu Koneksi MCP (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Server MCP Diaktifkan`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Profil Autentikasi OAuth MCP`},help:{"v1-fcrb4u-5z":`ID profil autentikasi yang mendukung penyegaran, digunakan untuk menyisipkan token bearer saat ini ke server MCP jarak jauh ini. Jika diatur, OpenClaw mencari dan menyegarkan profil saat runtime dan tidak meneruskan data penyegaran ke komponen hilir.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL Metadata Klien OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Identitas OAuth MCP`},help:{"v1-1ie6ys7-59":`Kepemilikan kredensial OAuth untuk server ini. Abaikan kolom ini atau gunakan "shared" untuk kredensial yang dikelola operator; gunakan "per-requester" agar setiap pengirim yang terautentikasi dapat menghubungkan akunnya sendiri.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`URL Pengalihan OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Cakupan OAuth MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Batas Waktu Permintaan MCP (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Verifikasi TLS MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Verifikasi TLS MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Pemanggilan Alat MCP Secara Paralel`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Pemanggilan Alat MCP Secara Paralel`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Pemilihan Alat MCP`},help:{"v1-10poyzb-4v":`Pemilihan alat MCP per server. Gunakan include untuk menampilkan hanya nama alat MCP yang dipilih, atau exclude untuk menyembunyikan nama alat MCP yang dipilih. Entri menerima nama persis dan pola glob '*' sederhana.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Alat MCP yang Dikecualikan`},help:{"v1-ijrc5y-1u":`Nama alat MCP yang persis atau pola glob '*' sederhana untuk disembunyikan dari server ini.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Alat MCP yang Disertakan`},help:{"v1-89fdfq-3o":`Nama alat MCP yang persis atau pola glob '*' sederhana untuk disediakan dari server ini. Jika tidak ditentukan, semua alat server tetap dapat digunakan kecuali yang dikecualikan.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL Sesi MCP yang Tidak Aktif (ms)`},help:{"v1-j9si74-87":`Penghentian opsional runtime MCP sesi OpenClaw saat tidak aktif, dalam milidetik. Jika tidak diatur atau bernilai 0, runtime tetap berjalan hingga sesi dibersihkan atau Gateway dimatikan. Nilai positif dibulatkan ke bawah; sewa aktif dan akuisisi yang tertunda mencegah penghentian. Runtime milik eksekusi tetap dihentikan saat eksekusi sekali jalan berakhir.`}},memory:{label:{"v1-oopaku-6":`Memori`},help:{"v1-1wlx40m-13":`Konfigurasi memori bawaan (global).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Mode Sitasi Memori`},help:{"v1-1q6dxr5-4u":`Mengontrol visibilitas sitasi dalam balasan: "auto" menampilkan sitasi saat berguna, "on" selalu menampilkannya, dan "off" menyembunyikannya. Pertahankan "auto" sebagai pengaturan default yang menyeimbangkan informasi berguna dan informasi yang tidak perlu.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Pencarian Memori`},help:{"v1-1ukbud1-25":`Pencarian vektor pada MEMORY.md dan memory/*.md (mendukung pengaturan khusus per agen).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Cache Embedding Pencarian Memori`},help:{"v1-d8h2e4-5b":`Menyimpan embedding potongan yang telah dihitung ke cache di SQLite agar pengindeksan ulang dan pembaruan inkremental berjalan lebih cepat (default: true). Biarkan tetap aktif kecuali saat menyelidiki keakuratan cache atau meminimalkan penggunaan disk.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Jenis Input Dokumen Pencarian Memori`},help:{"v1-1ui33sv-5f":"Nilai `input_type` opsional khusus penyedia untuk embedding memori dokumen dan pengindeksan. Gunakan ini dengan endpoint embedding asimetris yang kompatibel dengan OpenAI dan memerlukan label bagian teks atau dokumen."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Aktifkan Pencarian Memori`},help:{"v1-14f11b9-4t":`Sakelar utama untuk perilaku pengindeksan dan pengambilan data pencarian memori pada profil agen ini. Tetap aktifkan untuk pengingatan semantik, dan nonaktifkan jika Anda menginginkan respons yang sepenuhnya tanpa status tersimpan.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Indeks Sesi Pencarian Memori (Eksperimental)`},help:{"v1-qvhv8z-3i":`Mengindeks transkrip sesi ke dalam pencarian memori. Pertahankan pengaturan pengganti lanjutan ini jika pewarisan pengingatan di tingkat akar dan per agen berbeda.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Jalur Memori Tambahan`},help:{"v1-ojqokq-7i":`Menambahkan direktori atau file .md tambahan ke indeks memori selain file memori bawaan. Entri dapat berupa string jalur atau objek dengan pola glob relatif terhadap akar. Saat memori multimodal diaktifkan, file gambar/audio yang cocok di bawah jalur ini juga dapat diindeks.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Jalur Memori Tambahan`},help:{"v1-b9mbq8-3m":`Menetapkan direktori atau file memori tambahan. Jalur relatif ditentukan dari ruang kerja agen; entri file langsung diindeks persis sesuai jalur yang ditentukan.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Pola Jalur Memori Tambahan`},help:{"v1-j8br1v-4e":`Membatasi entri direktori pada file yang didukung dan cocok dengan glob relatif terhadap akar ini, misalnya "runbooks/**/*.md". Jangan sertakan pola ini untuk memindai semua file yang didukung secara rekursif.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Penyedia Cadangan Pencarian Memori`},help:{"v1-1r6368w-6p":`Penyedia cadangan yang digunakan saat embedding utama gagal: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local", atau "none". Tetapkan penyedia cadangan yang nyata untuk keandalan di lingkungan produksi; gunakan "none" hanya jika Anda lebih memilih kegagalan yang dinyatakan secara eksplisit.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Jenis Input Pencarian Memori`},help:{"v1-26vbwe-5u":"Gunakan nilai `input_type` opsional khusus penyedia ini hanya jika label yang sama harus diterapkan pada permintaan embedding kueri dan dokumen. Untuk penyedia asimetris, utamakan queryInputType dan documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Jalur Model Embedding Lokal`},help:{"v1-13ymbnt-5q":"Menentukan sumber model embedding lokal untuk pencarian memori lokal, seperti jalur file GGUF atau URI `hf:`. Gunakan ini hanya jika provider diatur ke `local`, dan verifikasi kompatibilitas model sebelum membangun ulang indeks berukuran besar."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Model Pencarian Memori`},help:{"v1-11pohrl-59":`Penggantian model embedding yang digunakan oleh penyedia memori terpilih saat model nonbawaan diperlukan. Atur ini hanya jika Anda perlu menyesuaikan kualitas cakupan hasil/biaya secara eksplisit di luar pengaturan bawaan penyedia.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Pencarian Memori Multimodal`},help:{"v1-1jn02s-9e":'Pengaturan memori multimodal opsional untuk mengindeks file gambar dan audio dari jalur tambahan yang dikonfigurasi. Biarkan ini nonaktif kecuali model embedding Anda secara eksplisit mendukung embedding lintas modalitas, dan atur `memory.search.fallback` ke "none" selama fitur ini aktif. File yang cocok diunggah ke penyedia embedding jarak jauh yang dikonfigurasi selama pengindeksan.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Aktifkan Pencarian Memori Multimodal`},help:{"v1-1dk5d7o-7e":`Mengaktifkan pengindeksan memori gambar/audio dari extraPaths. Saat ini, fitur ini memerlukan Gemini embedding-2, mempertahankan direktori akar memori default khusus Markdown, menonaktifkan penyedia cadangan pencarian memori, dan mengunggah konten biner yang cocok ke penyedia embedding jarak jauh yang dikonfigurasi.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Batas Maksimum Byte File Pencarian Memori Multimodal`},help:{"v1-1mmdrvk-5d":`Menetapkan jumlah byte maksimum yang diizinkan per file multimodal sebelum file tersebut dilewati selama pengindeksan memori. Gunakan ini untuk membatasi biaya unggah dan latensi pengindeksan, atau naikkan nilainya untuk klip audio pendek berkualitas tinggi.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modalitas Pencarian Memori Multimodal`},help:{"v1-alp4vh-4l":`Memilih jenis file multimodal yang diindeks dari extraPaths: "image", "audio", atau "all". Batasi pilihan ini agar kumpulan data biner berukuran besar tidak terindeks secara tidak sengaja.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Dimensionalitas Keluaran Pencarian Memori`},help:{"v1-1f7zu53-93":`Mengganti ukuran vektor keluaran khusus penyedia untuk embedding memori. Model Gemini mendukung 128-3072 dimensi dan merekomendasikan 768, 1536, atau 3072; keluarga model Bedrock seperti Titan V2, Cohere V4, dan Nova menyediakan ukuran yang diizinkan masing-masing. Perubahan nilai ini akan memerlukan pengindeksan ulang penuh karena dimensi vektor yang tersimpan harus tetap konsisten.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Penyedia Pencarian Memori`},help:{"v1-5evseb-71":`Memilih backend embedding yang digunakan untuk membuat/mengueri vektor memori. Defaultnya adalah "openai"; tetapkan "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama", atau "local" jika Anda ingin menggunakan backend lain.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Hasil Maksimum Pencarian Memori`},help:{"v1-13ekath-4x":`Jumlah maksimum hasil memori yang dikembalikan dari pencarian sebelum pemeringkatan ulang lanjutan dan penyisipan ke dalam prompt. Naikkan untuk cakupan pengambilan yang lebih luas, atau turunkan untuk prompt yang lebih ringkas dan respons yang lebih cepat.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Skor Minimum Pencarian Memori`},help:{"v1-1ww231l-4v":`Ambang skor relevansi minimum untuk menyertakan hasil memori dalam keluaran akhir pengambilan memori. Naikkan untuk mengurangi kecocokan yang lemah/tidak relevan, atau turunkan jika Anda memerlukan pengambilan dengan kriteria yang lebih longgar.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Jenis Input Kueri Pencarian Memori`},help:{"v1-831yrv-4q":"Nilai `input_type` opsional khusus penyedia untuk embedding memori saat kueri. Gunakan ini dengan endpoint embedding asimetris yang kompatibel dengan OpenAI dan memerlukan label kueri."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Ingat Lintas Percakapan`},help:{"v1-k1itm8-7y":`Gunakan konteks yang relevan dari percakapan pribadi lain milik agen ini melalui pengambilan transkrip yang terlindungi. Secara default, hanya aktif jika session.dmScope global tidak ditetapkan atau bernilai "main" dan tidak ada pengikatan yang menimpa cakupan DM; konfigurasi isolasi DM apa pun akan menonaktifkannya secara default. Nilai true atau false yang ditetapkan secara eksplisit selalu diutamakan.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Kunci API Embedding Jarak Jauh`},help:{"v1-nfuuu-62":`Menyediakan kunci API khusus untuk panggilan embedding jarak jauh yang digunakan dalam pengindeksan memori dan embedding saat kueri. Gunakan ini jika embedding memori perlu menggunakan kredensial yang berbeda dari kredensial default global atau variabel lingkungan.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`URL Dasar Embedding Jarak Jauh`},help:{"v1-1ugvqgt-5p":`Mengganti endpoint API embedding, seperti proksi yang kompatibel dengan OpenAI atau URL dasar Gemini kustom. Gunakan ini hanya saat merutekan melalui gateway Anda sendiri atau endpoint vendor; jika tidak, pertahankan pengaturan default penyedia.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Embedding Batch Jarak Jauh Diaktifkan`},help:{"v1-1fehqi-5x":`Mengaktifkan API batch penyedia untuk tugas embedding jika didukung (OpenAI/Gemini), sehingga meningkatkan laju pemrosesan pada pengindeksan berskala lebih besar. Biarkan ini aktif kecuali saat menelusuri kegagalan batch penyedia atau menjalankan beban kerja yang sangat kecil.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Header Embedding Jarak Jauh`},help:{"v1-1uic0kd-5i":`Menambahkan header HTTP kustom ke permintaan embedding jarak jauh, yang digabungkan dengan header default penyedia. Gunakan ini untuk header autentikasi proksi dan perutean tenant, serta batasi nilainya seminimal mungkin agar metadata sensitif tidak bocor.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Sumber Pencarian Memori`},help:{"v1-btxtzg-57":`Memilih sumber yang diindeks: "memory" membaca MEMORY.md + berkas memori, dan "sessions" menyertakan riwayat transkrip. Pertahankan ["memory"] kecuali Anda perlu mengambil informasi dari transkrip percakapan sebelumnya.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Indeks Vektor Pencarian Memori`},help:{"v1-fbybkj-37":`Mengontrol indeks semantik sqlite-vec. Pertahankan pengaturan pengganti lanjutan ini ketika kebijakan vektor tingkat akar dan per agen berbeda.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Jalur Ekstensi Vektor Pencarian Memori`},help:{"v1-1hysv5q-58":"Mengganti jalur pustaka ekstensi sqlite-vec yang ditemukan secara otomatis (`.dylib`, `.so`, atau `.dll`). Gunakan ini ketika lingkungan runtime Anda tidak dapat menemukan sqlite-vec secara otomatis atau Anda menetapkan build tertentu yang telah terbukti berfungsi."}},messages:{label:{"v1-1wwzqad-8":`Pesan`},help:{"v1-i5k0iw-5k":`Infrastruktur pesan dan pengaturan default lintas agen. Elemen sejajar di tingkat akar mengatur infrastruktur dan pengaturan default lintas agen; agents.defaults mengatur perilaku loop agen; entri agen dapat mengganti keduanya jika didukung.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji Reaksi Konfirmasi`},help:{"v1-1iip0zs-1x":`Reaksi emoji yang digunakan untuk mengonfirmasi penerimaan pesan masuk (kosongkan untuk menonaktifkan).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Cakupan Reaksi Konfirmasi`},help:{"v1-1jvdg5n-7s":`Kapan reaksi konfirmasi dikirim ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" mengonfirmasi pesan grup yang menyebut agen, baik grup tersebut mewajibkan penyebutan maupun tidak; "group-all" mengonfirmasi setiap pesan grup. "off"/"none" menonaktifkan reaksi konfirmasi sepenuhnya.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Aturan Obrolan Grup`},help:{"v1-chqsvh-4l":`Kontrol penanganan pesan grup, termasuk pemicu penyebutan dan pengaturan ukuran jendela riwayat. Batasi pola penyebutan agar saluran grup tidak terpicu oleh setiap pesan.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Batas Riwayat Grup`},help:{"v1-1mkbpw-9k":`Jumlah maksimum pesan grup sebelumnya yang dimuat sebagai konteks per giliran untuk sesi grup. Gunakan nilai yang lebih tinggi untuk kesinambungan konteks yang lebih kaya, atau nilai yang lebih rendah untuk respons yang lebih cepat dan hemat biaya. Riwayat prompt otomatis dibatasi hingga 200 pesan. Nilai maksimum bilangan bulat JSON memilih jendela konteks default kanal (50 untuk riwayat grup bersama), bukan jendela konteks tanpa batas.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Pola Penyebutan Grup`},help:{"v1-i7h7qc-6f":`Pola regex aman yang tidak membedakan huruf besar dan kecil untuk mendeteksi penyebutan eksplisit/frasa pemicu dalam obrolan grup. Gunakan pola yang spesifik untuk mengurangi deteksi keliru di kanal bervolume tinggi; pola dengan pengulangan bersarang yang tidak valid atau tidak aman akan diabaikan.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Pesan Masuk Grup Tanpa Penyebutan`},help:{"v1-17wef8h-5f":`Mengontrol cara obrolan grup tanpa penyebutan dikirimkan dalam mode selalu aktif. "user_request" memperlakukannya sebagai permintaan pengguna; "room_event" mengirimkannya sebagai konteks senyap yang memerlukan alat pesan untuk menghasilkan keluaran yang terlihat.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Balasan Grup yang Terlihat`},help:{"v1-qa4z1s-aa":`Mengesampingkan balasan sumber yang ditulis model untuk percakapan grup/kanal. Nilai defaultnya adalah "automatic" jika tidak ada kebijakan global untuk balasan yang terlihat. "message_tool" mewajibkan message(action=send) untuk keluaran asisten normal dan media alat umum; keluaran runtime yang secara eksplisit dimiliki host tetap dapat dikirimkan, kecuali untuk peristiwa latar ruangan. "automatic" mengirim balasan normal seperti sebelumnya.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Debounce Pesan Masuk`},help:{"v1-ebyu5x-4a":`Pengaturan debounce pesan masuk langsung yang digunakan sebelum pemrosesan antrean/giliran dimulai. Konfigurasikan ini untuk rentetan pesan cepat dari pengirim yang sama pada penyedia tertentu.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Debounce Pesan Masuk per Kanal (ms)`},help:{"v1-wbz54j-4g":`Pengaturan pengganti jeda penggabungan pesan masuk per kanal dalam milidetik, dengan ID penyedia sebagai kunci. Gunakan ini jika beberapa penyedia mengirim potongan pesan lebih sering daripada yang lain.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Jeda Penggabungan Pesan Masuk (ms)`},help:{"v1-1616yo2-7w":`Jeda tanpa pesan (ms) untuk mengelompokkan pesan masuk yang dikirim beruntun oleh pengirim yang sama. Telegram menggunakan nilai bawaan 300ms jika tidak ada pengaturan pengganti global maupun per kanal; kanal lain menggunakan nilai bawaan 0. Nilai nol menonaktifkan pengelompokan pesan beruntun biasa, tetapi Telegram tetap menyatukan kembali potongan pesan panjang yang mendekati batas.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Antrean Pesan Masuk`},help:{"v1-hm2o31-48":`Strategi antrean untuk pesan masuk yang tiba saat sesi sedang berjalan. Gunakan ini untuk menyesuaikan pengarahan, tindak lanjut tertunda, penggabungan pesan, atau interupsi.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Mode Antrean per Kanal`},help:{"v1-4rf8z8-54":`Pengaturan pengganti mode antrean per kanal dengan ID penyedia sebagai kunci (misalnya telegram, discord, slack). Gunakan ini jika pola lalu lintas suatu kanal memerlukan perilaku yang berbeda dari pengaturan default global.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Kapasitas Antrean`},help:{"v1-16ql8c7-4j":`Jumlah maksimum item masuk dalam antrean yang disimpan sebelum kebijakan pembuangan diterapkan. Nilai default adalah 20; batasi kapasitas di kanal yang ramai agar penggunaan memori tetap dapat diprediksi.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Jeda Penggabungan Cadangan Antrean per Kanal (ms)`},help:{"v1-4tpyt7-4e":`Pengaturan pengganti jeda penggabungan per kanal untuk perilaku antrean, dengan ID penyedia sebagai kunci. Gunakan ini untuk menyesuaikan penanganan lonjakan pesan secara terpisah pada antarmuka obrolan dengan ritme yang berbeda.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Strategi Pembuangan Antrean`},help:{"v1-ydb2rw-6m":`Strategi penghapusan saat batas antrean terlampaui. "summarize" menghapus entri terlama tetapi mempertahankan ringkasan singkat; "old" menghapus entri terlama tanpa ringkasan; "new" menolak item terbaru. Gunakan "summarize" untuk percakapan jangka panjang yang memerlukan konteks.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Mode Antrean`},help:{"v1-19k7gy1-67":`Mode antrean untuk proses yang sedang berjalan. Gunakan "steer" untuk menyisipkan prompt ke dalam proses yang sedang berjalan, "followup" untuk menjalankannya nanti, "collect" untuk mengelompokkan pesan yang kompatibel agar diproses nanti, atau "interrupt" untuk membatalkan proses yang sedang berjalan sebelum memulai prompt terbaru.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Awalan Respons Keluar`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Mode Default Catatan Penggunaan di Bagian Bawah`},help:{"v1-l3shsx-dv":`Mode default catatan penggunaan di bagian bawah setiap balasan ("off"|"tokens"|"full") yang diterapkan pada sesi yang belum memilih mode melalui /usage. Juga menerima "on" sebagai alias lama untuk "tokens". Menerima mode saja atau pemetaan per kanal dengan "default" sebagai cadangan. Urutan prioritas: nilai sesi -> entri kanal -> default -> off; pilihan /usage yang eksplisit (termasuk off) disimpan dan mengesampingkan nilai default. Gunakan /usage reset (alias: inherit, clear, default) untuk menghapus pengaturan khusus sesi dan kembali mewarisi nilai default yang dikonfigurasi ini.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Reaksi Status`},help:{"v1-193764l-3s":`Reaksi status siklus proses yang memperbarui emoji pada pesan pemicu seiring kemajuan agen (dalam antrean → berpikir → alat → selesai/kesalahan).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Aktifkan Reaksi Status`},help:{"v1-1qnmmnc-7x":`Aktifkan reaksi status siklus hidup di kanal yang didukung. Discord menganggap pengaturan yang belum ditetapkan sebagai aktif saat reaksi konfirmasi aktif; Slack, Signal, Telegram, dan WhatsApp mengharuskan pengaturan ini bernilai true sebelum reaksi siklus hidup digunakan. Secara default, Slack menggunakan status utas asisten bawaan untuk menampilkan progres.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Templat Footer Penggunaan`},help:{"v1-1xibc23-47":`Templat footer kustom untuk /usage full, berupa objek inline atau jalur file JSON. Jika templat tidak valid atau tidak tersedia, baris penggunaan bawaan akan digunakan.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Balasan yang Terlihat`},help:{"v1-7yfwc2-8t":`Mengontrol balasan sumber yang ditulis model dalam percakapan langsung, grup, dan kanal. "message_tool" mewajibkan message(action=send) untuk keluaran asisten normal dan media alat umum; keluaran runtime yang secara eksplisit dimiliki host tetap dapat dikirim, kecuali untuk peristiwa latar di ruang percakapan. "automatic" mengirim balasan normal seperti sebelumnya.`}},meta:{label:{"v1-1xpfxac-m":`Metadata Kompatibilitas`},help:{"v1-1owqhgn-2w":`Metadata kompatibilitas yang tetap dapat dibaca versi lama dipertahankan agar biner versi lama dapat menolak penurunan versi konfigurasi yang tidak aman.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Versi Terakhir yang Mengubah Konfigurasi`},help:{"v1-qykpv1-1i":`Versi OpenClaw yang terakhir menulis konfigurasi ini.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Penanda Migrasi Konfigurasi`},help:{"v1-burt8q-1q":`Penanda kompatibilitas berbatas untuk migrasi konfigurasi yang telah selesai.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migrasi Daftar Izin Kebijakan Model`},help:{"v1-5psop1-1z":`Mencatat bahwa pembatasan pemetaan model lama telah dipertahankan atau dievaluasi.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migrasi Pemisahan Model Utilitas`},help:{"v1-vzdfqx-2t":`Mencatat bahwa model utama implisit lama telah dipertahankan sebelum pemilihan model utilitas dipisahkan.`}},models:{label:{"v1-hzmwb-6":`Model`},help:{"v1-1h1niol-5q":`Akar katalog model untuk definisi penyedia, perilaku penggabungan/penggantian, dan integrasi penemuan Bedrock opsional. Pastikan definisi penyedia eksplisit dan tervalidasi sebelum mengandalkan jalur failover produksi.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Pembaruan Katalog Model`},help:{"v1-1hess4t-40":`Mengontrol pembaruan latar belakang pada katalog model bawaan. Entri jarak jauh dapat memperbarui metadata model, tetapi tidak dapat mengubah endpoint atau header penyedia.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Pembaruan Katalog Model Diaktifkan`},help:{"v1-1fogpjj-3j":`Mengambil pembaruan katalog model yang dihosting di latar belakang (default: true). Atur ke false untuk menonaktifkan semua lalu lintas katalog model jarak jauh.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL Pembaruan Katalog Model`},help:{"v1-e02ai2-44":`Ganti URL katalog model yang dihosting dengan URL mirror HTTPS yang dihosting sendiri (HTTP localhost diizinkan untuk pengujian). Perubahan berlaku setelah Gateway dimulai ulang.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Mode Katalog Model`},help:{"v1-1ofrnsp-es":`Mengontrol perilaku katalog penyedia: "merge" mempertahankan penyedia bawaan dan menerapkan penyedia kustom Anda di atasnya, sedangkan "replace" hanya menggunakan penyedia yang Anda konfigurasikan. Dalam "merge", ID penyedia yang cocok mempertahankan nilai baseUrl yang tidak kosong dalam models.json agen, sedangkan nilai apiKey hanya dipertahankan jika penyedia tidak dikelola oleh SecretRef dalam konteks konfigurasi/profil autentikasi saat ini; penyedia yang dikelola oleh SecretRef memperbarui apiKey dari penanda sumber saat ini, dan contextWindow/maxTokens model yang cocok menggunakan nilai yang lebih tinggi antara entri eksplisit dan implisit.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Penyedia Model`},help:{"v1-1y5jg0v-8p":`Peta penyedia dengan ID penyedia sebagai kunci, berisi pengaturan koneksi/autentikasi dan definisi model konkret. Penyedia bawaan dapat disesuaikan dengan pengaturan tambahan di tingkat penyedia; penyedia kustom harus menyertakan baseUrl dan models. Gunakan kunci penyedia yang stabil agar referensi dari agen dan alat tetap portabel di berbagai lingkungan.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Runtime Penyedia Model`},help:{"v1-1luy4fb-5o":`Kebijakan runtime agen tingkat rendah opsional untuk penyedia ini. Gunakan kebijakan runtime penyedia/model alih-alih menetapkan runtime untuk seluruh agen; jika tidak ditentukan atau menggunakan nilai default, OpenClaw akan memilih runtime untuk penyedia yang dipilih.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`ID Runtime Penyedia Model`},help:{"v1-1gusd9s-69":`ID runtime agen penyedia: "openclaw", "auto", ID harness plugin terdaftar seperti "codex", atau alias backend CLI yang didukung seperti "claude-cli". OpenAI pada endpoint resmi menggunakan harness Codex secara default jika tidak ditentukan.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Adaptor API Penyedia Model`},help:{"v1-16c28rb-57":`Pilihan adaptor API penyedia yang mengontrol penanganan kompatibilitas permintaan/respons untuk pemanggilan model. Gunakan adaptor yang sesuai dengan protokol penyedia hulu Anda untuk menghindari ketidakcocokan fitur.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Kunci API Penyedia Model`},help:{"v1-1p84k96-54":`Kredensial penyedia yang digunakan untuk autentikasi berbasis kunci API saat penyedia memerlukan autentikasi kunci langsung. Gunakan substitusi rahasia/variabel lingkungan dan hindari menyimpan kunci asli dalam file konfigurasi yang di-commit.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Mode Autentikasi Penyedia Model`},help:{"v1-1l1lwxr-5p":`Memilih jenis autentikasi penyedia: "api-key" untuk autentikasi kunci API, "token" untuk autentikasi token bearer, "oauth" untuk kredensial OAuth, dan "aws-sdk" untuk resolusi kredensial AWS. Sesuaikan dengan persyaratan penyedia Anda.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Header Authorization Penyedia Model`},help:{"v1-1gn3lt3-59":`Jika true, kredensial dikirim melalui header HTTP Authorization meskipun autentikasi alternatif tersedia. Gunakan ini hanya jika penyedia atau proxy Anda secara eksplisit mewajibkan penerusan Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`URL Dasar Penyedia Model`},help:{"v1-1ku88v8-53":`URL dasar untuk endpoint penyedia yang digunakan untuk melayani permintaan model bagi entri penyedia tersebut. Gunakan endpoint HTTPS dan sesuaikan URL untuk setiap lingkungan melalui templat konfigurasi jika diperlukan.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Header Penyedia Model`},help:{"v1-chg59u-4x":`Header HTTP statis yang digabungkan ke dalam permintaan penyedia untuk perutean tenant, autentikasi proxy, atau persyaratan gateway khusus. Gunakan seperlunya dan simpan nilai header yang sensitif sebagai rahasia.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Injeksi num_ctx Penyedia Model (Kompatibel dengan OpenAI)`},help:{"v1-53rmcr-6n":"Mengontrol apakah OpenClaw menyisipkan `options.num_ctx` untuk penyedia Ollama yang dikonfigurasi dengan adaptor yang kompatibel dengan OpenAI (`openai-completions`). Nilai default adalah true. Atur ke false hanya jika proxy/upstream Anda menolak kolom payload `options` yang tidak dikenal."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Layanan Lokal Penyedia Model`},help:{"v1-19zkcow-4y":`Proses server model lokal opsional yang dijalankan sesuai kebutuhan untuk penyedia ini. OpenClaw memeriksa healthUrl, menjalankan perintah saat diperlukan, menunggu hingga siap, lalu mengirim permintaan model.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Argumen Layanan Lokal Penyedia Model`},help:{"v1-t12wib-27":`Daftar argumen yang diteruskan ke perintah server model lokal tanpa ekspansi shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Perintah Layanan Lokal Penyedia Model`},help:{"v1-1x6hz64-4j":`Jalur absolut berkas yang dapat dieksekusi untuk proses server model lokal. Tentukan jalur ini secara eksplisit agar proses memulai penyedia bersifat deterministik dan tidak bergantung pada pencarian PATH oleh shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Direktori Kerja Layanan Lokal Penyedia Model`},help:{"v1-fi3xlx-1h":`Direktori kerja untuk proses server model lokal.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Lingkungan Layanan Lokal Penyedia Model`},help:{"v1-1lwb9k1-3k":`Variabel lingkungan tambahan untuk proses server model lokal. Nilai yang tampak rahasia disamarkan dalam snapshot konfigurasi.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL Pemeriksaan Kesehatan Layanan Lokal Penyedia Model`},help:{"v1-jv7aw-35":`URL kesiapan yang diperiksa sebelum permintaan model. Jika tidak ditentukan, OpenClaw menggunakan baseUrl penyedia dengan tambahan /models.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Penghentian Layanan Lokal Penyedia Model Saat Tidak Aktif`},help:{"v1-1efg054-3z":`Durasi dalam milidetik untuk menjaga server model lokal yang dimulai oleh OpenClaw tetap aktif setelah permintaan terakhir selesai. Atur ke 0 agar tetap aktif hingga OpenClaw ditutup.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Batas Waktu Kesiapan Layanan Lokal Penyedia Model`},help:{"v1-4gp0f0-2r":`Waktu tunggu maksimum dalam milidetik untuk pemeriksaan kesiapan server model lokal setelah proses dimulai.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Token Maksimum Penyedia Model`},help:{"v1-fnj50y-38":`Batas maksimum token keluaran default yang diterapkan pada model di bawah penyedia ini ketika entri model tidak menetapkan maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Daftar Model Penyedia Model`},help:{"v1-1vbm0gt-63":`Daftar model yang dideklarasikan untuk penyedia, termasuk pengenal, metadata, parameter khusus penyedia, serta petunjuk kompatibilitas/biaya opsional. Pastikan ID sama persis dengan nilai dalam katalog penyedia agar pemilihan dan penggunaan model cadangan berjalan dengan benar.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Runtime Model`},help:{"v1-1k70g2n-3g":`Kebijakan runtime agen tingkat rendah opsional untuk model ini. Kebijakan runtime model mengesampingkan kebijakan runtime penyedia.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`ID Runtime Model`},help:{"v1-1llzv33-42":`ID runtime agen model: "openclaw", "auto", ID harness plugin terdaftar seperti "codex", atau alias backend CLI yang didukung seperti "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Masukan Media Model`},help:{"v1-wxtj8e-2x":`Metadata opsional tentang kemampuan media model yang digunakan oleh alat untuk memilih pengaturan kompresi gambar bawaan yang konservatif.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Masukan Gambar Model`},help:{"v1-1nviirq-3c":`Batas masukan gambar opsional untuk model ini, seperti panjang sisi maksimum, jumlah piksel maksimum, dan panjang sisi yang diutamakan untuk kompresi.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Byte Maksimum Gambar Model`},help:{"v1-c2469j-23":`Ukuran maksimum muatan gambar terenkode yang diterima oleh penyedia untuk model ini.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Piksel Maksimum Gambar Model`},help:{"v1-9d6yqp-1u":`Jumlah piksel gambar maksimum yang diterima oleh penyedia untuk model ini.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Sisi Maksimum Gambar Model`},help:{"v1-1gbci08-1y":`Lebar atau tinggi gambar maksimum yang diterima oleh penyedia untuk model ini.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Sisi Pilihan Gambar Model`},help:{"v1-1u1mpcg-2x":`Panjang sisi yang diutamakan saat mengubah ukuran gambar untuk kompresi yang seimbang. Biarkan tidak diatur untuk menggunakan nilai bawaan OpenClaw yang konservatif.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Mode Token Gambar Model`},help:{"v1-1oy6z7v-1z":`Metode penghitungan token gambar penyedia: "tile", "detail", atau "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Parameter Runtime Penyedia Model`},help:{"v1-464sgu-4t":`Parameter runtime khusus penyedia yang ditafsirkan oleh plugin penyedia. Gunakan kunci yang didokumentasikan oleh penyedia, dan utamakan dokumentasi eksplisit penyedia daripada asumsi umum yang dibuat secara ad hoc.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Wilayah Penyedia Model`},help:{"v1-yq7rxk-5h":`Wilayah deployment/API penyedia opsional yang ditafsirkan oleh penyedia yang menyediakan endpoint regional. Lihat dokumentasi penyedia untuk nilai yang didukung; penggantian baseUrl biasanya diutamakan jika keduanya diatur.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Penggantian Pengaturan Permintaan Penyedia Model`},help:{"v1-1lkxryk-87":`Penggantian pengaturan opsional untuk permintaan ke penyedia model, termasuk header tambahan, penggantian autentikasi, perutean proksi, pengaturan klien TLS, dan allowPrivateNetwork opsional untuk endpoint tepercaya yang dihosting sendiri. Gunakan hanya jika jalur jaringan upstream atau perusahaan Anda memerlukan penyesuaian transportasi.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Izinkan Jaringan Privat untuk Permintaan Penyedia Model`},help:{"v1-1nbtcjk-fo":`Jika true, izinkan permintaan HTTP penyedia model ke rentang privat, CGNAT, atau rentang serupa melalui pengaman pengambilan HTTP penyedia (fetchWithSsrFGuard). URL dasar penyedia kustom/lokal sudah memercayai origin persis seperti yang dikonfigurasi, kecuali origin metadata, link-local, dan NAT64 penggunaan lokal (64:ff9b:1::/48); tetapkan ke false untuk menonaktifkan kepercayaan tersebut. OpenAI Responses WebSocket menggunakan kembali request untuk header/TLS, tetapi tidak menggunakan jalur pengambilan SSRF tersebut. Gunakan true hanya untuk endpoint yang dihosting sendiri dan dikendalikan operator yang harus menjangkau origin privat di luar origin baseUrl yang dikonfigurasi.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Penggantian Autentikasi Permintaan Penyedia Model`},help:{"v1-ucdgnf-1w":`Ganti perilaku autentikasi permintaan untuk penyedia ini.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Nama Header Autentikasi Permintaan Penyedia Model`},help:{"v1-1881nqr-1i":`Nama header autentikasi kustom yang digunakan saat mode autentikasi adalah header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Mode Autentikasi Permintaan Penyedia Model`},help:{"v1-1lhv8hs-24":`Mode penggantian autentikasi: "provider-default", "authorization-bearer", atau "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Prefiks Header Autentikasi Permintaan Penyedia Model`},help:{"v1-1rbm9lz-21":`Prefiks opsional yang ditambahkan di depan request.auth.value saat mode autentikasi adalah header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Token Bearer Permintaan Penyedia Model`},help:{"v1-6rcasw-1l":`Token Bearer yang digunakan saat mode autentikasi adalah authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Nilai Header Autentikasi Permintaan Penyedia Model`},help:{"v1-1v69ej-1j":`Nilai header autentikasi kustom yang digunakan saat mode autentikasi adalah header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Header Permintaan Penyedia Model`},help:{"v1-zj3orj-2i":`Header tambahan yang digabungkan ke dalam permintaan penyedia setelah atribusi default dan resolusi autentikasi.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proksi Permintaan Penyedia Model`},help:{"v1-md5uj8-4j":`Penggantian proksi opsional untuk permintaan penyedia model. Gunakan "env-proxy" untuk mengikuti pengaturan proksi lingkungan atau "explicit-proxy" untuk merutekan melalui URL proksi tertentu.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Mode Proksi Permintaan Penyedia Model`},help:{"v1-1dx0ozg-29":`Mode penggantian proksi untuk permintaan penyedia model: "env-proxy" atau "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS Proksi Permintaan Penyedia Model`},help:{"v1-rdx62w-1v":`Pengaturan TLS opsional yang digunakan saat menghubungkan ke proksi yang dikonfigurasi.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`CA TLS Proksi Permintaan Penyedia Model`},help:{"v1-11pg2fd-1s":`Bundel CA kustom yang digunakan untuk memverifikasi rantai sertifikat TLS proksi.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Sertifikat TLS Proksi Permintaan Penyedia Model`},help:{"v1-x8nk2q-22":`Sertifikat TLS klien yang disajikan ke proksi saat TLS mutual diperlukan.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Lewati Verifikasi TLS Proksi Permintaan Penyedia Model`},help:{"v1-12vjdm9-2j":`Melewati verifikasi sertifikat TLS proksi. Gunakan hanya untuk lingkungan pengembangan yang terkontrol.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Kunci TLS Proksi Permintaan Penyedia Model`},help:{"v1-1skyr56-1w":`Kunci privat yang dipasangkan dengan request.proxy.tls.cert untuk TLS mutual proksi.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Frasa Sandi TLS Proksi Permintaan Penyedia Model`},help:{"v1-wjvoxd-1m":`Frasa sandi opsional yang digunakan untuk mendekripsi request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Nama Server TLS Proksi Permintaan Penyedia Model`},help:{"v1-b4oabu-22":`Penggantian SNI/nama server opsional yang digunakan saat membangun koneksi TLS ke proksi.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`URL Proksi Permintaan Penyedia Model`},help:{"v1-kvbgou-48":`URL proksi eksplisit yang digunakan saat request.proxy.mode bernilai explicit-proxy. Kredensial yang disematkan dalam URL dianggap sensitif dan disamarkan dalam snapshot.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS Permintaan Penyedia Model`},help:{"v1-16u7v7h-2b":`Pengaturan TLS opsional yang digunakan saat terhubung langsung ke endpoint model hulu.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`CA TLS Permintaan Penyedia Model`},help:{"v1-ny8y3e-1v":`Bundel CA khusus yang digunakan untuk memverifikasi rantai sertifikat TLS hulu.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Sertifikat TLS Permintaan Penyedia Model`},help:{"v1-1lltmhw-2e":`Sertifikat TLS klien yang diberikan ke endpoint hulu saat TLS timbal balik diperlukan.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Lewati Verifikasi TLS Permintaan Penyedia Model`},help:{"v1-1006cuy-2m":`Melewati verifikasi sertifikat TLS hulu. Gunakan hanya untuk lingkungan pengembangan yang terkendali.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Kunci TLS Permintaan Penyedia Model`},help:{"v1-w2agir-1t":`Kunci privat yang dipasangkan dengan request.tls.cert untuk TLS timbal balik hulu.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Frasa Sandi TLS Permintaan Penyedia Model`},help:{"v1-10ds42f-1g":`Frasa sandi opsional yang digunakan untuk mendekripsi request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Nama Server TLS Permintaan Penyedia Model`},help:{"v1-18yt7x9-1y":`Penggantian SNI/nama server opsional yang digunakan saat membangun koneksi TLS hulu.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Batas Waktu Permintaan Penyedia Model`},help:{"v1-t3yn8l-ih":`Batas waktu opsional untuk permintaan model per penyedia, dalam detik. Pengaturan permintaan tingkat penyedia memengaruhi baris model eksplisit milik penyedia; pengaturan ini tidak membuat model implisit. Untuk penyedia kustom, atur bersama baseUrl dan models penyedia. Berlaku untuk pengambilan data HTTP penyedia, termasuk koneksi, header, isi, dan penanganan pembatalan keseluruhan permintaan, serta menaikkan batas pengawas waktu diam/streaming LLM untuk penyedia ini di atas nilai default implisit sekitar 120 detik. Gunakan ini untuk server model lokal atau yang dihosting sendiri yang lambat, atau untuk penyedia cloud yang menampung token penalaran tanpa mengirimkan data melalui jaringan (Gemini preview, Claude/Opus dengan payload alat besar), alih-alih mengubah batas waktu agen global.`}},nodeHost:{label:{"v1-nb8lk1-9":`Host Node`},help:{"v1-8recuz-4z":`Kontrol host node untuk fitur yang disediakan dari node Gateway ini ke node atau klien lain. Pertahankan nilai default kecuali Anda memang ingin meneruskan kapabilitas lokal melalui proksi di jaringan node Anda.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Eksekusi Agen Node`},help:{"v1-4uz5ur-2k":`Aktifkan giliran agen native yang memerlukan persetujuan pada host node tanpa antarmuka ini. Dinonaktifkan secara default.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Eksekusi Agen Claude Node`},help:{"v1-g8az5y-2l":`Mengontrol apakah host node tanpa antarmuka ini boleh mengumumkan ketersediaan giliran agen Claude CLI ke Gateway.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Eksekusi Agen Claude Node Diaktifkan`},help:{"v1-1ke804l-44":`Umumkan ketersediaan kelanjutan sesi Claude pada node yang dipasangkan saat biner claude lokal tersedia (default: false). Eksekusi tetap memerlukan persetujuan eksekusi node.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Pembaruan Otomatis Node`},help:{"v1-16xjk4e-5n":`Mengontrol pembaruan otomatis runtime terpisah untuk host node headless yang dikemas. Memeriksa setiap jam dan menunggu semua pekerjaan node selesai sebelum memulai ulang; jeda antar mulai ulang otomatis minimal 12 jam.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Pembaruan Otomatis Node Diaktifkan`},help:{"v1-1sa0yeg-7w":`Aktifkan pembaruan otomatis stable atau beta untuk node headless yang dikemas dan berjalan dalam jangka panjang (default: true). Atur ke false untuk menonaktifkannya. Juga dinonaktifkan oleh update.checkOnStart=false atau OPENCLAW_NO_AUTO_UPDATE=1; checkout kode sumber, aplikasi native, worker privat, dev, dan extended-stable tidak menerapkan pembaruan secara otomatis.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Proksi Browser Node`},help:{"v1-2xrew7-4f":`Mengelompokkan pengaturan proksi browser untuk menyediakan kontrol browser lokal melalui perutean node. Aktifkan hanya jika alur kerja node jarak jauh memerlukan profil browser lokal Anda.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Profil yang Diizinkan pada Proksi Browser Node`},help:{"v1-1ew5dkm-8b":`Daftar opsional nama profil browser yang diizinkan untuk diakses melalui perutean proksi node. Biarkan kosong untuk mempertahankan akses penuh bawaan ke profil, termasuk rute pembuatan/penghapusan profil. Jika diatur, OpenClaw menerapkan akses profil dengan hak akses minimum dan memblokir pembuatan/penghapusan profil persisten melalui proksi.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Proksi Browser Node Diaktifkan`},help:{"v1-pa04pd-5b":`Menyediakan server kontrol browser lokal melalui perutean proksi node agar klien jarak jauh dapat menggunakan kemampuan browser host ini. Biarkan nonaktif kecuali otomatisasi jarak jauh secara eksplisit bergantung padanya.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP Host Node`},help:{"v1-1mdhrwl-48":`Gunakan server MCP yang dijalankan oleh host node tanpa antarmuka grafis dan dipublikasikan ke Gateway pasangannya sebagai alat agen. Mulai ulang host node setelah mengubah bagian ini.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Server MCP Host Node`},help:{"v1-19m002f-3x":`Definisi server MCP bernama yang bersifat lokal untuk node ini. Menggunakan struktur server yang sama dengan mcp.servers; server OAuth tidak didukung oleh host node.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills Host Node`},help:{"v1-v8txza-41":`Gunakan bagian ini untuk mempublikasikan keterampilan yang terpasang di ~/.openclaw/skills dari host node tanpa antarmuka grafis. Mulai ulang host node setelah mengubah file keterampilan.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Skills Host Node Diaktifkan`},help:{"v1-1ggpkqb-36":`Pindai dan publikasikan keterampilan yang dihosting di node setelah terhubung (default: true). Atur ke false untuk menonaktifkan publikasi keterampilan node.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Eksekusi Worker Node`},help:{"v1-1w83rox-2p":`Aktifkan hosting sesi worker OpenClaw penuh dari bundel yang dikelola Gateway. Dinonaktifkan secara default.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Kapasitas Eksekusi Worker Node`},help:{"v1-10nvk8f-3w":`Jumlah maksimum sesi worker serentak yang dihosting oleh node ini (default: jumlah inti CPU yang tersedia). Harus berupa bilangan bulat dari 1 hingga 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Image Kontainer Eksekusi Worker Node`},help:{"v1-1oqx50o-5t":`Image Node 24.16+ atau 26.1+ opsional untuk worker yang diisolasi dalam kontainer (default: "node:24.19.0-slim"). Gunakan image yang dikunci dengan digest, berasal dari registri privat, atau telah dimuat sebelumnya jika diperlukan; image yang belum tersedia akan diunduh saat pertama kali digunakan.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Eksekusi Worker Node Diaktifkan`},help:{"v1-b3t0xp-2t":`Izinkan node yang telah dipasangkan ini menghosting sesi dari bundel yang persis sama dengan yang diinstal oleh Gateway-nya (default: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Isolasi Eksekusi Worker Node`},help:{"v1-19i6swo-58":`Pilih batas proses sesi worker: "none" berjalan langsung pada host node (default); "container" memerlukan mesin yang kompatibel dengan Docker dan berfungsi, serta tidak pernah beralih ke eksekusi pada host sebagai cadangan.`}},plugins:{label:{"v1-10renyj-7":`Plugin`},help:{"v1-1qbev2k-5c":`Kontrol sistem plugin untuk mengaktifkan ekstensi, membatasi cakupan pemuatan, mengonfigurasi entri, dan melacak instalasi. Pastikan kebijakan plugin ditetapkan secara eksplisit dan menerapkan prinsip hak akses minimum di lingkungan produksi.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Daftar Plugin yang Diizinkan`},help:{"v1-pupwbe-7z":`Daftar opsional ID plugin yang diizinkan; jika ditetapkan, hanya plugin yang tercantum yang dapat dimuat. Saluran obrolan bawaan yang dikonfigurasi tetap dapat mengaktifkan plugin bawaannya saat saluran tersebut diaktifkan secara eksplisit dalam konfigurasi. Gunakan ini untuk memastikan hanya ekstensi yang disetujui yang digunakan di lingkungan terkontrol.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Daftar Plugin yang Diblokir`},help:{"v1-4gyt4z-4i":`Daftar opsional ID plugin yang diblokir meskipun tercakup dalam daftar yang diizinkan atau jalur. Gunakan aturan pemblokiran untuk pemulihan darurat ke kondisi sebelumnya dan pemblokiran mutlak terhadap plugin berisiko.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Aktifkan Plugin`},help:{"v1-pnygd7-50":`Aktifkan atau nonaktifkan pemuatan plugin/ekstensi secara global saat aplikasi dimulai dan konfigurasi dimuat ulang (default: true). Biarkan aktif hanya jika kemampuan ekstensi diperlukan oleh penerapan Anda.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Entri Plugin`},help:{"v1-cn74rf-54":`Pengaturan per plugin dengan ID plugin sebagai kunci, termasuk status pengaktifan dan data konfigurasi runtime khusus plugin. Gunakan ini untuk menyesuaikan plugin tertentu tanpa mengubah kebijakan pemuat global.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Kunci API Plugin`},help:{"v1-ctytg2-53":`Kolom kunci API opsional yang digunakan oleh plugin yang menerima konfigurasi kunci langsung dalam pengaturan entri. Gunakan substitusi rahasia/variabel lingkungan dan hindari menyimpan kredensial asli ke dalam berkas konfigurasi.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Konfigurasi Plugin`},help:{"v1-1he672p-51":`Data konfigurasi yang ditentukan oleh plugin dan ditafsirkan berdasarkan skema serta aturan validasi plugin itu sendiri. Gunakan hanya kolom yang didokumentasikan oleh plugin untuk mencegah pengaturan yang diabaikan atau tidak valid.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Plugin Diaktifkan`},help:{"v1-12soc0h-9a":`Pengaturan pengaktifan per plugin untuk entri tertentu yang mengesampingkan kebijakan plugin global. Dengan mode pemuatan ulang hibrida bawaan, perubahan memuat ulang runtime plugin secara langsung untuk giliran agen baru tanpa memulai ulang Gateway, kecuali plugin memerlukan mulai ulang untuk jalur ini. Gunakan pengaturan ini untuk menerapkan plugin secara bertahap di berbagai lingkungan.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Variabel Lingkungan Plugin`},help:{"v1-p39pu4-52":`Peta variabel lingkungan per plugin yang disuntikkan hanya ke konteks runtime plugin tersebut. Gunakan pengaturan ini untuk membatasi kredensial penyedia ke satu plugin, alih-alih berbagi lingkungan proses global.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Kebijakan Hook Plugin`},help:{"v1-1oslnrf-4c":`Kontrol kebijakan hook bertipe per plugin untuk pemeriksaan keamanan yang diberlakukan oleh sistem inti. Gunakan pengaturan ini untuk membatasi kategori hook berdampak tinggi tanpa menonaktifkan seluruh plugin.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Izinkan Hook Akses Percakapan`},help:{"v1-xqz31z-7e":"Mengontrol apakah plugin ini boleh membaca konten percakapan mentah dari hook bertipe seperti `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize`, dan `agent_end`. Plugin yang tidak disertakan dalam paket harus mengaktifkan akses ini secara eksplisit."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Izinkan Hook Injeksi Prompt`},help:{"v1-7y6cny-32":"Mengontrol apakah plugin ini boleh mengubah prompt melalui hook bertipe. Tetapkan ke false untuk memblokir `before_prompt_build`."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Batas Waktu Hook Plugin (ms)`},help:{"v1-4ra6b7-74":`Batas waktu default dalam milidetik untuk hook bertipe milik plugin ini, dengan batas maksimum 600000. Jika tidak ditetapkan, setiap hook menggunakan batas waktu yang dideklarasikan plugin atau kebijakan per hook dari Gateway; tidak ada satu nilai default tetap. Nilai per hook dalam hooks.timeouts diutamakan.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Pengaturan Pengganti Batas Waktu Hook Plugin`},help:{"v1-yphl9b-5s":`Pengaturan pengganti batas waktu per hook dalam milidetik dengan nama hook bertipe sebagai kunci, dengan batas maksimum 600000. Gunakan pengaturan pengganti khusus untuk hook yang diketahui lambat seperti before_prompt_build atau agent_end alih-alih menaikkan batas waktu semua hook.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Kebijakan LLM Plugin`},help:{"v1-dlca6c-4j":`Kontrol api.runtime.llm.complete per plugin untuk kepercayaan terhadap penggantian model dan agen. Biarkan tidak diatur kecuali plugin harus secara eksplisit mengarahkan panggilan penyelesaian yang dikelola host.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Izinkan Penggantian Agen LLM oleh Plugin`},help:{"v1-k8c08b-4n":`Secara eksplisit mengizinkan plugin ini meminta api.runtime.llm.complete dengan ID agen non-default. Biarkan false kecuali plugin dipercaya untuk akses model lintas agen.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Izinkan Penggantian Profil Autentikasi LLM oleh Plugin`},help:{"v1-9ityw9-4x":`Mengizinkan plugin ini memilih profil autentikasi non-default untuk penyelesaian runtime agen yang terisolasi. Biarkan false kecuali plugin dipercaya untuk perutean kredensial terisolasi secara eksplisit.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Model Penyelesaian LLM yang Diizinkan untuk Plugin`},help:{"v1-1ul08he-54":`Target yang diizinkan untuk setiap penyelesaian LLM plugin sebagai referensi kanonis "provider/model", termasuk default yang ditentukan host dan penggantian. Gunakan "*" hanya jika Anda memang ingin mengizinkan model apa pun.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Model LLM Plugin yang Diizinkan`},help:{"v1-154sk45-47":`Target penggantian yang diizinkan untuk panggilan LLM plugin tepercaya sebagai referensi kanonis "provider/model". Gunakan "*" hanya jika Anda memang ingin mengizinkan penggantian dengan model apa pun.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Izinkan Penggantian Model LLM Plugin`},help:{"v1-uw4jmc-47":`Secara eksplisit mengizinkan plugin ini meminta penggantian model di api.runtime.llm.complete. Pertahankan nilai false kecuali plugin tersebut dipercaya untuk mengarahkan pemilihan model.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Kebijakan Subagen Plugin`},help:{"v1-wbf4m1-4d":`Kontrol runtime subagen per plugin untuk kepercayaan penggantian model dan daftar izin. Biarkan tidak diatur kecuali plugin harus secara eksplisit mengarahkan pemilihan model subagen.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Model Subagen Plugin yang Diizinkan`},help:{"v1-2pvkow-42":`Target penggantian yang diizinkan untuk eksekusi subagen plugin tepercaya sebagai referensi kanonis "provider/model". Gunakan "*" hanya jika Anda memang ingin mengizinkan model apa pun.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Izinkan Penggantian Model Subagen Plugin`},help:{"v1-1r5tzm1-4g":`Secara eksplisit mengizinkan plugin ini meminta penggantian penyedia/model saat subagen berjalan di latar belakang. Pertahankan nilai false kecuali plugin dipercaya untuk mengarahkan pemilihan model.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Pemuat Plugin`},help:{"v1-1myjwbi-52":`Grup konfigurasi pemuat plugin untuk menentukan jalur sistem berkas tempat plugin ditemukan. Pastikan jalur pemuatan ditentukan secara eksplisit dan ditinjau untuk menghindari pemuatan ekstensi yang tidak tepercaya secara tidak sengaja.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Jalur Pemuatan Plugin`},help:{"v1-o689p1-4z":`Berkas atau direktori plugin tambahan yang dipindai oleh pemuat selain lokasi bawaan. Gunakan direktori khusus ekstensi dan hindari jalur yang terlalu luas dengan konten yang dapat dieksekusi dan tidak terkait.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Slot Plugin`},help:{"v1-zx6crl-5f":`Memilih plugin yang memiliki slot runtime eksklusif seperti memori sehingga hanya satu plugin yang menyediakan kemampuan tersebut. Tetapkan kepemilikan slot secara eksplisit untuk menghindari penyedia yang tumpang tindih dengan perilaku yang saling bertentangan.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Plugin Mesin Konteks`},help:{"v1-4v13iw-2t":`Memilih plugin mesin konteks yang aktif berdasarkan id sehingga satu plugin menyediakan perilaku orkestrasi konteks.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Plugin Memori`},help:{"v1-80ngcl-23":`Pilih plugin memori yang aktif berdasarkan id, atau "none" untuk menonaktifkan plugin memori.`}},presence:{label:{"v1-10fdwo4-8":`Kehadiran`}},proxy:{label:{"v1-ji57pa-d":`Proksi Terkelola`},help:{"v1-vui6bx-58":`Perutean proksi penerusan yang dikelola operator untuk jalur HTTP, HTTPS, WebSocket, dan lalu lintas keluar mentah yang didukung pada runtime OpenClaw. Gunakan ini saat kontrol lalu lintas keluar terpusat merupakan bagian dari batas penerapan.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Proksi Terkelola Diaktifkan`},help:{"v1-1456xdw-49":`Pengaturan pengesampingan eksplisit untuk proksi terkelola. Keberadaan URL mengaktifkan perutean secara default; tetapkan false untuk mengabaikan URL proksi yang dikonfigurasi atau berasal dari lingkungan tanpa menghapusnya.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Mode Loopback Proksi Terkelola`},help:{"v1-1kaiuh0-3c":`Mengontrol perutean bidang kontrol loopback Gateway saat mode proksi terkelola aktif: "gateway-only", "proxy", atau "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL Proksi Terkelola`},help:{"v1-p36b5l-3v":`URL proksi penerusan terkelola. Gunakan http:// untuk proksi CONNECT biasa atau https:// jika koneksi ke titik akhir proksi itu sendiri harus menggunakan TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS Proksi Terkelola`},help:{"v1-6i0vu-3q":`Pengaturan TLS yang digunakan saat terhubung ke titik akhir proksi terkelola. Pengaturan ini berlaku untuk TLS proksi, bukan TLS tujuan setelah CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`File CA TLS Proksi Terkelola`},help:{"v1-1ntzjia-2p":`Jalur sistem file ke bundel CA kustom yang digunakan untuk memverifikasi sertifikat titik akhir proksi terkelola HTTPS.`}},secrets:{label:{"v1-1sihgpy-7":`Rahasia`},help:{"v1-jgn0o9-2l":`Penyedia referensi rahasia, perilaku penyimpanan bersama, dan perlindungan lalu lintas keluar subproses opsional.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Proksi Lalu Lintas Keluar Rahasia`},help:{"v1-1qfgid-4n":`Proksi loopback milik Gateway yang mengganti penanda rahasia penyimpanan bersama hanya saat permintaan keluar dikirim. Mulai ulang Gateway setelah mengubah bagian ini, yang hanya diterapkan saat startup.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Host yang Diizinkan untuk Proksi Lalu Lintas Keluar Rahasia`},help:{"v1-9ypodl-6t":`Daftar izin lalu lintas opsional untuk permintaan dan terowongan CONNECT. Jika ditetapkan, tujuan harus tercantum dalam daftar ini, pengikatan host per rahasia, atau bypassHosts. Daftar kosong hanya mengizinkan host yang terikat atau dikecualikan. Mulai ulang Gateway setelah mengubahnya.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Host yang Dikecualikan dari Proksi Keluar Rahasia`},help:{"v1-1oiiomv-57":`Nama host persis yang menggunakan terowongan CONNECT buta terautentikasi untuk klien dengan penyematan sertifikat. Sentinel tetap berupa teks tersandi dan akan gagal dalam autentikasi vendor alih-alih mengekspos teks biasa.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Proksi Keluar Rahasia Diaktifkan`},help:{"v1-u99b1i-2h":`Mengaktifkan substitusi rahasia pada lalu lintas keluar untuk subproses agen yang dihosting oleh Gateway. Default: false.`}},session:{label:{"v1-8yh9jr-7":`Sesi`},help:{"v1-j86s32-5d":`Kontrol global untuk perutean sesi, pengaturan ulang, kebijakan pengiriman, dan pemeliharaan yang mengatur perilaku riwayat percakapan. Pertahankan pengaturan default kecuali Anda memerlukan batasan isolasi, retensi, atau pengiriman yang lebih ketat.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Cakupan Sesi DM`},help:{"v1-ql362c-5l":`Pengaturan cakupan sesi DM: "main" menjaga kesinambungan, sedangkan "per-peer", "per-channel-peer", dan "per-account-channel-peer" meningkatkan isolasi. Gunakan mode terisolasi untuk kotak masuk bersama atau penerapan multiakun.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Cakupan Sesi Grup`},help:{"v1-1fdezx2-6i":`Pengaturan cakupan sesi grup/kanal: "per-group" memisahkan ruang sementara sesi utama agen memantaunya di latar belakang, terlepas dari dmScope; "main" menggabungkan konteks ruang ke dalam sesi utama dan tidak memerlukan pemantauan. Gunakan "main" hanya untuk ruang tepercaya.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Tautan Identitas Sesi`},help:{"v1-1y5jnsm-5n":`Memetakan identitas kanonis ke ID rekan dengan prefiks penyedia agar pengguna yang sama diarahkan ke satu utas DM (contoh: telegram:123456). Gunakan ini ketika orang yang sama muncul di beberapa kanal atau akun.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Kunci Utama Sesi`},help:{"v1-18p638h-3q":`Diterima tetapi diabaikan: sufiks sesi utama per agen selalu "main". Hilangkan kolom ini; cakupan sesi global menggunakan "global" sebagai gantinya.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Pemeliharaan Sesi`},help:{"v1-imr441-66":`Kontrol pemeliharaan otomatis penyimpanan sesi untuk pengarsipan dasbor, batas usia penghapusan, batas jumlah entri, retensi arsip pengaturan ulang, dan pembersihan berdasarkan anggaran disk. Mulai dalam mode warn untuk mengamati dampaknya, lalu beralih ke enforce setelah ambang batas disesuaikan.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Arsipkan Sesi Dasbor yang Tidak Aktif Setelah`},help:{"v1-1frdtub-5n":"Mengarsipkan sesi dasbor yang tidak aktif setelah durasi ini (misalnya `7d`) agar tetap tersedia tanpa memenuhi daftar sesi aktif. Tetapkan `false` atau `0` untuk menonaktifkan pengarsipan dasbor otomatis."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Penyimpanan Arsip Transkrip`},help:{"v1-1kp9s9h-5s":`Memindahkan transkrip yang tidak aktif ke arsip JSONL terkompresi sambil mempertahankan metadata sesi. File arsip menjadi bagian riwayat yang wajib disimpan dan harus disertakan dalam cadangan. Perubahan berlaku tanpa memulai ulang Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Arsipkan Setelah Jumlah Hari Tidak Aktif`},help:{"v1-zay1q3-5b":`Arsipkan transkrip setelah tidak aktif selama jumlah hari ini (bilangan bulat positif, default 30). Pekerjaan aktif tetap terlindungi; perubahan ambang batas berlaku pada siklus proses latar berikutnya tanpa memulai ulang Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Arsipkan Transkrip Lama Secara Otomatis`},help:{"v1-6p6vmb-5a":`Mengaktifkan pengarsipan transkrip di latar belakang (default false). Proses latar belakang memeriksa transkrip yang memenuhi syarat setiap menit. Kebijakan pengarsipan eksplisit ini terpisah dari penghapusan dan pembersihan berdasarkan batas penggunaan disk.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Target Batas Atas Penggunaan Disk Sesi`},help:{"v1-143vh09-7z":`Ukuran target setelah pembersihan berdasarkan anggaran disk (batas atas). Nilai default adalah 80% dari maxDiskBytes; tetapkan secara eksplisit untuk pengosongan ruang yang lebih ketat pada disk berkapasitas terbatas. Nilai yang menghasilkan nol akan kembali ke nilai default; nilai negatif tidak valid. Untuk menonaktifkan anggaran, gunakan maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Anggaran Disk Maksimum Sesi`},help:{"v1-147lxk3-cj":'Batas penggunaan disk fisik per agen yang mencakup SQLite utama/WAL dan artefak direktori sesi yang diperhitungkan (misalnya `500mb`). Nilai default adalah `10gb`; data yang dilindungi dapat membuat penggunaan tetap di atas target. Jika batas terlampaui, mode warn melaporkan tekanan kapasitas dan mode enforce menghapus artefak reset/penghapusan lama, riwayat yang tidak dirujuk, lalu arsip yang dibuat akibat batas jumlah entri. Arsip manual, retensi berbasis usia, dasbor, pemulihan, dan versi lama tetap dilindungi. Atur ke `false`, `0`, atau `"0"` untuk menonaktifkan.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Jumlah Maksimum Entri Sesi`},help:{"v1-1w2egrh-7u":`Membatasi jumlah entri sesi yang belum diarsipkan (default 5000). Percakapan persisten yang memenuhi syarat dan melebihi batas diarsipkan beserta riwayatnya; entri otomatisasi sekali pakai dihapus. Arsip yang sudah ada tidak diperhitungkan dalam batas ini. Entri aktif yang dilindungi tetap dihitung dan dapat membuat jumlah entri dalam penyimpanan tetap di atas batas.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Mode Pemeliharaan Sesi`},help:{"v1-bq39hk-6v":`Menentukan apakah kebijakan pemangkasan dan batas penggunaan disk hanya dilaporkan ("warn") atau diterapkan secara aktif ("enforce"). Tetap gunakan "warn" selama peluncuran dan beralihlah ke "enforce" setelah memvalidasi ambang batas yang aman. Penyimpanan arsip memiliki pengaturan enabled eksplisit tersendiri.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Pertahankan Sesi Terbaru`},help:{"v1-138q5wx-89":"Melindungi sesi interaktif yang aktif dalam rentang waktu ini (misalnya `7d`) dari penghapusan riwayat otomatis berdasarkan usia, jumlah entri, dan batas penggunaan disk. Jika tidak diatur atau diatur ke `false`, kebijakan normal yang memprioritaskan entri terlama tetap berlaku. Baris sintetis untuk eksekusi model, cron, hook, heartbeat, ACP, dan subagen tetap memenuhi syarat untuk pembersihan terbatas."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Pangkas Sesi Setelah`},help:{"v1-1xn50w7-76":"Mengarsipkan percakapan persisten yang memenuhi syarat dan menghapus entri otomatisasi sekali pakai yang lebih lama dari durasi ini (default `30d`; misalnya `12h`). Riwayat percakapan yang diarsipkan tetap tersimpan dan percakapan dapat dipulihkan; percakapan yang dilindungi atau dapat dirutekan tetap aktif."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Retensi Arsip Reset Sesi`},help:{"v1-16amrs1-7r":"Retensi berbasis usia untuk transkrip yang diarsipkan (`*.reset.<timestamp>` dan `*.deleted.<timestamp>`). Secara default, arsip disimpan hingga batas penggunaan disk mengharuskan penghapusan, dimulai dari yang terlama; tetapkan durasi (misalnya `30d`) untuk mengaktifkan penghapusan berdasarkan waktu aktual, atau `false` untuk menonaktifkannya secara eksplisit."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Beri Tahu Beranda Saat Sesi Dibuat`},help:{"v1-c4prn5-8b":`Antrekan pemberitahuan sistem di sesi Beranda milik agen pemilik saat sesi dibuat (default: true). Pemberitahuan menyertakan judul dan metadata pembuat yang tersedia, serta dibaca pada giliran Beranda atau heartbeat berikutnya. Atur ke false untuk menonaktifkan; draf, sesi penyamaran, sesi internal, dan eksekusi cron terjadwal dikecualikan.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Kebijakan Reset Sesi`},help:{"v1-1hmt7n3-6r":`Menentukan objek kebijakan reset default yang digunakan saat tidak ada pengaturan pengganti khusus jenis atau kanal yang berlaku. Secara default, sesi tidak direset otomatis; gunakan jadwal harian atau berdasarkan waktu tidak aktif untuk mengaktifkannya, sementara /new dan /reset tetap tersedia kapan saja.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Jam Reset Harian Sesi`},help:{"v1-wry8cv-59":`Menetapkan batas jam lokal (0-23) untuk mode reset harian agar sesi berganti pada waktu yang dapat diprediksi. Gunakan dengan mode=daily dan sesuaikan dengan zona waktu yang diharapkan operator agar perilakunya mudah dipahami.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Menit Tidak Aktif untuk Reset Sesi`},help:{"v1-1kzj0id-5e":`Menetapkan rentang waktu tidak aktif sebelum reset untuk mode tidak aktif dan juga dapat berfungsi sebagai pengaman tambahan pada mode harian. Gunakan nilai yang lebih besar untuk menjaga kesinambungan atau nilai yang lebih kecil untuk utas berumur pendek yang lebih segar.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Mode Reset Sesi`},help:{"v1-e5ie4w-5b":`Memilih strategi pengaturan ulang: "none" menonaktifkan pengaturan ulang otomatis (default), "daily" mengatur ulang pada jam yang dikonfigurasi, dan "idle" mengatur ulang setelah tidak ada aktivitas. /new dan /reset tetap tersedia di setiap mode.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Pengaturan Ulang Sesi berdasarkan Kanal`},help:{"v1-1uxsulx-5h":`Menyediakan pengaturan ulang khusus kanal dengan ID penyedia/kanal sebagai kunci untuk mengontrol perilaku secara terperinci. Gunakan ini hanya jika suatu kanal memerlukan perilaku pengaturan ulang khusus di luar kebijakan tingkat jenis.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Pengaturan Ulang Sesi berdasarkan Jenis Chat`},help:{"v1-ypdr7u-52":`Mengganti perilaku pengaturan ulang berdasarkan jenis chat (langsung, grup, utas) jika pengaturan default tidak memadai. Gunakan ini jika aktivitas grup/utas memerlukan frekuensi pengaturan ulang yang berbeda dari pesan langsung.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Pengaturan Ulang Sesi (Langsung)`},help:{"v1-fjnlp5-56":`Menentukan kebijakan pengaturan ulang untuk chat langsung dan menggantikan konfigurasi dasar session.reset untuk jenis tersebut. Gunakan ini sebagai pengaturan pengganti utama untuk pesan langsung, bukan alias lama dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Pengaturan Ulang Sesi (Grup)`},help:{"v1-hl1200-4u":`Menentukan kebijakan pengaturan ulang untuk sesi chat grup yang kesinambungan dan pola gangguannya berbeda dari pesan langsung. Gunakan batas waktu tanpa aktivitas yang lebih singkat untuk grup yang ramai jika pergeseran konteks menjadi masalah.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Pengaturan Ulang Sesi (Utas)`},help:{"v1-1hgpeke-4w":`Menentukan kebijakan pengaturan ulang untuk sesi dengan cakupan utas, termasuk alur kerja terfokus dalam utas kanal. Gunakan ini jika sesi utas perlu kedaluwarsa lebih cepat atau lebih lambat daripada jenis chat lainnya.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Pemicu Reset Sesi`},help:{"v1-rcabsw-5a":`Mencantumkan pemicu pesan yang memaksa reset sesi saat ditemukan kecocokan dalam konten masuk. Gunakan secukupnya untuk frasa reset eksplisit agar konteks tidak hilang secara tak terduga selama percakapan normal.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Cakupan Sesi`},help:{"v1-axt4ds-5z":`Menetapkan strategi dasar pengelompokan sesi: "per-sender" memisahkan sesi berdasarkan pengirim dan "global" berbagi satu sesi per konteks kanal. Tetap gunakan "per-sender" untuk perilaku multipengguna yang lebih aman, kecuali konteks bersama memang diperlukan.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Kebijakan Pengiriman Sesi`},help:{"v1-17qpipb-5l":`Mengontrol izin pengiriman lintas sesi menggunakan aturan allow/deny yang dievaluasi berdasarkan channel, chatType, dan prefiks kunci. Gunakan ini untuk membatasi tujuan pengiriman pesan oleh alat sesi dalam lingkungan yang kompleks.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Tindakan Default Kebijakan Pengiriman Sesi`},help:{"v1-15plhut-53":`Menetapkan tindakan cadangan saat tidak ada aturan sendPolicy yang cocok: "allow" atau "deny". Tetap gunakan "allow" untuk pengaturan yang lebih sederhana, atau pilih "deny" jika Anda memerlukan aturan izin eksplisit untuk setiap tujuan.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Aturan Kebijakan Pengiriman Sesi`},help:{"v1-o217za-5h":'Aturan allow/deny berurutan yang dievaluasi sebelum tindakan default, misalnya `{ action: "deny", match: { channel: "discord" } }`. Tempatkan aturan yang paling spesifik terlebih dahulu agar aturan umum tidak mengesampingkan pengecualian.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Tindakan Aturan Pengiriman Sesi`},help:{"v1-178vm80-54":`Menetapkan keputusan aturan sebagai "allow" atau "deny" saat kriteria pencocokan yang terkait terpenuhi. Gunakan urutan yang mendahulukan deny saat menerapkan batasan ketat dengan pengecualian allow yang eksplisit.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Pencocokan Aturan Pengiriman Sesi`},help:{"v1-18qh5qg-5d":`Menetapkan kondisi pencocokan aturan opsional yang dapat menggabungkan batasan channel, chatType, dan prefiks kunci. Jaga cakupan pencocokan tetap sempit agar maksud kebijakan mudah dipahami dan proses debug tetap sederhana.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Kanal Aturan Pengiriman Sesi`},help:{"v1-u5erwx-50":`Mencocokkan penerapan aturan dengan ID kanal/penyedia tertentu (misalnya discord, telegram, slack). Gunakan ini saat satu kanal harus mengizinkan atau menolak pengiriman secara terpisah dari kanal lain.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Jenis Chat Aturan Pengiriman Sesi`},help:{"v1-7cv4f9-4z":`Mencocokkan penerapan aturan dengan jenis chat (direct, group, thread) sehingga perilaku berbeda sesuai bentuk percakapan. Gunakan ini saat tujuan DM dan grup memerlukan batasan keamanan yang berbeda.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Prefiks Kunci Aturan Pengiriman Sesi`},help:{"v1-ac4dee-5n":`Mencocokkan prefiks kunci sesi yang telah dinormalisasi setelah langkah normalisasi kunci internal pada komponen pengguna kebijakan. Gunakan ini untuk kontrol prefiks umum, dan utamakan rawKeyPrefix saat pencocokan persis terhadap kunci lengkap diperlukan.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Prefiks Kunci Mentah Aturan Pengiriman Sesi`},help:{"v1-1g9w044-5e":`Mencocokkan prefiks kunci sesi mentah yang belum dinormalisasi untuk menargetkan kebijakan berdasarkan kunci lengkap secara tepat. Gunakan ini jika keyPrefix yang dinormalisasi terlalu luas dan Anda memerlukan ketepatan berdasarkan prefiks agen atau transport tertentu.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Mode Berbagi Sesi`},help:{"v1-xbh52d-5a":`Mengontrol mode kolaborasi yang dapat dipilih oleh pemilik sesi dan administrator. Nilai boolean yang tidak ditentukan secara default dianggap aktif; tetapkan suatu mode ke false untuk menghapusnya dari pemilih dan menolak pemilihan baru.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Izinkan Sesi Draf`},help:{"v1-1lzap27-2p":`Mengizinkan visibilitas draf, yang menyembunyikan sesi dari operator yang bukan pemilik maupun administrator. Default: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Izinkan Sesi Hanya Baca`},help:{"v1-upl3nu-21":`Mengizinkan sesi dijadikan hanya baca bagi pengguna yang bukan peserta. Default: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Izinkan Sesi Saran`},help:{"v1-4i8owu-4g":`Mengizinkan visibilitas saran. Pada tahap ini, kebijakan akses yang diterapkan sama dengan mode hanya baca; antrean saran dikonfigurasi oleh fitur yang akan hadir kemudian. Default: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Jalur Penyimpanan Sesi`},help:{"v1-hreznz-56":`Menetapkan jalur file penyimpanan sesi yang digunakan untuk mempertahankan catatan sesi setelah mulai ulang. Gunakan jalur eksplisit hanya jika Anda memerlukan tata letak disk khusus, pengaturan tujuan pencadangan, atau penyimpanan pada volume yang terpasang.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Pengikatan Utas Sesi`},help:{"v1-zbzihu-4s":`Pengaturan bawaan bersama untuk pembuatan dan perutean sesi yang terikat pada utas di seluruh kanal yang didukung. Konfigurasikan pengaturan bawaan global di sini dan timpa per kanal hanya jika perilakunya berbeda.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Konteks Pembuatan Sesi Utas`},help:{"v1-1set6nw-4c":`Konteks subagen native bawaan untuk pembuatan sesi yang terikat pada utas. Gunakan "fork" untuk memulai dari transkrip pemohon atau "isolated" untuk sesi anak yang bersih. Bawaan: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Pengikatan Utas Diaktifkan`},help:{"v1-foomtc-3f":`Sakelar utama global untuk pembuatan, perutean, dan pengiriman sesi yang terikat pada utas. Nonaktifkan untuk mematikan pengikatan utas secara global.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Batas Waktu Tidak Aktif Pengikatan Utas (jam)`},help:{"v1-gffnx3-3h":`Periode tidak aktif bawaan dalam jam untuk sesi yang terikat pada utas di seluruh penyedia/kanal (0 menonaktifkan kedaluwarsa akibat tidak aktif). Bawaan: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Usia Maksimum Pengikatan Utas (jam)`},help:{"v1-1xfcyhw-39":`Batas usia maksimum mutlak opsional dalam jam untuk sesi yang terikat pada utas di seluruh penyedia/kanal (0 menonaktifkan batas mutlak). Bawaan: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Pembuatan Sesi yang Terikat pada Utas`},help:{"v1-1lqwbdl-46":`Kontrol izin bawaan global untuk membuat sesi kerja yang terikat pada utas dari sessions_spawn dan pembuatan utas ACP. Bawaan: true saat pengikatan utas diaktifkan.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Target Tautan Simbolis Skill yang Diizinkan`},help:{"v1-xzybiq-4t":`Direktori akar target sebenarnya yang tepercaya dan boleh dituju oleh symlink skill saat target berada di luar direktori akar sumber yang dikonfigurasi. Batasi cakupannya, misalnya ke direktori skill di repositori sejajar.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Direktori Skill Tambahan`},help:{"v1-11o7opu-53":`Direktori akar skill bersama tambahan yang akan dipindai dengan prioritas terendah. Gunakan ini untuk repositori sejajar atau paket skill bersama yang perlu tersedia tanpa menyalinnya ke ruang kerja OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Pantau Skills`},help:{"v1-1ckr2l5-5d":`Aktifkan pemantauan sistem berkas untuk mendeteksi perubahan definisi skill agar pembaruan dapat diterapkan tanpa memulai ulang seluruh proses. Tetap aktifkan dalam alur kerja pengembangan dan nonaktifkan pada image produksi yang tidak dapat diubah.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Mode Otonom Skill Workshop`},help:{"v1-1s3kgit-6j":`Mengontrol pembelajaran latar belakang: "off" hanya menampilkan pengingat saran, "propose" membuat usulan yang menunggu tindak lanjut, dan "auto" menerapkan usulan yang tercatat serta menjalankan tinjauan mingguan terhadap skill milik Workshop melalui pengeditan berkas biasa. Default: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Kebijakan Antarmuka`},help:{"v1-vgtjbs-50":`Penggantian kebijakan pesan per antarmuka dengan kunci berupa ID antarmuka pengiriman yang telah ditentukan. Gunakan ini hanya jika satu antarmuka yang diterapkan memerlukan penanganan balasan senyap yang lebih ketat daripada default agen.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Kebijakan Balasan Senyap Antarmuka`},help:{"v1-12zgc3n-60":`Mengganti kebijakan balasan senyap untuk satu antarmuka pengiriman yang telah ditentukan. Kolom yang tidak diatur mewarisi agents.defaults.silentReply; gunakan ID antarmuka dengan cakupan terbatas agar perilaku internal atau khusus grup tidak meluas ke tujuan lain.`}},talk:{label:{"v1-15ukbjj-4":`Bicara`},help:{"v1-1gx10xa-5g":`Pengaturan sintesis suara mode Talk untuk identitas suara, pemilihan model, format keluaran, dan perilaku interupsi. Gunakan bagian ini untuk menyesuaikan pengalaman pengguna suara sekaligus mengendalikan latensi dan biaya.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Agen Talk`},help:{"v1-iee5l9-2b":`Agen yang memiliki sesi Talk yang dibuat tanpa kunci sesi dengan cakupan agen yang eksplisit.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Mode Cepat Konsultasi Talk`},help:{"v1-syf3xk-2o":`Gunakan ini untuk menetapkan mode cepat ke true atau false bagi eksekusi agen reguler di balik konsultasi Talk waktu nyata.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Tingkat Berpikir Konsultasi Talk`},help:{"v1-1ft5njw-2o":`Gunakan ini untuk mengganti tingkat berpikir bagi eksekusi agen reguler di balik konsultasi Talk waktu nyata.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Interupsi Talk Saat Pengguna Berbicara`},help:{"v1-8n9q4o-3l":`Jika true (default), hentikan ucapan asisten saat pengguna mulai berbicara dalam mode Talk. Biarkan aktif untuk mendukung giliran berbicara dalam percakapan.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Penyedia Aktif Talk`},help:{"v1-wgnxhg-1g":`ID penyedia Talk yang aktif (misalnya "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Pengaturan Penyedia Talk`},help:{"v1-oh0yuv-30":`Pengaturan Talk khusus penyedia dengan ID penyedia sebagai kunci. Selama migrasi, utamakan pengaturan ini daripada kunci talk.* lama.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Konfigurasi Penyedia Talk`},help:{"v1-36pblg-1r":`Kolom konfigurasi Talk milik penyedia untuk ID penyedia yang sesuai.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Kunci API Penyedia Talk`},help:{"v1-1a1p9wp-v":`Kunci API penyedia untuk mode Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk Waktu Nyata`},help:{"v1-c2re7j-3z":`Penyedia, model, suara, mode, transportasi, dan strategi penalaran Talk waktu nyata. Simpan konfigurasi penyedia ucapan/TTS di talk.provider dan talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Penalaran Talk Waktu Nyata`},help:{"v1-opsatw-37":`Strategi penalaran Talk: agent-consult untuk bantuan agen melalui Gateway, direct-tools untuk pemanggilan alat lokal, atau none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Perutean Konsultasi Talk Waktu Nyata`},help:{"v1-10qjcvk-5f":`Relai cadangan Gateway untuk transkrip akhir pengguna saat penyedia waktu nyata melewatkan openclaw_agent_consult. provider-direct mempertahankan balasan penyedia; force-agent-consult merutekan melalui OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Instruksi Talk Waktu Nyata`},help:{"v1-1jaaj84-5p":`Instruksi sistem tambahan yang ditambahkan ke prompt Talk waktu nyata bawaan OpenClaw. Gunakan ini untuk gaya suara, nada, dan perilaku waktu nyata lainnya di sisi penyedia sambil tetap mempertahankan panduan agent-consult.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Mode Talk Waktu Nyata`},help:{"v1-1u2xui1-1l":`Mode eksekusi Talk: realtime, stt-tts, atau transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Model Talk Waktu Nyata`},help:{"v1-amou5a-27":`Penggantian ID model penyedia waktu nyata untuk sesi Talk di browser atau yang dikelola Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Padding Awal Talk Waktu Nyata (ms)`},help:{"v1-1cwg07n-22":`Durasi audio dalam milidetik yang dipertahankan sebelum aktivitas suara waktu nyata terdeteksi.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Penyedia Talk Waktu Nyata`},help:{"v1-wwsmpt-1o":`ID penyedia suara waktu nyata yang aktif, seperti openai atau google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Pengaturan Penyedia Waktu Nyata Talk`},help:{"v1-ruagcu-1r":`Pengaturan suara waktu nyata khusus penyedia dengan ID penyedia sebagai kunci.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Konfigurasi Penyedia Waktu Nyata Talk`},help:{"v1-edfpxm-1u":`Konfigurasi suara waktu nyata milik penyedia untuk ID penyedia yang sesuai.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Kunci API Penyedia Waktu Nyata Talk`},help:{"v1-1fbmgpx-z":`Kunci API penyedia untuk Talk waktu nyata.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Upaya Penalaran Waktu Nyata Talk`},help:{"v1-157xd3e-2t":`Upaya penalaran khusus penyedia untuk sesi Talk waktu nyata, seperti minimal, low, medium, atau high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Durasi Keheningan Waktu Nyata Talk (ms)`},help:{"v1-1grnu06-1y":`Durasi keheningan dalam milidetik sebelum giliran pengguna Talk waktu nyata ditetapkan sebagai selesai.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Suara Pembicara Waktu Nyata Talk`},help:{"v1-1kgb166-2h":`Penggantian nama suara pembicara penyedia waktu nyata untuk sesi Talk di browser atau yang dikelola Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`ID Suara Pembicara Waktu Nyata Talk`},help:{"v1-1k8w6vk-2f":`Penggantian ID suara pembicara penyedia waktu nyata untuk sesi Talk di browser atau yang dikelola Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Transport Waktu Nyata Talk`},help:{"v1-2otjgn-2g":`Transport byte/sesi Talk: webrtc, provider-websocket, gateway-relay, atau managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Ambang Batas VAD Real-time Talk`},help:{"v1-nf5l2t-2j":`Ambang batas deteksi aktivitas suara real-time dari 0 (paling sensitif) hingga 1 (paling tidak sensitif).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Batas Waktu Keheningan Talk (ms)`},help:{"v1-1kim32f-59":`Durasi keheningan pengguna dalam milidetik sebelum mode Talk menyelesaikan dan mengirim transkrip saat ini. Biarkan tidak diatur untuk menggunakan durasi jeda bawaan platform (700 ms di macOS dan Android, 900 ms di iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Lokal Pengenalan Ucapan Talk`},help:{"v1-1un3x4l-4c":`ID lokal BCP 47 untuk pengenalan ucapan Talk pada node perangkat dan suara sistem cadangan iOS, misalnya "ru-RU". Biarkan tidak diatur untuk menggunakan pengaturan bawaan setiap perangkat.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetri`},help:{"v1-1o5tru3-55":`Persetujuan eksplisit untuk statistik fitur anonim yang disertakan dalam pemeriksaan pembaruan harian. Statistik fitur dinonaktifkan secara bawaan dan tidak pernah menyertakan pesan, kredensial, atau pengenal.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Stempel Waktu Persetujuan Statistik Fitur`},help:{"v1-1t051az-3t":`Stempel waktu ISO yang mencatat kapan operator menerima atau menolak statistik fitur anonim. Mencegah panduan penyiapan menanyakannya lagi.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Statistik Fitur Anonim`},help:{"v1-1ptrwuq-4r":`Membagikan nama saluran dan penyedia yang diaktifkan, jumlah plugin, serta jumlah sesi terbaru dalam pemeriksaan pembaruan harian. Dinonaktifkan secara bawaan dan selalu dinonaktifkan saat DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Alat`},help:{"v1-1el54kl-5h":`Infrastruktur alat dan pengaturan default lintas agen. Entri sejajar di tingkat root mengatur infrastruktur dan pengaturan default lintas agen; agents.defaults mengatur perilaku loop agen; entri agen dapat menimpa keduanya jika didukung.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Akses Alat Antaragen`},help:{"v1-1ynpa5f-cf":`Kebijakan untuk pemanggilan alat sesi lintas agen: pengiriman, daftar, riwayat, pencarian, dan pembacaan status (default: diaktifkan). Gunakan allow untuk membatasi pasangan agen; enabled=false memblokir akses lintas agen biasa. Sesi subagen native dan sesi anak ACP milik pemohon tetap dapat diakses dengan visibilitas tree atau all. Untuk pemisahan yang ketat, atur tools.sessions.visibility ke agent atau self (tree masih mengizinkan sesi anak native/ACP milik pemohon), atau gunakan gateway terpisah.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Daftar Target yang Diizinkan Antaragen`},help:{"v1-1jt2ari-76":`ID agen atau pola * yang boleh berpartisipasi dalam pemanggilan lintas agen; agen pemohon dan agen target harus sama-sama cocok. Akses lintas agen diaktifkan secara default, dan allow yang tidak disertakan atau kosong mengizinkan setiap pasangan. Tetapkan daftar eksplisit untuk membatasi akses; entri kosong menolak akses.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Aktifkan Alat Antaragen`},help:{"v1-w950oq-ba":`Mengaktifkan akses alat sesi lintas agen (default: true); allow yang tidak disertakan atau kosong mengizinkan setiap pasangan agen. Atur ke false untuk memblokir akses lintas agen biasa; sesi subagen native dan sesi anak ACP milik pemohon tetap dapat diakses dengan visibilitas tree atau all. Untuk pemisahan yang ketat, atur tools.sessions.visibility ke agent atau self (tree masih mengizinkan sesi anak native/ACP milik pemohon), atau gunakan gateway terpisah.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Daftar Alat yang Diizinkan`},help:{"v1-1is3eaq-4v":`Daftar izin alat absolut yang menggantikan pengaturan default dari profil untuk lingkungan dengan aturan ketat. Gunakan ini hanya jika Anda sengaja menjalankan sebagian kecil kapabilitas alat yang dipilih secara ketat.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Tambahan Daftar Izin Alat`},help:{"v1-1xw9zp8-57":`Entri tambahan dalam daftar izin alat yang digabungkan dengan profil alat yang dipilih dan kebijakan default. Pastikan daftar ini ringkas dan eksplisit agar audit dapat dengan cepat mengidentifikasi pengecualian kebijakan yang disengaja.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Kebijakan Alat per Penyedia`},help:{"v1-1ecljob-4y":`Penggantian aturan izin/penolakan alat per penyedia, dengan ID kanal/penyedia sebagai kunci, untuk menyesuaikan kapabilitas pada setiap antarmuka. Gunakan ini ketika satu penyedia memerlukan kontrol yang lebih ketat daripada kebijakan alat global.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Mode Kode`},help:{"v1-1ecc39k-6k":'Mode Kode OpenClaw generik. Jika tidak ditetapkan secara global, nilai defaultnya adalah `"auto"`; objek yang ditulis tanpa `enabled` tetap nonaktif. Eksekusi agen dengan mode ini aktif hanya menyediakan `exec` dan `wait` kepada model dan mengakses alat biasa melalui jembatan katalog.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Aktifkan Mode Kode`},help:{"v1-rgstxz-aj":'Aktivasi Mode Kode OpenClaw global. Jika pengaturan global sama sekali tidak ada, nilai defaultnya adalah `"auto"`; objek yang ditulis tanpa `enabled` tetap nonaktif. `"auto"` mengaktifkan mode ini untuk model yang mengutamakan katalog, sedangkan `true` mengaktifkannya untuk eksekusi yang mendukung alat. Pengaturan aktivasi khusus agen dan model lebih diutamakan. Eksekusi dengan mode ini aktif akan dihentikan secara aman jika runtime tidak tersedia, alih-alih menyediakan daftar alat lengkap.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Eksekutor Mode Kode`},help:{"v1-l8nlk2-6x":`Eksekutor JavaScript: "node" (default) menggunakan Node vm untuk kode tepercaya dan bukan sandbox keamanan; "quickjs" menggunakan plugin QuickJS WASM yang disertakan untuk eksekusi tamu dengan keamanan yang diperkuat. Izin alat berlaku untuk keduanya. Jika eksekutor yang dipilih tidak tersedia, eksekusi diblokir demi keamanan.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Batas Keluaran Mode Kode`},help:{"v1-1hmij9q-1n":`Jumlah maksimum byte terserialisasi yang dikembalikan melalui keluaran mode kode.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Batas Pemanggilan Alat Tertunda Mode Kode`},help:{"v1-3b5tyd-2i":`Jumlah maksimum pemanggilan alat bersarang secara bersamaan yang dapat dimulai oleh VM mode kode sebelum harus dilanjutkan nanti.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Hasil Pencarian Maksimum Mode Kode`},help:{"v1-1gpue5r-28":`Jumlah maksimum hasil pencarian katalog tersembunyi yang dapat diminta oleh program mode kode.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Batas Snapshot Mode Kode`},help:{"v1-1mmgkqy-1x":`Jumlah maksimum byte terserialisasi yang disimpan untuk satu snapshot QuickJS yang ditangguhkan.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Batas Memori Mode Kode`},help:{"v1-xetora-6n":`Batas heap tamu QuickJS atau anggaran heap V8 untuk worker Node yang diupayakan sebaik mungkin, dalam byte. Overhead runtime Node dan alokasi minimum mesin memengaruhi anggaran efektif; buffer eksternal dan RSS proses tidak termasuk. Ini bukan jaminan keamanan.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Antarmuka Mode Kode`},help:{"v1-dsp2b9-2x":'Antarmuka yang disajikan kepada model. Hanya "only" yang didukung: menampilkan `exec` dan `wait` mode kode serta menyembunyikan alat biasa.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Hasil Pencarian Default Mode Kode`},help:{"v1-1io42lu-2m":"Jumlah default hasil pencarian katalog tersembunyi yang dikembalikan oleh `catalog.search` dalam mode kode."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`TTL Snapshot Mode Kode`},help:{"v1-1nxfczz-28":"Durasi eksekusi Code Mode yang ditangguhkan dapat dilanjutkan dengan `wait` sebelum kedaluwarsa."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Batas Waktu Mode Kode`},help:{"v1-8csycm-1p":"Durasi maksimum dalam milidetik untuk satu panggilan `exec` atau `wait` dalam mode kode."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Daftar Blokir Alat`},help:{"v1-wilr1b-4p":`Daftar blokir alat global yang memblokir alat yang tercantum meskipun aturan profil atau penyedia mengizinkannya. Gunakan aturan penolakan untuk pemblokiran darurat dan pertahanan berlapis jangka panjang.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Akses Alat dengan Hak Istimewa`},help:{"v1-ehcm0r-5a":`Kontrol akses alat dengan hak istimewa untuk antarmuka perintah berhak istimewa yang hanya boleh diakses oleh pengirim tepercaya. Biarkan dinonaktifkan kecuali alur kerja operator secara eksplisit memerlukan tindakan dengan hak istimewa.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Aturan Izin Alat dengan Hak Istimewa`},help:{"v1-1u9bhih-54":`Aturan izin pengirim untuk alat dengan hak istimewa, biasanya menggunakan format identitas kanal/penyedia sebagai kunci. Gunakan identitas yang spesifik dan eksplisit agar perintah dengan hak istimewa tidak dapat dipicu oleh pengguna yang tidak dituju.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Aktifkan Akses Alat dengan Hak Istimewa`},help:{"v1-1n8oyal-4l":`Mengaktifkan jalur eksekusi alat dengan hak istimewa saat pemeriksaan pengirim dan kebijakan berhasil. Biarkan dinonaktifkan di kanal publik/bersama dan aktifkan hanya dalam konteks tepercaya yang dioperasikan oleh pemilik.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Alat Exec`},help:{"v1-p5piic-56":`Pengelompokan kebijakan alat Exec untuk host eksekusi shell, mode keamanan, perilaku persetujuan, dan pengikatan runtime. Pertahankan pengaturan default yang konservatif di lingkungan produksi dan perketat jalur eksekusi dengan hak istimewa.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Daftar Model yang Diizinkan untuk apply_patch`},help:{"v1-4q5ovf-1x":`Daftar opsional ID model yang diizinkan (misalnya "gpt-5.4" atau "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Aktifkan apply_patch`},help:{"v1-1erkir4-31":`Aktifkan atau nonaktifkan apply_patch untuk model OpenAI dan OpenAI Codex jika diizinkan oleh kebijakan alat (default: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch Hanya di Ruang Kerja`},help:{"v1-x2z207-3o":`Batasi jalur apply_patch ke direktori ruang kerja (default: true). Atur ke false untuk mengizinkan penulisan di luar ruang kerja (berbahaya).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Pemberitahuan Eksekusi Berjalan Setelah Persetujuan (ms)`},help:{"v1-1gwwann-4z":`Jeda dalam milidetik sebelum menampilkan pemberitahuan sedang berjalan setelah persetujuan eksekusi diberikan. Perbesar untuk mengurangi kedipan pada perintah cepat, atau perkecil agar operator lebih cepat menerima umpan balik.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Permintaan Persetujuan Eksekusi`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Penyorotan Perintah Eksekusi`},help:{"v1-kyxd4o-4n":`Tampilkan penyorotan perintah berdasarkan hasil parser dalam permintaan persetujuan eksekusi (default: false). Aktifkan ini untuk menampilkan teks perintah yang disorot tanpa mengubah kebijakan persetujuan eksekusi.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Masa Berlaku Izin Berkelanjutan (Hari)`},help:{"v1-5uxe2j-6r":`Masa berlaku default, dalam hari (1-3650), untuk izin berkelanjutan yang diterbitkan melalui allow-always pada persetujuan otomatisasi. Jika tidak diatur, izin tetap berlaku hingga dicabut atau otomatisasi pemiliknya berubah. Ketentuan ditetapkan saat penerbitan, sehingga perubahan ini hanya memengaruhi izin yang diterbitkan berikutnya.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Target Eksekusi`},help:{"v1-rno1mf-5q":`Memilih strategi target eksekusi untuk perintah shell. Gunakan "auto" untuk perilaku yang menyesuaikan dengan lingkungan runtime (sandbox jika tersedia, jika tidak gateway), atau tetapkan sandbox/gateway/node secara eksplisit saat Anda memerlukan lingkungan tetap.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Mode Eksekusi`},help:{"v1-1wi6t4l-5q":`Pemilih kebijakan eksekusi yang dinormalisasi. Gunakan "auto" agar kasus yang belum tercakup persetujuan ditinjau oleh pengklasifikasi, "ask" agar kasus tersebut ditinjau oleh manusia, "allowlist" hanya untuk perintah aman yang ditentukan secara deterministik, atau "full" untuk operasi lokal tepercaya.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Pengikatan Node Eksekusi`},help:{"v1-rfnz54-4s":`Konfigurasi pengikatan node untuk alat eksekusi saat eksekusi perintah didelegasikan melalui node yang terhubung. Gunakan pengikatan node secara eksplisit hanya jika perutean multinode diperlukan.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Notifikasi Saat Eksekusi Berakhir`},help:{"v1-1ounlvx-3q":`Jika true (default), sesi eksekusi latar belakang yang berakhir dan peristiwa siklus hidup eksekusi node akan memasukkan peristiwa sistem ke antrean dan meminta heartbeat.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Notifikasi Eksekusi Berhasil Tanpa Output`},help:{"v1-1wx4xxd-3d":`Jika true, eksekusi latar belakang yang berhasil berakhir tanpa output tetap memasukkan peristiwa penyelesaian sistem ke antrean (default: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Penambahan di Awal PATH Eksekusi`},help:{"v1-s1aimc-1r":`Direktori yang ditambahkan di awal PATH untuk proses eksekusi (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Peninjau Eksekusi`},help:{"v1-12y548k-4x":`Peninjau exec berbasis model yang digunakan oleh mode otomatis sebelum beralih ke persetujuan manusia. Konfigurasikan penggantian model khusus di sini jika Anda ingin peninjauan exec terpisah dari model agen utama.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Mode Cepat Peninjau Eksekusi`},help:{"v1-175bx14-8u":`Mode cepat opsional untuk peninjauan persetujuan OpenClaw: true meminta pemrosesan prioritas pada rute OpenAI Responses dan ChatGPT/OAuth yang didukung; false meminta pemrosesan standar. Jangan isi untuk mempertahankan pengaturan default penyedia. Mode cepat mungkin memerlukan biaya lebih tinggi dan bergantung pada ketersediaan dari penyedia. Tidak mengonfigurasi Codex Guardian bawaan.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Model Peninjau Exec`},help:{"v1-1lltiy5-3i":`Penggantian penyedia/model opsional untuk agen peninjau exec. Biarkan kosong untuk menggunakan kembali model utama yang dikonfigurasi untuk agen tujuan.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Penalaran Peninjau Eksekusi`},help:{"v1-yg2gby-6u":`Tingkat upaya penalaran opsional untuk peninjauan persetujuan OpenClaw berbasis model: minimal, low, medium, high, xhigh, atau max. Jangan isi untuk mempertahankan pengaturan default penyedia. Tingkat yang didukung dinormalisasi untuk model yang dipilih. Tidak mengonfigurasi Codex Guardian bawaan.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Batas Waktu Peninjau Exec (ms)`},help:{"v1-1o30chi-3w":`Batas waktu peninjau exec per tahap dalam milidetik untuk persiapan dan penyelesaian model sebelum beralih ke persetujuan manusia (default: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Profil Biner Aman Exec`},help:{"v1-4cdcwe-29":`Profil biner aman opsional untuk setiap biner (batas argumen posisi + flag yang diizinkan/ditolak).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Biner Aman Exec`},help:{"v1-1of1m2s-21":`Izinkan biner aman yang hanya menerima stdin berjalan tanpa entri eksplisit dalam daftar izin.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Direktori Tepercaya Biner Aman Exec`},help:{"v1-zljbcn-2v":`Direktori tambahan yang secara eksplisit dipercaya untuk pemeriksaan jalur biner aman (entri PATH tidak pernah dipercaya secara otomatis).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Keamanan Exec`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Wajibkan Persetujuan Evaluasi Inline`},help:{"v1-jkmgo7-5z":"Wajibkan persetujuan eksplisit untuk bentuk evaluasi inline interpreter seperti `python -c`, `node -e`, `ruby -e`, atau `osascript -e`. Mencegah penggunaan kembali daftar izin secara diam-diam dan mengubah izin selalu menjadi permintaan persetujuan setiap kali untuk bentuk-bentuk tersebut."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Batas Waktu Eksekusi (Detik)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Alat sistem berkas khusus ruang kerja`},help:{"v1-1mhuvka-2s":`Batasi alat sistem berkas (read/write/edit/apply_patch) ke direktori ruang kerja (default: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Identitas GitHub CLI dan Penulis Git`},help:{"v1-1fl77im-5s":`Profil GitHub CLI lokal yang dikelola dan penulis Git opsional untuk alat agen. Jangan sertakan objek ini untuk mempertahankan akun dan penulis bawaan pengguna yang menjalankan Gateway; kredensial remote repositori tidak pernah ditimpa.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Email Penulis Git`},help:{"v1-kol5g6-1i":`Email opsional untuk penulis dan pembuat commit Git yang hanya berlaku dalam proses ini.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Nama Penulis Git`},help:{"v1-z5bl1f-1h":`Nama opsional untuk penulis dan pembuat commit Git yang hanya berlaku dalam proses ini.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Jenis Kredensial GitHub`},help:{"v1-qi3qun-3q":`Menandai profil OAuth terkelola yang kredensial penyegarannya dirotasi dan dimiliki oleh Gateway. Profil tanpa penanda ini menggunakan token akses pribadi.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Versi Profil GitHub`},help:{"v1-4lzl0-27":`Versi profil yang dihasilkan tanpa makna yang dapat ditafsirkan, digunakan untuk mengganti kredensial terkelola secara atomik.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Aktifkan Pemahaman Tautan`},help:{"v1-23t2io-59":`Aktifkan prapemrosesan pemahaman tautan otomatis agar URL dapat diringkas sebelum penalaran agen. Biarkan aktif untuk konteks yang lebih kaya, dan nonaktifkan jika pemrosesan harus benar-benar minimal.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Jumlah Maksimum Tautan untuk Pemahaman Tautan`},help:{"v1-ksxmcv-52":`Jumlah maksimum tautan yang diperluas per giliran selama pemahaman tautan. Gunakan nilai yang lebih rendah untuk mengendalikan latensi/biaya dalam utas yang ramai, dan nilai yang lebih tinggi ketika konteks dari beberapa tautan sangat penting.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Model Pemahaman Tautan`},help:{"v1-6j3mnw-5a":`Daftar model pilihan untuk tugas pemahaman tautan, yang dievaluasi secara berurutan sebagai cadangan jika didukung. Gunakan model ringan terlebih dahulu untuk peringkasan rutin, dan model yang lebih berat hanya jika diperlukan.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Cakupan Pemahaman Tautan`},help:{"v1-183cwpa-55":`Mengatur kapan pemahaman tautan dijalankan berdasarkan konteks percakapan dan jenis pesan. Batasi cakupan untuk menghindari pengambilan data yang tidak perlu pada pesan yang tautannya tidak perlu ditindaklanjuti.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Batas Waktu Pemahaman Tautan (detik)`},help:{"v1-61v30o-4p":`Batas waktu pemahaman per tautan dalam detik sebelum tautan yang belum terselesaikan dilewati. Batasi waktu ini untuk menghindari penundaan panjang saat situs eksternal lambat atau tidak dapat dijangkau.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Deteksi Perulangan Alat`},help:{"v1-1e3rls8-5g":`Mengontrol deteksi perulangan alat berdasarkan riwayat bergulir dan perlindungan setelah pemadatan. Hilangkan pengaturan ini agar deteksi bergulir tetap nonaktif dan perlindungan setelah pemadatan tetap aktif. Atur ke true untuk mengaktifkan keduanya, atau false untuk menonaktifkan keduanya.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Kebijakan Lampiran Pemahaman Audio`},help:{"v1-1s3t9s5-3o":`Pilih lampiran audio yang sesuai untuk diproses. Proses hanya lampiran pertama kecuali transkripsi beberapa lampiran memang diinginkan.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Format Tampilan Ulang Transkrip`},help:{"v1-glpdzh-3i":`Format transkrip yang dikirim kembali dengan placeholder {transcript}. Pertahankan placeholder tersebut agar transkrip disertakan saat dikirim.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Kirim Kembali Transkrip ke Chat`},help:{"v1-1dedp8c-3r":`Kirim kembali transkrip audio ke chat asal sebelum diproses oleh agen. Aktifkan ini saat pengguna perlu memverifikasi apa yang didengar sistem.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Aktifkan Pemahaman Audio`},help:{"v1-1v0x7te-2m":`Aktifkan pemahaman audio agar pesan suara atau klip audio dapat ditranskripsikan untuk konteks agen.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Bahasa Pemahaman Audio`},help:{"v1-1ruqt97-3z":`Petunjuk bahasa default untuk penyedia transkripsi audio. Atur jika bahasa utama yang digunakan sudah diketahui dan deteksi oleh penyedia tidak andal.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Byte Maksimum Pemahaman Audio`},help:{"v1-1mcckc8-43":`Batas ukuran input audio default untuk model yang dikonfigurasi dan dideteksi otomatis. Atur sesuai ukuran rekaman terbesar yang dapat diterima oleh penyedia dan jaringan Anda.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Karakter Maksimum Pemahaman Audio`},help:{"v1-eo1dp-43":`Panjang transkrip maksimum default untuk model yang dikonfigurasi dan dideteksi otomatis. Gunakan nilai yang lebih rendah agar pesan suara yang panjang tidak memperbesar konteks agen.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Model Pemahaman Audio Pilihan`},help:{"v1-1n5zya1-3c":`Utamakan satu entri tools.media.models yang ditandai dengan kapabilitas untuk transkripsi audio sebelum menggunakan opsi cadangan lain yang kompatibel.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Prompt Pemahaman Audio`},help:{"v1-1v5jtay-4b":`Prompt transkripsi audio default saat entri model tidak menggantinya. Pertahankan instruksi agar tetap konsisten jika alur kerja lanjutan bergantung pada gaya transkrip.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Cakupan Pemahaman Audio`},help:{"v1-1pptfg0-3w":`Batasi pemahaman audio berdasarkan kanal, jenis obrolan, atau kunci sumber. Persempit cakupan ini jika transkripsi otomatis bersifat sensitif atau berbiaya tinggi.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Batas Waktu Pemahaman Audio (detik)`},help:{"v1-n8wc6c-3b":`Batas waktu default untuk permintaan pemahaman audio. Tingkatkan untuk rekaman panjang atau model transkripsi lokal yang lebih lambat.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Konkurensi Pemahaman Media`},help:{"v1-13kr9np-58":`Jumlah maksimum operasi pemahaman media yang berjalan bersamaan per giliran untuk seluruh tugas gambar, audio, dan video. Turunkan nilai ini pada penerapan dengan sumber daya terbatas agar CPU/jaringan tidak kelebihan beban.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Kebijakan Lampiran Pemahaman Gambar`},help:{"v1-11hofbw-3e":`Pilih lampiran gambar yang cocok untuk diproses. Proses hanya lampiran pertama kecuali analisis beberapa gambar memang diperlukan.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Aktifkan Pemahaman Gambar`},help:{"v1-1b2zw34-50":`Aktifkan pemahaman gambar agar gambar yang dilampirkan atau dirujuk dapat diinterpretasikan menjadi konteks tekstual. Nonaktifkan jika Anda memerlukan operasi khusus teks atau ingin menghindari biaya pemrosesan gambar.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Byte Maksimum Pemahaman Gambar`},help:{"v1-jwwpd1-3v":`Batas ukuran input gambar default untuk model yang dikonfigurasi dan dideteksi secara otomatis. Sesuaikan nilai ini dengan batas payload penyedia dan bandwidth deployment.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Karakter Maksimum Pemahaman Gambar`},help:{"v1-ebnxhk-3q":`Panjang maksimum deskripsi gambar default. Gunakan nilai yang lebih rendah untuk konteks ringkas atau nilai yang lebih tinggi untuk OCR dan analisis adegan yang mendetail.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Model Pemahaman Gambar Pilihan`},help:{"v1-1o2uwo6-3c":`Utamakan satu entri tools.media.models yang diberi tag kemampuan untuk pemahaman gambar sebelum menggunakan opsi cadangan kompatibel lainnya.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Prompt Pemahaman Gambar`},help:{"v1-1jdcu8b-3u":`Prompt pemahaman gambar default saat tidak ditimpa oleh suatu entri. Pastikan prompt ini deterministik jika pengguna hasilnya mengandalkan deskripsi yang konsisten.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Cakupan Pemahaman Gambar`},help:{"v1-tievo1-3s":`Batasi pemahaman gambar berdasarkan kanal, jenis obrolan, atau kunci sumber. Persempit cakupannya di kanal yang ramai atau tidak tepercaya untuk mengendalikan pemrosesan.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Batas Waktu Pemahaman Gambar (detik)`},help:{"v1-1wcm84x-31":`Batas waktu default untuk permintaan pemahaman gambar. Tingkatkan untuk gambar berukuran besar atau model visi lokal yang lebih lambat.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Model Bersama untuk Pemahaman Media`},help:{"v1-f34u65-47":`Daftar acuan model pemahaman media. Gunakan tag kapabilitas image, audio, atau video pada setiap entri agar setiap pipeline hanya memilih model cadangan yang kompatibel.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Kebijakan Lampiran Pemahaman Video`},help:{"v1-1qm1qrc-3e":`Pilih lampiran video yang cocok untuk diproses. Proses hanya lampiran pertama kecuali analisis beberapa video memang diinginkan.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Aktifkan Pemahaman Video`},help:{"v1-1ltx5gl-58":`Aktifkan pemahaman video agar klip dapat diringkas menjadi teks untuk penalaran dan respons lanjutan. Nonaktifkan jika pemrosesan video tidak sesuai kebijakan atau terlalu mahal untuk penerapan Anda.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Byte Maksimum Pemahaman Video`},help:{"v1-2mp77v-3v":`Batas ukuran input video default untuk model yang dikonfigurasi dan terdeteksi secara otomatis. Sesuaikan dengan batas payload penyedia dan bandwidth penerapan.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Karakter Maksimum Pemahaman Video`},help:{"v1-1j0x40b-3j":`Panjang maksimum default deskripsi video. Gunakan nilai lebih rendah untuk konteks ringkas atau nilai lebih tinggi untuk ringkasan adegan yang mendetail.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Model Pemahaman Video Pilihan`},help:{"v1-1cygq5k-3c":`Utamakan satu entri tools.media.models yang diberi tag kapabilitas untuk pemahaman video sebelum opsi cadangan kompatibel lainnya.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Prompt Pemahaman Video`},help:{"v1-ul2jx4-3r":`Prompt pemahaman video default saat entri tidak menggantinya. Pastikan prompt ini deterministik jika pihak yang menggunakannya mengandalkan ringkasan yang konsisten.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Cakupan Pemahaman Video`},help:{"v1-7gfrx3-3s":`Batasi pemahaman video berdasarkan kanal, jenis obrolan, atau kunci sumber. Persempit cakupan ini di kanal yang ramai atau tidak tepercaya untuk mengendalikan pemrosesan.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Batas Waktu Pemahaman Video (detik)`},help:{"v1-e8rzsy-33":`Batas waktu default untuk permintaan pemahaman video. Tingkatkan untuk klip yang lebih panjang atau model analisis lokal yang lebih lambat.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Daftar Tindakan Pesan yang Diizinkan`},help:{"v1-1iceqwa-5c":`Daftar global tindakan pesan yang diizinkan untuk alat pesan. Gunakan hanya jika seluruh lingkungan eksekusi harus menyediakan dan menerima rangkaian tindakan yang lebih terbatas; utamakan daftar izin per agen untuk agen publik atau agen dalam sandbox.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Aktifkan Siaran Pesan`},help:{"v1-1ms74z7-14":`Aktifkan tindakan siaran (default: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Izinkan Lintas Konteks (Antarpenyedia)`},help:{"v1-276qxo-2s":`Izinkan pengiriman lintas penyedia yang berbeda (default: true). Atur ke false untuk memblokir pengiriman pesan lintas penyedia.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Izinkan Lintas Konteks (Penyedia yang Sama)`},help:{"v1-1sg4x49-1z":`Izinkan pengiriman ke kanal lain dalam penyedia yang sama (default: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Penanda Lintas Konteks`},help:{"v1-1fg6jrp-1z":`Tambahkan penanda asal yang terlihat saat mengirim lintas konteks (default: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Awalan Penanda Lintas Konteks`},help:{"v1-eblsru-1p":`Awalan teks untuk penanda lintas konteks (mendukung "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Akhiran Penanda Lintas Konteks`},help:{"v1-1nk0jub-1p":`Akhiran teks untuk penanda lintas konteks (mendukung "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Profil Alat`},help:{"v1-h6k98q-5k":`Nama profil alat global yang digunakan untuk memilih kebijakan dasar alat yang telah ditentukan sebelum menerapkan pengaturan pengganti izin/larangan. Gunakan ini untuk menjaga konfigurasi lingkungan yang konsisten di seluruh agen dan pertahankan nama profil agar tetap sama.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Kebijakan Alat Sandbox`},help:{"v1-ea7awo-4k":`Pembungkus kebijakan alat untuk eksekusi agen dalam sandbox agar eksekusi sandbox dapat memiliki batas kemampuan tersendiri. Gunakan ini untuk menerapkan keamanan yang lebih ketat dalam konteks sandbox.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Kebijakan Izin/Larangan Alat Sandbox`},help:{"v1-ub701o-4t":`Kebijakan izin/larangan alat yang diterapkan saat agen berjalan dalam lingkungan eksekusi sandbox. Batasi kebijakan seminimal mungkin agar tugas sandbox tidak berkembang menjadi tindakan eksternal yang tidak diperlukan.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Visibilitas Alat Sesi`},help:{"v1-1vtq2rh-c5":`Mengontrol sesi mana yang dapat ditargetkan oleh sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all" sebagai default = semua sesi di Gateway, termasuk agen dan pengguna lain; "agent" = semua sesi dalam id agen saat ini; "self" = hanya sesi saat ini; "tree" = sesi saat ini + sesi subagen yang dibuat). Akses lintas agen aktif secara default dan cakupannya diatur oleh tools.agentToAgent; gunakan visibilitas yang lebih sempit untuk membatasi akses.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Kebijakan Alat Subagen`},help:{"v1-1xoug01-4z":`Pembungkus kebijakan alat untuk subagen yang dibuat guna membatasi atau memperluas ketersediaan alat dibandingkan dengan pengaturan default induk. Gunakan ini agar kemampuan agen yang didelegasikan tetap sesuai dengan tujuan tugas.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Kebijakan Izin/Penolakan Alat Subagen`},help:{"v1-7vxsbf-5d":`Kebijakan izin/penolakan alat yang diterapkan pada runtime subagen yang dibuat. Pertahankan cakupan ini agar lebih sempit daripada cakupan induk. Alat milik induk seperti progress_card selalu ditolak, termasuk melalui allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Kawanan`},help:{"v1-1q96vvs-45":`Orkestrasi subagen dalam mode pengumpul. Aktif secara default; atur ke false untuk menonaktifkannya. Izin alat tetap berlaku untuk agents_wait dan opsi pembuatan swarm.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Agen Default Swarm`},help:{"v1-p4alpg-2m":`Agen target default untuk pembuatan swarm yang tidak menyertakan agentId. Daftar subagen yang diizinkan tetap berlaku.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Aktifkan Swarm`},help:{"v1-1nnnrq9-2e":`Mengaktifkan subagen dalam mode pengumpul dan agents_wait. Aktif secara default; atur ke false untuk menonaktifkannya.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Anak Aktif Swarm per Grup`},help:{"v1-kfx6qp-1c":`Jumlah maksimum anak pengumpul yang aktif per grup swarm.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Anak Swarm yang Berjalan Bersamaan`},help:{"v1-1d46jtm-1s":`Jumlah maksimum anak pengumpul yang berjalan bersamaan per grup swarm.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Total Anak Swarm per Grup`},help:{"v1-1gc9vl1-1e":`Jumlah maksimum pengumpul yang dapat dibuat selama masa aktif setiap grup swarm.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Batas Waktu Tunggu Maksimum Swarm`},help:{"v1-bog18y-1g":`Batas waktu maksimum yang diterima oleh agents_wait, dalam detik.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Pencarian Alat`},help:{"v1-s0kx04-7y":`Ringkas katalog alat OpenClaw, MCP, dan klien yang besar. Runtime OpenClaw menggunakan Tool Search terstruktur secara otomatis jika tidak diatur; Code Mode yang aktif diprioritaskan dan Codex menggunakan pencarian bawaannya. Tetapkan false untuk menonaktifkannya, true untuk jembatan kode, atau gunakan bentuk objek untuk memilih mode.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Batas Waktu Kode Pencarian Alat`},help:{"v1-105r499-34":"Waktu maksimum dalam milidetik untuk satu eksekusi `tool_search_code`. Runtime membatasi nilai ke rentang 1s..60s yang didukung."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Aktifkan Pencarian Alat`},help:{"v1-1vm3hfr-4h":"Mengaktifkan Pencarian Alat. Saat aktif, OpenClaw menyembunyikan katalog alat yang besar di balik `tool_search_code` atau alat pencarian/deskripsi/pemanggilan terstruktur selama runtime tertanam berjalan."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Hasil Maksimum Pencarian Alat`},help:{"v1-7du4kh-32":`Jumlah maksimum hasil Pencarian Alat yang dapat diminta model. Runtime membatasi nilai ke rentang 1..50 yang didukung.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Antarmuka Pencarian Alat`},help:{"v1-jybcbe-7x":'Pilih antarmuka yang diakses model: "code" menyediakan `tool_search_code`; "tools" menyediakan alat cadangan terstruktur untuk pencarian/deskripsi/pemanggilan; "directory" menampilkan direktori alat terbatas, menyediakan sejumlah terbatas skema yang kemungkinan diperlukan atau wajib, dan menunda akses ke sisanya melalui pencarian/deskripsi/pemanggilan.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Hasil Default Pencarian Alat`},help:{"v1-1uchq7t-39":"Jumlah default hasil Pencarian Alat yang dikembalikan saat model tidak menentukan batas. Runtime membatasinya hingga `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Aktifkan Alat Rencana Terstruktur`},help:{"v1-1xgegme-4o":"Alat status terpadu `progress_card` untuk rencana persisten dan catatan naratif dalam sesi induk. Diaktifkan secara default; atur ke false untuk menonaktifkannya. Tidak pernah tersedia bagi subagen."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Alat Web`},help:{"v1-fpsy5-4y":`Pengelompokan kebijakan alat web untuk penyedia pencarian/pengambilan, batas, dan penyesuaian perilaku cadangan. Pastikan pengaturan yang diaktifkan selaras dengan ketersediaan kunci API dan kebijakan jaringan keluar.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL Cache Pengambilan Web (menit)`},help:{"v1-1hk89qp-17":`TTL cache dalam menit untuk hasil web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Aktifkan Alat Pengambilan Web`},help:{"v1-yrswld-1f":`Aktifkan alat web_fetch (pengambilan HTTP ringan).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Header Permintaan Pengambilan Web`},help:{"v1-16bjkv5-me":"Header permintaan tambahan yang dikirim bersama permintaan web_fetch langsung, misalnya header perutean gateway atau autentikasi. Setiap nilai yang dikonfigurasi dianggap sensitif dan disamarkan dalam konfigurasi yang ditampilkan serta rekaman debug. Nilai berupa string biasa, mendukung substitusi ${VAR} dan escape literal global $${VAR}, serta dikirim ke URL yang dipilih model. Entri divalidasi saat permintaan dibuat, bukan saat konfigurasi dimuat, sehingga nama yang tidak valid atau nilai yang tidak dapat dikirim akan dibuang dan dicatat dalam log, alih-alih menonaktifkan fitur; Accept, Accept-Language, User-Agent, dan header pembingkaian seperti Transfer-Encoding juga dibuang. Gunakan tools.web.fetch.userAgent untuk mengubah agen pengguna. Pengalihan lintas origin hanya mempertahankan header dalam daftar izin aman guarded-fetch, dan perubahan pada header yang benar-benar dikirim akan mempartisi cache pengambilan."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Jumlah Karakter Maksimum Pengambilan Web`},help:{"v1-12d1fw7-1d":`Jumlah karakter maksimum yang dikembalikan oleh web_fetch (dipotong).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Batas Mutlak Jumlah Karakter Pengambilan Web`},help:{"v1-cl2mf1-1v":`Batas mutlak untuk maxChars pada web_fetch (berlaku untuk konfigurasi dan pemanggilan alat).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Jumlah Pengalihan Maksimum Pengambilan Web`},help:{"v1-t6eak9-1h":`Jumlah pengalihan maksimum yang diizinkan untuk web_fetch (default: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Ukuran Unduhan Maksimum Pengambilan Web (byte)`},help:{"v1-q6ld9c-10":`Ukuran unduhan maksimum sebelum dipotong.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Penyedia Pengambilan Web`},help:{"v1-6pb3nv-v":`ID penyedia cadangan untuk pengambilan web.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Ekstraksi Readability untuk Pengambilan Web`},help:{"v1-19exqzx-2c":`Gunakan Readability untuk mengekstrak konten utama dari HTML (menggunakan pembersihan HTML dasar sebagai cadangan).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Kebijakan SSRF Pengambilan Web`},help:{"v1-qtn7zx-3c":`Pengaturan pengganti kebijakan SSRF dengan cakupan terbatas untuk web_fetch. Batasi cakupannya dan aktifkan hanya untuk lingkungan proksi jaringan lokal yang dikenal.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Nama Host yang Diizinkan untuk Pengambilan Web`},help:{"v1-1j9ctya-35":`Nama host persis atau literal IP yang diizinkan untuk web_fetch, termasuk target yang biasanya diblokir. Batasi daftar ini seminimal mungkin.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Izinkan Rentang Lokal Unik IPv6 untuk Pengambilan Web`},help:{"v1-1eyz55i-3b":`Izinkan Alamat Lokal Unik IPv6 (fc00::/7) untuk kompatibilitas dengan proksi IP palsu tepercaya seperti sing-box, Clash, atau Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Izinkan Rentang Tolok Ukur RFC 2544 untuk Pengambilan Web`},help:{"v1-u5asdb-2y":`Izinkan IP dalam rentang tolok ukur RFC 2544 (198.18.0.0/15) untuk kompatibilitas dengan proksi IP palsu seperti Clash atau Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Nama Host yang Diblokir untuk Pengambilan Web`},help:{"v1-1164vvk-66":`Pola nama host yang ditolak sebelum pemeriksaan DNS dan aturan izin pada setiap pengalihan web_fetch. Mendukung host yang cocok persis dan "*.example.com" khusus untuk subdomain; tambahkan "example.com" secara terpisah untuk memblokir domain utama. Jika kosong atau tidak diatur, tidak ada penolakan tambahan.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Izinkan Jaringan Privat untuk Pengambilan Web (Berbahaya)`},help:{"v1-2s6mv7-3t":`Mengizinkan web_fetch mengakses target jaringan privat dan internal. Biarkan nonaktif kecuali URL yang dipilih model tepercaya dalam penerapan ini.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Batas Waktu Pengambilan Web (detik)`},help:{"v1-1c3yfr4-16":`Batas waktu dalam detik untuk permintaan web_fetch.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent Pengambilan Web`},help:{"v1-s7pe8j-1e":`Ganti header User-Agent untuk permintaan web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Proksi Variabel Lingkungan Tepercaya untuk Pengambilan Web`},help:{"v1-1ypkqj7-54":`Rutekan web_fetch melalui proksi HTTP(S) tepercaya dari variabel lingkungan dan biarkan proksi menangani resolusi DNS. Aktifkan hanya jika proksi tersebut dikendalikan operator dan menerapkan kebijakan lalu lintas keluar setelah resolusi DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL Cache Pencarian Web (menit)`},help:{"v1-6trzlf-18":`TTL cache dalam menit untuk hasil web_search.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Aktifkan Alat Pencarian Web`},help:{"v1-n1cm4y-27":`Aktifkan web_search terkelola dan pencarian bawaan Codex opsional untuk model yang memenuhi syarat.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Jumlah Maksimum Hasil Pencarian Web`},help:{"v1-mrw7mi-z":`Jumlah hasil yang dikembalikan (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Domain yang Diizinkan untuk Codex`},help:{"v1-1cv4y44-43":`Daftar domain yang diizinkan untuk web_search bawaan Codex. Pada giliran yang menggunakan pencarian yang dihosting secara bawaan, daftar ini juga membatasi web_fetch terkelola; giliran yang menggunakan penyedia terkelola tidak terpengaruh.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Ukuran Konteks Pencarian Codex`},help:{"v1-antack-1u":`Petunjuk ukuran konteks pencarian bawaan Codex: "low", "medium", atau "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Aktifkan Pencarian Web Bawaan Codex`},help:{"v1-ek2jzd-1k":`Aktifkan pencarian web bawaan Codex untuk model yang mendukung Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Mode Pencarian Web Codex`},help:{"v1-1ahyq9f-32":`Preferensi pencarian web bawaan Codex: "cached" (default; giliran Codex tanpa pembatasan akan menggunakan "live") atau "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Kota Pengguna Codex`},help:{"v1-1y95orp-1d":`Perkiraan kota yang dikirim ke pencarian web bawaan Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Negara Pengguna Codex`},help:{"v1-1xkm5ms-1g":`Perkiraan negara yang dikirim ke pencarian web bawaan Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Wilayah Pengguna Codex`},help:{"v1-lhar02-1l":`Perkiraan wilayah/negara bagian yang dikirim ke pencarian web bawaan Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Zona Waktu Pengguna Codex`},help:{"v1-fgv9fh-1h":`Perkiraan zona waktu yang dikirim ke pencarian web bawaan Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Penyedia Pencarian Web`},help:{"v1-10omglr-1x":`ID penyedia pencarian. Dideteksi otomatis dari kunci API yang tersedia jika tidak diisi.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Batas Waktu Pencarian Web (detik)`},help:{"v1-i0egvw-17":`Batas waktu dalam detik untuk permintaan web_search.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transkrip`},help:{"v1-1i0sc09-66":`Pengaturan inti pengambilan transkrip untuk catatan rapat, alat agen yang mendukung perekaman, dan sumber rapat langsung dengan mulai otomatis yang dikonfigurasi. Plugin rapat menyimpan catatan secara permanen secara default; atur enabled ke false untuk menonaktifkannya secara global.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Sumber Transkrip dengan Mulai Otomatis`},help:{"v1-1mzsl79-5s":`Sumber transkrip langsung yang dikelola secara otomatis sejak gateway dimulai. Setiap entri diaktifkan dengan mencantumkannya; hapus entri untuk menonaktifkan sumber tersebut. Sumber mengambil transkrip secara terus-menerus kecuali whenOccupied diaktifkan.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`ID Akun Transkrip`},help:{"v1-6g2kjj-4b":`Pengenal akun penyedia atau ruang kerja opsional untuk sumber transkrip yang memerlukan pembedaan akun. Gunakan format ID akun yang didokumentasikan oleh penyedia.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`ID Kanal Transkrip`},help:{"v1-1lk9d5o-4u":`ID kanal penyedia untuk sumber transkrip langsung, seperti kanal suara Discord atau kanal huddle Slack. Verifikasi makna ID khusus penyedia sebelum mengaktifkan mulai otomatis.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`ID Guild Discord`},help:{"v1-fyfgnk-4l":`ID guild Discord opsional untuk sumber transkrip suara Discord. Konfigurasikan ini dengan channelId yang sesuai jika penyedia memerlukan pencarian kanal suara dalam lingkup guild.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`URL Rapat Transkrip`},help:{"v1-1xtt9ci-4f":`URL rapat opsional untuk penyedia yang bergabung melalui URL, bukan ID kanal. Gunakan hanya tautan rapat tepercaya karena fitur mulai otomatis dapat bergabung dan merekam rapat tersebut.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`ID Penyedia Sumber Transkrip`},help:{"v1-1uur06p-3s":`ID penyedia sumber transkrip, seperti penyedia suara Discord atau penyedia huddle Slack di masa mendatang. Gunakan ID persis yang disediakan oleh plugin penyedia.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`ID Sesi Transkrip`},help:{"v1-xyo4x5-5o":`ID sesi transkrip tetap yang opsional untuk sumber mulai otomatis ini. Diabaikan jika whenOccupied bernilai true. Biarkan tidak diatur agar ID dibuat otomatis, kecuali Anda memerlukan pemilih harian yang tetap dan dapat menghindari benturan ID pada hari yang sama.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Judul Transkrip`},help:{"v1-ycjnmp-5y":`Judul opsional untuk perekaman transkrip mendatang. Mengubah judul saja akan membiarkan perekaman saat ini tetap berjalan tanpa mengubah judul yang telah ditetapkan atau catatan yang tersimpan. Perubahan sumber lainnya tetap mengikuti penanganan mulai ulang seperti biasa.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Perekaman Transkrip Saat Ada Peserta`},help:{"v1-34jid4-78":`Mulai sesi transkrip baru setiap kali ada peserta manusia di sumber dan hentikan sesi (serta buat catatan) setelah peserta manusia terakhir keluar. Memerlukan penyedia yang melaporkan keberadaan peserta, seperti discord-voice. Default: false (rekam terus-menerus sejak Gateway dimulai).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transkrip Diaktifkan`},help:{"v1-fyqqr0-6d":`Mengaktifkan catatan rapat otomatis yang tersimpan secara persisten, alat transkrip agen, dan sumber mulai otomatis yang telah dikonfigurasi. Default: true. Tetapkan false untuk menonaktifkan penyimpanan persisten dan alat tersebut; mode transkripsi rapat yang dipilih secara eksplisit tetap menyimpan bagian akhir transkrip langsung dalam batas tertentu.`}},tts:{label:{"v1-bmxkk9-e":`Teks ke Ucapan`},help:{"v1-1o27tk2-4n":`Kebijakan teks ke ucapan untuk membacakan balasan agen pada antarmuka suara atau audio yang didukung. Biarkan nonaktif kecuali pemutaran suara merupakan bagian dari alur kerja operator/pengguna Anda.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Persona TTS`},help:{"v1-1r0opcb-29":`ID persona TTS default. Preferensi persona TTS lokal dapat menggantikan pengaturan ini untuk setiap host.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Persona TTS`},help:{"v1-19aybhl-2l":`Persona TTS bernama yang menentukan identitas suara yang konsisten beserta pengikatan ucapan khusus penyedia.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Persona TTS`},help:{"v1-10s52ah-2l":`Satu persona TTS. Gunakan pengikatan khusus penyedia untuk menentukan suara/model dan templat prompt secara tepat.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Pengikatan Penyedia untuk Persona TTS`},help:{"v1-993jop-3e":`Pengikatan persona TTS khusus penyedia dengan ID penyedia suara sebagai kunci. Pengaturan ini digabungkan dengan tts.providers dan menimpa nilai yang sama untuk persona aktif.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Pengaturan Penyedia TTS`},help:{"v1-1k80nl4-4y":`Pengaturan TTS khusus penyedia dengan ID penyedia suara sebagai kunci. Gunakan ini sebagai pengganti kunci tingkat teratas khusus penyedia bawaan agar plugin suara tetap terpisah dari skema konfigurasi inti.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Konfigurasi Penyedia TTS`},help:{"v1-dwapva-3d":`Konfigurasi TTS khusus penyedia untuk satu ID penyedia suara. Batasi cakupan kolom pada plugin yang memiliki penyedia tersebut.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Kunci API Penyedia TTS`},help:{"v1-1m2fj0i-2o":`Kunci API penyedia yang digunakan oleh penyedia suara tersebut saat pluginnya memerlukan akses TTS terautentikasi.`}},tui:{label:{"v1-c8hus1-b":`UI Terminal`},help:{"v1-1fg9vw2-3s":`Pengaturan tampilan UI terminal. Gunakan bagian ini untuk preferensi tampilan khusus terminal tanpa mengubah perilaku Gateway atau UI lainnya.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Footer UI Terminal`},help:{"v1-6e12l3-3k":`Pengaturan tampilan footer UI terminal. Pastikan konteks opsional tetap ringkas agar informasi sesi, model, tujuan, dan token tetap mudah dibaca.`}},ui:{label:{"v1-ye4dff-2":`UI`},help:{"v1-dt1924-42":`Pengaturan tampilan UI untuk aksen dan preferensi tampilan operator. Gunakan ini untuk menyesuaikan keterbacaan tanpa mengubah perilaku saat dijalankan.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Warna Aksen Pengguna`},help:{"v1-16klzws-4z":`Aksen Control UI: #RRGGBB untuk warna kustom, atau 'theme' untuk palet tema yang dipilih. Mengesampingkan ui.seamColor; kosongkan untuk mewarisi warna sambungan yang dikonfigurasi atau warna bawaan tema.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Warna Aksen`},help:{"v1-14q3r4h-4g":`Warna aksen utama yang digunakan pada antarmuka untuk penekanan, lencana, dan penanda identitas visual. Gunakan nilai berkontras tinggi yang tetap terbaca pada tema terang maupun gelap.`}},update:{label:{"v1-k12u1x-7":`Pembaruan`},help:{"v1-11c5k8v-5c":`Perilaku saluran pembaruan dan pemeriksaan saat memulai untuk menjaga versi runtime OpenClaw tetap terkini. Gunakan saluran konservatif di lingkungan produksi dan saluran yang lebih eksperimental hanya di lingkungan terkendali.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Pembaruan Otomatis Diaktifkan`},help:{"v1-49xs2h-3c":`Aktifkan pembaruan otomatis di latar belakang untuk instalasi paket stable dan beta; extended-stable tidak pernah diterapkan secara otomatis (bawaan: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Saluran Pembaruan`},help:{"v1-lqtdvf-5b":`Saluran pembaruan untuk instalasi git + npm ("stable", "extended-stable", "beta", atau "dev"). extended-stable hanya tersedia untuk paket: instalasi hanya dilakukan di latar depan, dengan petunjuk opsional yang hanya dapat dibaca saat memulai.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Pemeriksaan Pembaruan Saat Memulai`},help:{"v1-qy3q9g-5v":`Memeriksa pembaruan saat Gateway dimulai, termasuk petunjuk extended-stable yang hanya dapat dibaca (default: true). Atur ke false untuk menonaktifkan pemeriksaan dan penerapan pembaruan otomatis Gateway dan node headless, serta ping pembaruan anonim.`}},voicewake:{label:{"v1-txt1wb-a":`Aktivasi suara`}},web:{label:{"v1-1ae9z56-b":`Saluran Web`}},wizard:{label:{"v1-28jonk-h":`Preferensi Penyiapan`},help:{"v1-14jh6rm-3b":`Preferensi penyiapan milik pengguna. Riwayat panduan penyiapan dan status konfirmasi milik mesin disimpan dalam basis data status bersama.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Akses Penemuan Penyiapan`},help:{"v1-1nqxt0w-38":`Persetujuan penemuan untuk penyiapan terpandu: "full" memindai tanpa meminta konfirmasi, sedangkan "guarded" meminta izin sebelum memeriksa aplikasi lokal.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Rekomendasi Aplikasi Penyiapan`},help:{"v1-ub8uoi-30":`Mengontrol apakah penyiapan terpandu boleh menggunakan label aplikasi yang terinstal untuk merekomendasikan plugin dan keterampilan yang relevan.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Stempel Waktu Eksekusi Terakhir Panduan`},help:{"v1-1y0fbk-1k":`Stempel waktu eksekusi panduan terakhir yang berhasil disimpan.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Perintah Eksekusi Terakhir Panduan`},help:{"v1-x2pfkk-15":`Perintah yang memanggil eksekusi panduan terakhir.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit Eksekusi Terakhir Panduan`},help:{"v1-h0jkmt-1i":`Commit kode sumber yang digunakan oleh eksekusi panduan pengembangan terakhir.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Mode Eksekusi Terakhir Panduan`},help:{"v1-16508qy-1r":`Menunjukkan apakah eksekusi panduan terakhir menargetkan penyiapan "local" atau "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Versi Eksekusi Terakhir Panduan`},help:{"v1-1tr4z9d-19":`Versi OpenClaw yang digunakan oleh eksekusi panduan terakhir.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Stempel Waktu Konfirmasi Keamanan Panduan`},help:{"v1-86i182-2a":`Stempel waktu konfirmasi keamanan penyiapan, yang disimpan bersama konfigurasi target.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Akselerasi Worktree`},help:{"v1-9es3gc-4r":`Gunakan akselerasi sistem berkas untuk worktree terkelola baru jika didukung (default: true). Tetapkan ke false untuk menggunakan checkout Git dan penyalinan berkas biasa. Hanya berlaku untuk worktree baru.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Direktori Akar Worktree`},help:{"v1-1tgti9j-5d":`Direktori global untuk worktree terkelola baru. Gunakan jalur absolut atau ~ untuk direktori beranda Anda; defaultnya adalah <state-dir>/worktrees. Worktree yang sudah ada tetap menggunakan jalur yang tercatat saat pengaturan ini berubah.`}}}}})))()}export{n,t};